const NOTES_SITE = {"lq-amaretto":{"h":"L'amaretto doit son nom à l'amertume délicate de l'amande, l'italien 'amaro' signifiant amer, le diminutif évoquant une amertume tendre plutôt que mordante. Les confiseurs lombards mariaient de longue date le noyau d'abricot ou l'amande amère au sucre et à l'eau-de-vie, parfumant l'ensemble de safran et de vanille pour adoucir l'âpreté. Cette liqueur prolonge la tradition des ratafias d'amandes que l'on offrait jadis aux hôtes de marque.","p":"L'amande amère était réputée stomachique et cordiale, prise en très petite quantité après les repas lourds. On se gardera toutefois d'en abuser : le noyau et l'amande amère renferment un principe qui libère de l'acide cyanhydrique, et seule une dose mesurée, longuement macérée puis filtrée, en fait un agrément et non un péril.","c":"Concasser les amandes amères au dernier moment pour libérer leur parfum, et n'en mettre qu'une faible part au regard de l'ensemble. Servir frais mais non glacé, après une longue garde au frais qui arrondit l'âpreté.","d":"« Peu d'amande au flacon mûri, grand parfum sans nul souci. »"},"lq-amaretto-cremino":{"h":"Le 'cremino' adoucit l'amaretto en l'unissant au lait, à la manière des crèmes de liqueur que l'on préparait dans les offices pour les dames et les fins de banquet. Le lait y voile l'amertume de l'amande et lui prête une robe nacrée, prolongeant l'usage ancien des laits parfumés aux noyaux. C'est une douceur de table plus qu'un alcool de cave, tenant du ratafia et du lait d'amande sucré.","p":"On prêtait à ces crèmes lactées une vertu adoucissante pour l'estomac échauffé, l'amande amère y demeurant réputée stomachique à très faible dose. Le noyau d'amande amère portant un principe cyanogène, on n'en glisse qu'une pincée bien macérée, et l'on tient le flacon hors de portée des enfants.","c":"Employer un lait entier bien frais et le mêler à l'alcool sans le brusquer pour éviter qu'il ne tranche. Conserver au froid, agiter avant de verser, et consommer dans les semaines qui suivent car le lait n'attend pas.","d":"« Lait sur l'amande versé sans hâte, garde au frais qui jamais ne se gâte. »"},"lq-arancello":{"h":"L'arancello est le pendant orangé du limoncello, né des vergers d'agrumes du Midi italien où l'on n'a jamais laissé perdre un zeste parfumé. L'oranger, venu d'Orient par les routes des califes, fut d'abord cultivé pour son fruit amer avant que l'orange douce ne gagne les tables. De son écorce gorgée d'huiles essentielles, les ménagères tiraient une liqueur ambrée que l'on offrait au visiteur.","p":"Le zeste d'orange était tenu pour tonique et digestif, son amertume aromatique réputée ouvrir l'appétit et réconforter après un repas copieux. On lui prêtait aussi une vertu apaisante, l'arôme de l'écorce passant pour réjouir l'esprit.","c":"Choisir des oranges non traitées et ne prélever que le zeste coloré, en évitant la peau blanche qui apporte une amertume rêche. Servir bien frais en fin de repas, après un repos qui marie le zeste au sucre.","d":"« Du verger l'écorce dorée vaut mieux gardée que jetée. »"},"lq-arancello-cremino":{"h":"Cette version crémeuse de l'arancello unit le zeste d'orange au lait, dans la lignée des crèmes d'office où l'on noyait les agrumes dans une douceur laitée. L'orange, longtemps fruit de luxe réservé aux tables fortunées, prenait ainsi une robe veloutée digne des desserts de fête. Le lait tempère le mordant du zeste et en fait une liqueur de dessert plus que de digestif.","p":"Le zeste d'orange demeurait réputé digestif et tonique, et l'on disait du lait qu'il en adoucissait l'ardeur pour les estomacs délicats. C'était surtout une gourmandise réconfortante que l'on servait aux convives en fin de repas.","c":"Prélever le zeste sans la peau blanche, puis mêler doucement le lait entier afin qu'il ne tourne pas au contact de l'alcool. Tenir au froid et boire dans les semaines suivant la préparation, car la crème ne se garde guère.","d":"« Orange et lait en bon ménage, douceur de table sans orage. »"},"lq-limoncello-cremino":{"h":"Le crémino de limoncello descend des limoncellos de la côte amalfitaine, où le citron parfumé règne sur les terrasses en gradins depuis des siècles. Le citron, apporté en Méditerranée par les marchands et les jardiniers d'Orient, y devint emblème de fraîcheur et de soleil. En le voilant de lait, on en fait une crème onctueuse, héritière des laits d'agrumes des vieilles cuisines.","p":"Le zeste de citron était réputé rafraîchissant et tonique, propre à réveiller l'appétit et à dissiper la pesanteur des repas. Le lait, disait-on, en arrondissait l'acidité pour le rendre aimable aux palais sensibles.","c":"N'employer que le zeste jaune de citrons non traités et y mêler un lait entier bien frais sans le faire bouillir. Garder au froid et déguster glacé, dans un délai court car le lait ne souffre pas l'attente.","d":"« Citron voilé de lait léger, plaisir d'été vite à manger. »"},"lq-anisette":{"h":"L'anisette tire son charme de l'anis vert, semence aromatique chère aux Anciens, que les Romains glissaient déjà dans les gâteaux servis en fin de noces pour faciliter la digestion. Sa saveur réglissée, rehaussée de coriandre, de cannelle et de macis, en fit l'une des liqueurs de dame les plus prisées des cabinets du passé. On la sirotait à petites gorgées, parfois noyée d'un peu d'eau qui la troublait d'un voile laiteux.","p":"L'anis vert était tenu pour carminatif et stomachique, réputé chasser les vents et apaiser les digestions lentes. On lui prêtait aussi une vertu adoucissante pour la gorge et un effet rassérénant sur les humeurs.","c":"Préférer des graines d'anis bien parfumées et fraîches, l'arôme s'éventant avec le temps. Servir frais, en petite quantité, additionné au besoin d'un trait d'eau froide qui en révèle le bouquet.","d":"« Anis au soir, ventre en repos ; au matin clair, cœur dispos. »"},"lq-amere-feuilles":{"h":"Cette amère de feuilles rassemble le ban des herbes de jardin et de garrigue, romarin, sauge, laurier et camomille, à la manière des élixirs que les apothicaires composaient de tout ce qui verdoyait au pied du mur. Le romarin, herbe du souvenir et de fidélité, brûlait jadis dans les chambres de malades pour assainir l'air. Une telle liqueur tient de l'eau de senteur autant que du digestif de famille.","p":"Le romarin et la sauge étaient réputés toniques et stomachiques, propres à réveiller les esprits et à soutenir la digestion ; la camomille passait pour calmer les estomacs irrités. On veillera à mesurer la sauge, dont l'usage prolongé et immodéré n'était pas tenu pour anodin par les anciens herboristes.","c":"Cueillir les feuilles par temps sec et les employer fraîches pour un parfum plus vif. Filtrer avec soin pour ôter toute herbe en suspension, et servir frais en digestif après un repos de plusieurs semaines.","d":"« Herbe du mur cueillie au sec vaut tout l'or de l'apothicaire grec. »"},"lq-anis-brizard":{"h":"Cette anisette à la façon d'une vieille maison angevine évoque les liqueurs claires que l'on distillait pour adoucir les fins de soirée. L'anis y règne, épaulé de badiane venue d'Extrême-Orient et de graine de fenouil, trio aromatique qui partage la même âme réglissée. La vanille et le citron y apportent une rondeur de liqueur de salon, héritière des anisettes des ports atlantiques.","p":"L'anis et le fenouil étaient réputés carminatifs et digestifs, recommandés contre les lourdeurs et les vents après les repas de fête. La badiane, dite anis étoilé, passait pour réchauffer doucement l'estomac et parfumer l'haleine.","c":"Doser l'essence d'anis avec retenue, car sa puissance domine vite l'ensemble. Un trait de jus de citron avive le bouquet ; servir frais après filtration soignée et un repos qui fond les arômes.","d":"« Anis, fenouil et badiane à trois, font la liqueur du fin gosier de roi. »"},"lq-ecorce-chene":{"h":"L'écorce de chêne, riche en tanins, servait depuis fort longtemps à tanner les cuirs et à raffermir les chairs, avant d'entrer dans les liqueurs amères des campagnes. Le chêne, arbre des druides et des serments, prêtait son écorce aux remèdes de l'apothicaire comme aux fûts du vigneron. Cette liqueur en tire une astringence boisée qui rappelle le vin longuement gardé en barrique.","p":"L'écorce de chêne était réputée astringente et tonique, employée en décoction contre les flux et pour resserrer les tissus relâchés. On lui prêtait, à dose modérée, une vertu fortifiante ; son amertume tannique invite cependant à n'en boire qu'un petit verre.","c":"Choisir une écorce saine, prélevée sur jeune bois et bien séchée, et ne pas prolonger la macération au point de rendre la liqueur trop âpre. Servir à petite dose, fraîche, après une longue garde qui assouplit le tanin.","d":"« Sous l'écorce du vieux chêne dort la force qui mène. »"},"lq-bourgeons-sapin":{"h":"La liqueur de bourgeons de sapin descend des sirops et eaux-de-vie des montagnards, qui récoltaient au printemps les jeunes pousses tendres d'un vert acide. Dans les vallées alpines et vosgiennes, ces bourgeons parfumaient sirops contre la toux et liqueurs de fête, mariant la résine et la fraîcheur du sous-bois. On les cueillait tôt, alors qu'ils sont encore moelleux et gorgés de sève.","p":"Les bourgeons de sapin étaient réputés balsamiques et pectoraux, employés pour adoucir la gorge et dégager la poitrine aux saisons froides. On leur prêtait une vertu tonique et assainissante, propre à réconforter le voyageur des cimes.","c":"Cueillir les bourgeons jeunes et tendres, d'un vert clair, avant qu'ils ne durcissent. La macération est brève pour garder leur fraîcheur résineuse ; filtrer aussitôt et servir frais.","d":"« Bourgeon d'avril cueilli matin, met le printemps au fond du brin. »"},"lq-douce-miel":{"h":"La liqueur douce au miel renoue avec les hydromels et les vins miellés que l'on buvait bien avant que la canne et la betterave ne donnent le sucre. Le miel, nourriture des dieux et présent des abeilles, fut le premier édulcorant de l'humanité et le cœur de maint breuvage de fête. Relevée d'un soupçon de vanille, cette liqueur prolonge la tradition des boissons miellées des noces et des veillées.","p":"Le miel était tenu pour adoucissant et pectoral, recommandé contre les maux de gorge et les refroidissements, et passait pour réconforter les forces. On le disait baume des humeurs et ami du sommeil quand on le prenait au soir.","c":"Choisir un miel parfumé, de toutes fleurs ou d'acacia, et le délayer à froid pour préserver son arôme. Laisser longuement reposer afin que la vanille s'unisse au miel, puis servir frais ou à température de cave.","d":"« Miel au flacon longuement mûri, console au soir l'homme attendri. »"},"lq-abricots":{"h":"La liqueur d'abricots célèbre ce fruit doré venu d'Asie centrale par les jardins de Perse, dont le nom même garde la trace d'un voyage à travers l'arabe et le latin. Mûri au soleil du Roussillon et de la vallée du Rhône, l'abricot gorgé de sucre faisait les confitures, les ratafias et les eaux-de-vie de l'arrière-saison. Sa chair fondante donne une liqueur ambrée au parfum de verger chaud.","p":"L'abricot bien mûr était réputé rafraîchissant et nourrissant, ami du teint et des humeurs douces. On se gardait en revanche de croquer son amande de noyau, dont l'amertume trahit un principe cyanogène à manier avec prudence.","c":"Ne choisir que des fruits bien mûrs, parfumés et sans meurtrissure, qui donneront le plus de saveur. On peut glisser quelques noyaux pour relever d'une note amandée, mais en très petit nombre ; servir frais après une bonne garde.","d":"« Abricot mûr au soleil pris, parfume au verre le pays. »"},"lq-abricots-secs":{"h":"Faite d'abricots séchés, cette liqueur perpétue l'art ancien de garder les fruits de l'été pour les soirs d'hiver, le séchage concentrant le sucre et le parfum. Sur les claies et les toits ensoleillés, on faisait sécher l'abricot comme on le fit de tout temps sur les chemins de l'Orient. Rehaussée d'orange et de badiane, elle prend une rondeur épicée d'autant plus riche que le fruit s'est confit au soleil.","p":"L'abricot séché était tenu pour nourrissant et adoucissant, et la badiane qui l'accompagne passait pour digestive et carminative. L'ensemble réchauffe doucement l'estomac, à la manière des fruits confits de la fin des banquets.","c":"Choisir des abricots secs moelleux et non sulfurés, qui se réhydratent dans l'alcool en libérant tout leur sucre. Le zeste d'orange et la badiane veulent la main légère ; servir frais après une longue macération.","d":"« Fruit séché au soleil d'antan rend en hiver l'été d'avant. »"},"lq-achillee":{"h":"L'achillée millefeuille porte dans son nom celui d'Achille, le héros qui, dit-on, en aurait pansé les plaies de ses soldats, d'où ses vieux surnoms d'herbe aux coupures et d'herbe au charpentier. Ses fines feuilles découpées et ses ombelles blanches peuplent les prés et les bords de chemin depuis toujours. On en tirait tisanes, vulnéraires et liqueurs amères des campagnes.","p":"L'achillée était réputée tonique, vulnéraire et apéritive, employée pour resserrer les plaies et soutenir les digestions paresseuses. Son amertume aromatique, tenue pour bienfaisante à petite dose, invite à n'en user que par verres modestes.","c":"Cueillir les fleurs en plein épanouissement, par temps sec, loin des chemins poussiéreux. Un zeste de citron en avive l'amertume ; filtrer finement et servir frais après quelques semaines de repos.","d":"« Herbe d'Achille au pré cueillie, ferme la plaie et l'appétit rallie. »"},"lq-amandes":{"h":"L'amandier, venu d'Asie centrale et du Levant, accompagna les caravanes et les colons grecs jusqu'aux rivages de la Méditerranée, où il devint l'un des premiers arbres à fleurir, dès la fin de l'hiver. Son nom remonte au grec 'amygdalê', et ses fruits, broyés et adoucis à l'eau de fleur d'oranger, donnaient déjà aux apothicaires d'autrefois ces 'laits d'amande' que l'on prêtait aux convalescents. L'amande douce parfumait les massepains et les dragées des noces, tandis que l'amère, plus rare, n'entrait qu'à pincée pour relever le bouquet.","p":"Le lait d'amande douce était tenu pour adoucissant et nourrissant, propre à apaiser les gorges irritées. L'amande amère, en revanche, renferme un principe libérant du cyanure : on n'en use qu'à très petite dose, jamais crue en quantité.","c":"Ne mêler que quelques amandes amères pour beaucoup d'amandes douces, afin d'obtenir le parfum sans le péril. Filtrer soigneusement la pulpe au linge fin et laisser reposer la liqueur quelques semaines pour qu'elle s'arrondisse.","d":"« Amande douce au verre, amère à la pincée : qui force la mesure s'en va mal reposé. »"},"lq-aneth":{"h":"L'aneth, cousin du fenouil, croissait déjà dans les jardins de l'Égypte et de la Grèce antiques, où l'on prisait ses graines au goût d'anis et de carvi. Son nom dériverait du grec 'anêthon', et les anciens jardiniers le tenaient pour une herbe apaisante, glissée jusque sous l'oreiller des enfants agités. On le retrouve dans les conserves du Nord et les saumures, où sa graine parfume vinaigres et eaux-de-vie.","p":"La graine d'aneth était réputée carminative et digestive, recommandée contre les lourdeurs de table et les coliques venteuses. On lui prêtait aussi la vertu d'apaiser le hoquet et de favoriser un sommeil tranquille.","c":"Concasser légèrement les graines avant la macération pour libérer leurs huiles. Servir cette liqueur fraîche en fin de repas, sucrée avec retenue afin de laisser parler l'arôme.","d":"« Graine d'aneth après ripaille, et le ventre point ne tiraille. »"},"lq-artichauts":{"h":"L'artichaut, cardon domestiqué sur le pourtour méditerranéen, fit les délices des tables italiennes de la Renaissance avant de gagner les potagers de France. Son amertume franche, logée dans les feuilles et la tige, inspira nombre d'amers et d'apéritifs de jadis. Les jardiniers le tenaient pour un légume de seigneur, lent à mûrir mais généreux à qui sait l'attendre.","p":"Les feuilles d'artichaut étaient réputées amies du foie et de la bile, propres à soutenir la digestion des chères grasses et à réveiller un appétit endormi. On en tirait des décoctions amères que l'on buvait avant le repas pour ouvrir l'estomac.","c":"Préférer les feuilles et tiges bien vertes, récoltées avant la pleine floraison, lorsque l'amertume est la plus nette. Sucrer modérément : c'est l'amertume qui fait ici tout le mérite de la liqueur.","d":"« L'artichaut amer en son verre ouvre la table et désaltère. »"},"lq-bananes":{"h":"Originaire des forêts d'Asie tropicale, la banane voyagea d'île en île par l'Inde et l'Afrique avant que les navigateurs ne la portent aux Antilles et au Nouveau Monde. Longtemps fruit de curiosité sur les tables d'Europe, elle n'y devint familière qu'avec les flottes marchandes et les serres chaudes. Sa chair fondante et sucrée se prêta vite aux conserves à l'eau-de-vie et aux liqueurs des comptoirs lointains.","p":"La banane passait pour un fruit nourrissant et réconfortant, propre à rassasier et à redonner des forces aux corps fatigués. On la tenait pour douce à l'estomac et bienfaisante aux esprits affaiblis.","c":"Choisir des bananes encore un peu fermes et peu mûres, qui tiennent mieux à la macération et ne tournent pas au fade. Une gousse de vanille fendue rehausse leur rondeur ; filtrer avec soin car leur pulpe trouble volontiers la liqueur.","d":"« Banane à peine mûre au bocal, fait la liqueur sans qu'elle s'avachisse. »"},"lq-celeri":{"h":"Le céleri descend de l'ache sauvage des marais, plante odorante que Grecs et Romains tressaient en couronnes pour leurs vainqueurs et leurs morts avant d'en faire un légume de bouche. Patiemment adouci par les jardiniers, son pied charnu et ses tiges parfumées gagnèrent les potées et les courts-bouillons. Sa saveur poivrée et verte, mariée à la coriandre et à la badiane, donne une liqueur d'herbe singulière.","p":"Le céleri était réputé tonique, diurétique et apéritif, propre à stimuler l'appétit et à dégager les humeurs paresseuses. On lui prêtait aussi de réchauffer le sang et de fortifier les natures languissantes.","c":"Employer des tiges bien fraîches et croquantes, coupées menu pour livrer tout leur arôme. La macération doit rester courte, sous peine que le vert ne tourne à l'amer ; servir bien frais à l'heure de l'apéritif.","d":"« Tige de céleri en sa fiole réveille l'appétit qui sommeille. »"},"lq-chataignes":{"h":"La châtaigne, fruit du châtaignier que les Romains répandirent à travers la Gaule, fut longtemps l'arbre à pain des pays de montagne, nourrissant villages entiers durant les hivers rudes. On la séchait, on la moulait en farine, on la confisait au miel ; l'Ardèche, la Corse et le Limousin en firent leur orgueil. Sa chair douce et farineuse, mariée à la vanille, donne une liqueur ronde aux airs de veillée d'automne.","p":"La châtaigne était tenue pour nourrissante et fortifiante, soutien des corps laborieux et des estomacs robustes. On la disait propre à réchauffer et à rassasier durablement ceux qui peinaient au froid.","c":"Choisir des châtaignes bien pleines et saines, entaillées et cuites avant de macérer pour livrer leur douceur. Laisser reposer longtemps, plusieurs mois durant, car cette liqueur gagne en velours avec la patience.","d":"« Châtaigne au bocal lentement mûrie, vaut tout l'or des veillées d'automne. »"},"lq-chevrefeuille":{"h":"Le chèvrefeuille, liane des haies et des lisières, embaume les soirées d'été d'un parfum de miel que butinent papillons crépusculaires et abeilles. Son nom évoque les chèvres friandes de son feuillage, et les anciens en faisaient l'emblème des liens tendres, tant ses tiges s'enlacent à ce qu'elles rencontrent. On en cueille les fleurs au point de leur épanouissement pour en capter le suc parfumé.","p":"Les fleurs de chèvrefeuille étaient réputées adoucissantes et pectorales, employées en infusion contre les maux de gorge et les toux d'hiver. Mieux vaut s'en tenir aux fleurs, car les baies du chèvrefeuille sont tenues pour irritantes et ne se mangent pas.","c":"Cueillir les fleurs au matin, fraîchement ouvertes, lorsque le parfum est à son comble, et les employer sans tarder. Sucrer avec mesure pour ne pas masquer cet arôme délicat et fugace.","d":"« Fleur de chèvrefeuille au soir cueillie tient le parfum d'un été qui s'oublie. »"},"lq-coco":{"h":"La noix de coco, fruit du cocotier des rivages tropicaux, voyagea au gré des courants et des navigateurs, échouant sur des plages lointaines où elle prenait racine d'elle-même. Les marins la nommaient 'noix des Indes' et en tiraient eau, lait et chair pour les longues traversées. Mariée au rhum, à la cannelle et au citron vert, elle compose une crème onctueuse aux accents des îles.","p":"Le lait de coco était tenu pour rafraîchissant et nourrissant, réconfort des gosiers desséchés sous les climats brûlants. On lui prêtait une douceur bienfaisante aux corps épuisés par la chaleur.","c":"Préférer un lait de coco riche et bien crémeux pour donner du corps à la liqueur. Conserver cette crème au frais et la boire dans un délai raisonnable, car le lait n'aime guère la longue garde ; agiter avant de servir.","d":"« Coco fondu dans le rhum des îles, et l'hiver soudain s'exile. »"},"lq-epices":{"h":"Cet assemblage de graines aromatiques, anis, badiane, coriandre, cumin, carvi, fenouil et genièvre, rassemble en une seule fiole tout le trésor des épiciers d'autrefois, ces marchands dont les comptoirs sentaient le Levant et la route des caravanes. Chaque graine y apporte sa note, de l'anis sucré au genièvre résineux, en un concert que les anciens nommaient 'eau d'épices'. De telles liqueurs aromatiques tenaient lieu de digestif et de cordial dans les officines.","p":"Ce concours de graines était réputé éminemment carminatif et stomachique, propre à dissiper les vents et à seconder les digestions difficiles. On le buvait à petits verres après les repas de fête pour réchauffer et apaiser l'estomac.","c":"Concasser grossièrement les graines avant macération pour en libérer les huiles, sans pour autant les réduire en poudre. Goûter en cours de repos et filtrer dès que l'équilibre est trouvé, de crainte que le genièvre ne domine le bouquet.","d":"« Sept graines au flacon réunies font à l'estomac douce harmonie. »"},"lq-fenouil-sauvage":{"h":"Le fenouil sauvage dresse ses ombelles dorées sur les talus et les garrigues du Midi, exhalant au soleil un parfum d'anis qui imprègne le maquis. Les Grecs le nommaient 'marathon', et la plaine où se livra la célèbre bataille en tirait son nom, car le fenouil y croissait en abondance. Ses fleurs et ses graines parfumaient poissons, pains et liqueurs des pays de soleil.","p":"Le fenouil était réputé carminatif et digestif, ami des estomacs lourds, et l'on prêtait à ses graines la vertu d'éclaircir la vue et d'apaiser les coliques. On le tenait aussi pour favorable aux nourrices et adoucissant pour la gorge.","c":"Cueillir les fleurs en plein épanouissement, par temps sec, lorsque leur arôme anisé est le plus puissant. Une macération mesurée suffit ; filtrer puis laisser la liqueur s'arrondir quelques semaines au repos.","d":"« Fleur de fenouil au soleil mûrie porte au verre tout le Midi. »"},"lq-fraises-tagada":{"h":"La fraise Tagada, confiserie née dans les ateliers français du milieu du vingtième siècle, n'a du fruit que la forme et le rouge éclatant, mais elle a conquis les goûters de plusieurs générations. Sa pâte de guimauve poudrée de sucre, à l'arôme de fraise appuyé, fond dans l'alcool en lui prêtant sa couleur de grenadine et son parfum d'enfance. C'est une liqueur de fantaisie, clin d'œil gourmand glissé dans le grimoire des macérations.","p":"On ne saurait prêter à ce bonbon d'autre vertu que celle de réjouir le palais et d'amuser la compagnie. C'est une douceur de plaisir, non de remède, à boire pour le seul agrément.","c":"La macération est courte, car le bonbon se défait vite et libère promptement couleur et arôme. Inutile d'ajouter du sucre, la confiserie en apporte assez ; servir très frais, en petite quantité.","d":"« Tagada fondue dans l'eau-de-vie rend à l'adulte un goût d'enfantine envie. »"},"lq-fleur-oranger":{"h":"La fleur d'oranger, née du bigaradier que les Arabes répandirent autour de la Méditerranée, embaume les vergers du Midi de son parfum suave et entêtant. On la distille en eau précieuse, l'une des plus anciennes du parfumeur et du pâtissier, qui parfume les gâteaux de fête et les douceurs des noces. Les fiançailles d'antan se couronnaient de ses fleurs, emblèmes de pureté et de promesse.","p":"L'eau de fleur d'oranger était réputée calmante et sédative, glissée dans les tisanes du soir pour apaiser les nerfs agités et favoriser le sommeil. On la prêtait aussi propre à soulager les palpitations et les humeurs anxieuses.","c":"User des fleurs sèches avec parcimonie et de l'eau de fleur d'oranger d'une goutte mesurée, car cet arôme tourne vite au savonneux s'il est forcé. Laisser reposer la liqueur pour que le parfum se fonde sans agressivité.","d":"« Fleur d'oranger au verre du soir berce le dormeur sans le savoir. »"},"lq-acacias":{"h":"Les grappes blanches que l'on nomme communément fleurs d'acacia sont en vérité celles du robinier faux-acacia, arbre venu d'Amérique du Nord et acclimaté en Europe par les jardiniers du dix-septième siècle. Au mois de mai, leur floraison parfumée embaume les chemins et se cuisine en beignets dorés, vieille gourmandise de campagne. Leur suc, mêlé à l'eau-de-vie avec un soupçon de cannelle et de girofle, donne une liqueur claire et fleurie.","p":"Les fleurs de robinier étaient réputées adoucissantes et légèrement apaisantes, employées en infusion contre les aigreurs d'estomac. On se garde toutefois de l'écorce et des graines de cet arbre, tenues pour toxiques : seules les fleurs s'emploient.","c":"Ne cueillir que les grappes bien blanches et fraîchement ouvertes, en les détachant de leur rafle qui apporterait de l'amertume. La macération doit rester brève pour garder la finesse florale ; filtrer puis sucrer au sirop.","d":"« Grappe d'acacia au mois de mai cueillie fait la liqueur d'un printemps réjoui. »"},"lq-alise":{"h":"L'alise est le fruit de l'alisier, arbre des bois et des coteaux dont les Anciens connaissaient déjà les baies âpres, qui ne s'adoucissent qu'une fois blettes, touchées par les premiers froids. Le bois de l'alisier torminal, dense et précieux, fut recherché des ébénistes et des graveurs, tandis que ses fruits nourrissaient grives et passants. Mariée à la cannelle et à la vanille sur une eau-de-vie de fruits, l'alise livre une liqueur rustique aux notes d'amande et de fruits cuits.","p":"Les baies d'alisier étaient réputées astringentes, employées jadis contre les flux de ventre et les dérangements d'entrailles. On les tenait pour resserrantes, à n'user qu'avec mesure tant leur âpreté est franche.","c":"N'employer que des alises bien blettes, presque molles, car vertes elles sont trop âpres pour donner du plaisir. La cannelle et la vanille adoucissent leur rudesse ; laisser mûrir la liqueur de longues semaines pour qu'elle s'attendrisse.","d":"« Alise n'est bonne qu'après la gelée, qui veut la cueillir verte sera mal régalé. »"},"lq-noyaux-peches":{"h":"On a longtemps tiré des noyaux de pêches et d'abricots, brisés puis macérés, une essence parfumée à l'amande qui parfumait crèmes, ratafias et noyaux de table. Le mot 'noyau' désignait d'ailleurs à lui seul ces liqueurs domestiques que l'on préparait à l'arrière-saison, quand les vergers livraient leurs derniers fruits. Les amandons cachés sous la coque dure passaient ainsi pour le secret le mieux gardé du fruit.","p":"L'amandon de noyau était réputé cordial et stomachique, agréable digestif de fin de repas. Il renferme toutefois des composés qui libèrent du cyanure : la prudence ancienne, qui limitait sévèrement le nombre de noyaux, demeure de rigueur, et l'on s'en tiendra à de très petites quantités.","c":"Concasser les noyaux sans les réduire en pâte et ne laisser macérer que peu de temps, afin d'extraire l'arôme sans excès. Servir frais, en très petit verre, après un repas copieux.","d":"« Noyau brisé donne l'arôme, mais qui en abuse perd son homme. »"},"lq-ananas":{"h":"Rapporté des Amériques par les navigateurs, l'ananas fut d'abord un fruit de prince, choyé dans les serres chaudes des grandes demeures avant de gagner les tables bourgeoises. Sa couronne hérissée et sa chair dorée lui valurent une réputation d'exotisme presque royale, symbole d'hospitalité fastueuse. On le macérait dès qu'il devenait accessible, pour en fixer le parfum solaire dans l'eau-de-vie.","p":"La chair de l'ananas était tenue pour rafraîchissante et favorable à la digestion, réputée alléger les estomacs lourds après les mets gras.","c":"Choisir un fruit bien mûr, lourd et odorant, dont une feuille centrale se détache sans peine. Couper en dés en réservant le jus, et servir la liqueur fraîche, à l'heure du dessert.","d":"« Ananas cueilli à point parfume le verre et le festin. »"},"lq-angelique":{"h":"L'angélique, dont le nom même évoque la protection des anges, fut cultivée dans les jardins des cloîtres pour ses tiges aromatiques et ses graines. Confite à Niort, distillée chez les religieux, elle entra dans la composition de maintes eaux et liqueurs de santé. On la disait plante des temps de peste, brûlée et mâchée pour écarter les miasmes.","p":"Toute la plante, tige comme semence, était réputée tonique et stomachique, propre à réchauffer l'estomac et à ranimer les forces languissantes.","c":"Préférer des tiges jeunes et tendres, qui donnent plus de finesse que les vieilles fibres amères. Laisser longuement reposer après filtration, pour que les épices et la racine s'accordent.","d":"« Qui a l'angélique en son jardin n'a guère à craindre du chemin. »"},"lq-angleterre":{"h":"Les ratafias dits 'd'Angleterre' relèvent de ces noms de fantaisie dont les vieux livres de ménage aimaient parer leurs recettes, suggérant l'élégance des tables d'outre-Manche. Le mariage de l'amande amère, du citron et de l'angélique y compose une liqueur ambrée, relevée d'un soupçon de cachou venu des Indes. C'était une de ces préparations de dame que l'on offrait aux visiteurs de marque.","p":"On lui prêtait des vertus cordiales et digestives. L'amande amère qui en fait l'âme contient cependant des principes vénéneux libérant du cyanure : on la dose avec retenue, et la liqueur se boit à très petites gorgées.","c":"Mesurer les amandes amères avec parcimonie et ne pas prolonger leur séjour dans l'alcool. Filtrer sur linge fin pour clarifier la robe avant la mise en flacon.","d":"« Liqueur d'Angleterre en flacon, petit verre et longue saison. »"},"lq-anis":{"h":"L'anis vert compte parmi les plus vieilles épices des jardins de bouche, prisé des Égyptiens comme des Romains qui en parfumaient un gâteau de fin de repas. Sa graine, douce et chaude, traversa les âges dans les dragées de baptême et les eaux digestives. De ce grain modeste naquit toute une famille de liqueurs blanches que l'on troublait d'un trait d'eau.","p":"L'anis passait pour carminatif et digestif, apaisant les ventres noués et les digestions paresseuses ; on en donnait volontiers après les tables chargées.","c":"Écraser légèrement les grains pour libérer l'arôme sans amertume. Servir frais ; la liqueur se trouble joliment d'opale si l'on y ajoute un peu d'eau.","d":"« Un grain d'anis au fond du verre, et l'estomac fait bonne chère. »"},"lq-asperule":{"h":"L'aspérule odorante, humble herbe des sous-bois, ne livre tout son parfum de foin coupé et de vanille qu'une fois séchée. Elle est l'âme du vin de mai des pays germaniques, le fameux 'Maitrank' que l'on préparait à la fonte des neiges. Cueillie sous les hêtres au seuil du printemps, elle fut longtemps l'herbe joyeuse des premiers beaux jours.","p":"On la réputait cordiale et propre à réjouir le cœur. Riche en coumarine, elle veut une main mesurée, car prise en excès elle pourrait porter à la tête et fatiguer ; un usage léger reste de sagesse.","c":"Laisser légèrement faner les fleurs un jour ou deux avant la macération, pour réveiller leur parfum. Ne pas prolonger l'infusion, qui tournerait à l'amertume.","d":"« Aspérule au mois de mai réjouit qui sait l'apprêter. »"},"lq-aubepine":{"h":"L'aubépine, blanche épine des haies, fleurit au seuil de mai et fut de tout temps l'arbuste des seuils protecteurs, planté pour clore les champs et garder les maisons. Ses fleurs éphémères, à peine écloses, embaument l'air d'un parfum d'amande douce. On les recueillait en hâte, car la floraison dure peu, pour en garder le souvenir dans une liqueur.","p":"La fleur et le fruit de l'aubépine étaient tenus pour amis du cœur, réputés en apaiser les battements et tempérer les humeurs agitées.","c":"Cueillir les fleurs juste écloses, par temps sec, et les mettre à macérer sans tarder car elles passent vite. Filtrer avec soin et patienter quelques semaines avant de goûter.","d":"« Fleur d'épine au mois de mai, douce au cœur qui l'a cueillie. »"},"lq-basilic":{"h":"Le basilic, dont le nom dérive du grec signifiant 'royal', fut tenu pour herbe d'honneur autant que de cuisine, environnée de croyances contraires selon les pays. Venu de l'Inde par les routes d'Orient, il gagna les jardins méditerranéens où son parfum poivré devint inséparable des beaux jours. On le glissait aux fenêtres pour son odeur, et dans les plats pour sa flamme.","p":"Le basilic était réputé tonique et stomachique, ami des digestions et réconfort des esprits las.","c":"N'employer que des feuilles fraîches et bien vertes, cueillies avant la floraison qui les amollit. Macérer brièvement, car une infusion trop longue vire au foin ; servir frais.","d":"« Basilic en pot sur l'appui, parfume l'été qui s'enfuit. »"},"lq-betterave":{"h":"La betterave, longtemps simple racine potagère et fourragère, conquit ses lettres de noblesse quand on apprit à en tirer le sucre, au temps où les mers fermées privaient l'Europe de canne. Sa chair pourpre, profonde et terreuse, teint d'un rouge somptueux les liqueurs qu'elle parfume. De légume modeste, elle se fit ainsi curiosité de bouche.","p":"On prêtait à la betterave des vertus nourrissantes et adoucissantes, réputée réconforter les tempéraments affaiblis.","c":"Choisir une racine ferme et bien colorée, la râper finement pour qu'elle cède sa teinte et sa douceur. Filtrer soigneusement, car la pulpe trouble volontiers la liqueur.","d":"« Racine rouge en cave close donne au verre couleur de rose. »"},"lq-bissap":{"h":"Le bissap, infusion de fleurs séchées d'hibiscus, est la boisson de fête et d'hospitalité de toute l'Afrique de l'Ouest, d'un rouge éclatant comme le rubis. Les calices, recueillis et séchés, voyagèrent au long des routes pour colorer et aciduler les breuvages. Transposé en liqueur, ce trésor pourpre garde son acidité vive et sa robe de feu.","p":"L'hibiscus était réputé rafraîchissant et propre à désaltérer, apprécié pour son acidité tonique sous les fortes chaleurs.","c":"Doser le sucre sans timidité pour équilibrer l'acidité naturelle de la fleur. Servir bien frais, sa couleur grenat faisant à elle seule la fête du verre.","d":"« Fleur d'Afrique au rouge ardent rafraîchit le cœur en buvant. »"},"lq-bouillon-blanc":{"h":"Le bouillon-blanc, ou molène, dresse au bord des chemins sa haute tige de fleurs jaunes, si familière qu'on la nommait jadis cierge de Notre-Dame pour son port de flambeau. Ses fleurs et ses feuilles cotonneuses furent de longue date l'amie des poitrines et des gorges enrouées. On en faisait des tisanes pectorales avant d'en parer une liqueur dorée.","p":"La fleur de bouillon-blanc était réputée adoucissante et pectorale, amie des gorges irritées et des toux de l'hiver. On la filtre toujours avec un soin extrême, car ses petits poils piquants veulent être écartés.","c":"Ne retenir que les corolles bien jaunes, cueillies au matin, et les filtrer deux fois sur étamine très serrée pour ôter le moindre poil. Conserver à l'abri de la lumière, qui ternit sa belle couleur d'or.","d":"« Fleur du chemin couleur de miel adoucit la gorge en hiver. »"},"rh-44":{"h":"Le 'Rhum 44' tient son nom d'une arithmétique de cuisine devenue rituel : quarante-quatre grains de café, quarante-quatre morceaux de sucre, piqués dans une orange laissée quarante-quatre jours dans le rhum. Cette recette des Antilles et du Sud-Ouest se transmet de tablée en tablée comme un petit secret de famille. L'orange clouée de café y devient une curiosité que l'on montre fièrement au fond du bocal.","p":"On lui prêtait des vertus digestives et toniques, l'alliance du café et des épices passant pour réveiller les esprits après le repas.","c":"Piquer une orange non traitée, à la peau saine et parfumée, de grains de café bien torréfiés. Respecter les quarante-quatre jours de patience, puis retirer l'orange avant qu'elle ne donne de l'amertume.","d":"« Quarante-quatre jours d'attente font la liqueur qui contente. »"},"rh-vanille-macadamia":{"h":"La noix de macadamia, venue des forêts d'Australie où les peuples premiers la récoltaient de longue date, est l'une des plus tardives venues au jardin des fruits secs. Sa coque, d'une dureté redoutable, garde une amande douce et beurrée au goût de crème. Mariée à la vanille dans le rhum, elle compose une liqueur ronde et veloutée, aux accents des îles.","p":"L'amande de macadamia, riche et nourrissante, était tenue pour réconfortante et propre à soutenir les forces.","c":"Concasser les noix pour qu'elles livrent tout leur gras parfumé, et fendre la gousse de vanille en deux pour en gratter les graines. La longue macération assouplit l'ensemble : patienter avant de filtrer.","d":"« Noix des antipodes en flacon, vanille pour bonne façon. »"},"rh-ananas":{"h":"Dans les îles à rhum, l'ananas et la canne poussent côte à côte, et leur mariage dans le bocal coule de source comme une évidence créole. Fruit-roi des Tropiques, l'ananas y mûrit au soleil jusqu'à fondre de sucre, prêt à parfumer l'eau-de-vie locale. Cette macération simple est de celles que l'on prépare au retour du marché, sans façon ni mesure savante.","p":"La chair de l'ananas mûr était réputée rafraîchissante et favorable à la digestion, agréable conclusion des repas sous les chaleurs.","c":"Choisir un ananas pleinement mûr, fondant et sucré, en réservant le jus à la macération. Le rhum agricole, herbacé, soutient mieux le fruit qu'un rhum trop neutre ; servir frais.","d":"« Soleil dans le fruit, soleil dans le verre, telle est la loi des îles à canne. »"},"rh-vaudou":{"h":"Le nom de cette macération évoque les cultes afro-caribéens nés de la rencontre entre l'Afrique de l'Ouest et les Antilles, où le rhum tenait souvent lieu d'offrande versée aux esprits. L'assemblage de fruits tropicaux et d'épices ardentes — girofle, muscade, piment-oiseau — rappelle les marchés d'épices des îles, carrefours du grand négoce colonial. Une telle débauche aromatique relevait autant du remède de bonne femme que du plaisir de bouche.","p":"Les épices chaudes y étaient tenues pour stimulantes et carminatives, propres à 'réveiller les sangs paresseux'. On usera toutefois du piment-oiseau et de la muscade avec retenue, car l'un brûle le palais et l'autre, à forte dose, trouble la tête.","c":"Choisir des fruits parvenus à pleine maturité, presque confits par le soleil ; la longue macération de quatre mois lie les ardeurs épicées au moelleux des dattes et de la papaye. Servir frais, à très petite mesure, après un repas copieux.","d":"« Rhum qui mêle feu et fruit fait danser jusques à la nuit. »"},"rh-banane":{"h":"La banane, dont le nom nous vient du portugais emprunté aux langues d'Afrique de l'Ouest, voyagea de l'Asie vers les Antilles dans les cales des navigateurs. Aux îles à sucre, elle devint pain quotidien autant que douceur, et l'alliance du fruit mûr au rhum de canne y allait de soi. Sa chair fondante donne aux macérations une rondeur veloutée que nul autre fruit n'égale.","p":"On disait la banane nourrissante et réconfortante, bonne pour 'refaire les forces' des travailleurs des champs. Réduite en liqueur, elle passait pour adoucir l'estomac et apaiser les esprits échauffés.","c":"Préférer des bananes bien mûres, tachetées de brun, dont les sucres sont pleinement développés ; les vertes ne donnent qu'amertume. Filtrer soigneusement, car la pulpe se délite et trouble le flacon.","d":"« À banane mûre et canne sucrée, la liqueur se fait dorée. »"},"rh-abricots-antilles":{"h":"L'abricot tire son nom, par le latin et l'arabe al-barqūq, de l'idée d'un fruit 'précoce', mûri avant les autres. Originaire des contrées d'Asie centrale, il gagna le pourtour méditerranéen avant que ses cousins tropicaux ne prospèrent sous d'autres cieux. Marié au rhum et à la vanille Bourbon, il compose une liqueur ambrée digne des comptoirs d'épices.","p":"La chair de l'abricot était réputée rafraîchissante et bénéfique au teint, riche d'un suc doré que les anciens prisaient. On gardera cependant à l'esprit que l'amande de son noyau, amère, recèle un principe vénéneux et ne saurait être employée sans grande mesure.","c":"Choisir des abricots parfumés et fondants ; un fruit ferme ne livre qu'un arôme avare. La vanille Bourbon se fend dans la longueur pour mieux exhaler ses graines.","d":"« Abricot d'or et vanille fine font à la coupe mine divine. »"},"rh-cerise-citronnee":{"h":"La cerise doit son nom à la cité antique de Cerasus, sur les rivages du Pont-Euxin, d'où l'on rapporta jadis le cerisier vers l'Occident. Fruit de fête et de printemps, elle parut de tout temps dans les ratafias et les guignolets de nos campagnes. Le zeste de citron vert, ici, en relève l'éclat d'une fraîcheur acidulée.","p":"La cerise était tenue pour rafraîchissante et bénéfique aux reins, et sa queue séchée passait pour aider à 'faire couler les eaux'. Méfiance toutefois du noyau brisé, dont l'amande amère partage avec celle de l'abricot un principe redoutable.","c":"Prendre des cerises bien noires et charnues, fendues mais non dénoyautées pour qu'un soupçon d'amertume noble s'y glisse. Servir frais, en fin de repas, lorsque l'acidité du citron tranche sur la douceur.","d":"« Cerise et citron mariés, gaîté du verre assurée. »"},"rh-acai":{"h":"L'açaï, baie d'un palmier des forêts inondées de l'Amazone, porte un nom venu du tupi désignant 'le fruit qui pleure son eau'. Les peuples du fleuve en faisaient une bouillie nourrissante, pilée et délayée, bien avant que son nom ne courût les villes. Sa pulpe sombre, presque vineuse, donne au rhum une robe profonde rehaussée de cannelle et de poivre.","p":"Les populations amazoniennes la tenaient pour soutenante et fortifiante, propre à rassasier le pêcheur jusqu'au soir. On lui prêtait une vertu tonique, qui s'accorde bien à la chaleur des épices qui l'accompagnent ici.","c":"L'açaï s'altère vite : on l'emploiera en pulpe surgelée ou en poudre de bonne provenance plutôt qu'en baie fragile. Une pointe de poivre noir suffit à réveiller son arôme sourd et boisé.","d":"« Baie du grand fleuve en macération teint le rhum de sa passion. »"},"rh-couille-singe-tagada":{"h":"Voici une fantaisie de confiserie plus que d'herbier, où le rhum des îles épouse les sucreries de nos foires. Les bonbons dits 'couilles de singe', boules acidulées tapissant les bocaux des marchands, et la fraise Tagada, née au mitan du vingtième siècle, y mêlent leurs parfums espiègles. C'est là une recette de plaisir et de sourire, sans prétention savante.","p":"Nulle vertu médicinale ne saurait être prêtée à pareille gourmandise, qui ne vise que la joie du palais. On la réservera aux soirs de fête, sans en attendre autre soin que celui du cœur léger.","c":"Macération brève, dix à trente jours suffisent, car les bonbons fondent et libèrent vite leurs colorants. Filtrer avec soin pour ôter la cire et servir bien glacé.","d":"« Sucre de foire et rhum bien fort font rire le verre jusqu'au bord. »"},"rh-acerola":{"h":"L'acérola, petite cerise des Antilles et des terres d'Amérique tropicale, doit son nom espagnol à sa ressemblance avec l'azerole de nos haies méditerranéennes. Son fruit écarlate, fragile et juteux, fut longtemps cueilli en bordure des jardins créoles. Réputée gorgée de suc vif, elle prête au rhum une acidité franche et printanière.","p":"On la tenait pour souverainement rafraîchissante et propre à 'redonner du ton' aux convalescents, tant son suc passait pour vivifiant. Cette réputation de fruit fortifiant lui valut faveur sous les climats chauds.","c":"Le fruit se gâte en quelques heures : à défaut de fruit frais, la purée surgelée préserve au mieux sa vivacité. Adoucir au sirop de canne pour tempérer son acidité parfois mordante.","d":"« Petite cerise des îles vaut au verre mille pétilles. »"},"rh-hibiscus":{"h":"Les calices séchés de l'hibiscus, que l'on nomme bissap en Afrique de l'Ouest et oseille de Guinée aux Antilles, colorent les boissons d'un rouge de rubis. De longue date, on en tirait infusions et sirops de fête sur les deux rives de l'Atlantique. Plongés dans le rhum, ces calices teignent la liqueur d'une pourpre éclatante et d'une acidité de fruits rouges.","p":"L'infusion d'hibiscus était réputée rafraîchissante et désaltérante, et l'on disait qu'elle 'tempérait les ardeurs' de la fièvre estivale. Sa belle acidité en faisait une boisson prisée par grande chaleur.","c":"Une macération trop longue tire de l'amertume des calices ; mieux vaut goûter et filtrer dès que la robe est franche. Le sucre de canne arrondit l'acidité naturelle de la fleur.","d":"« Fleur de pourpre au flacon mise pare le rhum d'une chemise. »"},"rh-ananas-piment":{"h":"L'ananas, que les Tupi nommaient nanas, 'parfum des parfums', émerveilla les premiers navigateurs abordant les Antilles, qui en firent l'emblème de l'hospitalité. Couronné de sa houppe verte, ce fruit royal trônait sur les tables des grandes maisons coloniales. Le piment-oiseau, ici, vient cingler sa douceur sucrée d'un trait de feu.","p":"L'ananas mûr passait pour aider la digestion des viandes et 'défaire les lourdeurs' des bons repas. Le piment-oiseau, ardent entre tous, sera dosé d'une main timide, car il échauffe la bouche et le gosier sans pitié.","c":"Choisir un ananas dont une feuille centrale se détache aisément, gage de pleine maturité. Un seul piment fendu suffit à parfumer ; on le retirera dès que la chaleur paraît juste.","d":"« Ananas doux, piment qui mord : au verre c'est gentille discorde. »"},"rh-fraise":{"h":"La fraise, dont le nom dérive du latin fraga, embaumait déjà les sous-bois que parcouraient les anciens. Longtemps menue et sauvage, elle ne prit son ampleur qu'après le croisement, au siècle des jardins, de variétés venues des deux Amériques. Mariée au rhum de canne, elle compose une liqueur vermeille à l'arôme de plein été.","p":"La fraise était tenue pour rafraîchissante et bénéfique au teint, et l'on vantait sa chair comme 'amie du sang'. On lui prêtait aussi le pouvoir d'apaiser les humeurs échauffées par la canicule.","c":"Prendre des fraises parfumées et bien rouges à cœur, cueillies à maturité, car une fois pâles elles ne rendent qu'eau. Macération courte et flacon à l'abri du jour, sous peine de voir la belle couleur ternir.","d":"« Fraise de juin au rhum noyée garde l'été en bouteille scellée. »"},"rh-arbouses":{"h":"L'arbouse, fruit de l'arbousier des garrigues méditerranéennes, fut surnommée par les anciens 'fruit que l'on ne mange qu'une fois', en raison de son arrière-goût rude quand elle n'est point mûre. Son arbre porte en même temps fleurs et fruits, prodige qui le fit aimer des promeneurs. Cueillie à point et unie au thym, elle donne un rhum au parfum de maquis.","p":"On lui prêtait des vertus astringentes et toniques, et l'on en faisait jadis des conserves réputées soutenir l'estomac. Le thym qui l'accompagne était tenu pour antiseptique et fortifiant des voies de la poitrine.","c":"Ne cueillir que les arbouses d'un rouge profond, molles sous le doigt, car les fermes restent âpres et farineuses. Un brin de thym seulement, pour évoquer la garrigue sans masquer le fruit.","d":"« Arbouse et thym de la colline mettent le maquis en bouteille fine. »"},"rh-cacahuete":{"h":"La cacahuète, dont le nom nous vient du nahuatl tlālcacahuatl, 'cacao de terre', est une graine d'Amérique qui mûrit sous le sol, fait singulier qui intrigua longtemps les botanistes. Portée par les navires jusqu'en Afrique puis partout sous les tropiques, elle devint nourriture de fond pour bien des peuples. Pilée et liée au lait, elle compose ici une crème de rhum onctueuse et gourmande.","p":"On tenait cette graine huileuse pour nourrissante et soutenante, propre à 'rassasier le pauvre' en temps de disette. Riche et grasse, elle s'accommode des épices douces qui l'accompagnent, muscade et cannelle.","c":"Torréfier légèrement les cacahuètes avant macération pour en révéler tout l'arôme grillé. Cette crème, lourde en laitage, se garde au frais et se boit jeune, dans les jours qui suivent sa préparation.","d":"« Graine de terre et lait sucré font le rhum tout veloutté. »"},"rh-mangue-betterave":{"h":"La mangue, reine des fruits des pays chauds, porte un nom venu du tamoul par le portugais, et son arbre était vénéré dans les jardins de l'Orient. Apportée aux Antilles au fil des grands voyages, elle y trouva une seconde patrie sous le soleil. Mariée à la betterave de nos potagers, elle compose un assemblage hardi où le sucre terreux de la racine épouse la chair solaire du fruit.","p":"La mangue mûre était tenue pour rafraîchissante et bénéfique aux entrailles, et la betterave, de longue date, passait pour 'refaire le sang' des affaiblis. L'une et l'autre, riches en suc, donnent une liqueur réputée réconfortante.","c":"Choisir une mangue parfumée qui cède sous une pression douce, et une betterave cuite plutôt que crue pour adoucir sa rusticité. La couleur grenat tient de la racine bien plus que du fruit.","d":"« Mangue du Sud, rave du Nord : au verre se font bel accord. »"},"rh-banane-cannelle":{"h":"Le séchage de la banane, qui en concentre les sucres en pâte sombre et moelleuse, est un art ancien des terres tropicales où l'on conservait ainsi la récolte. La cannelle, écorce roulée d'un arbre de Ceylan, fut jadis si précieuse qu'elle valait son poids d'argent dans les ports d'épices. Leur union dans le rhum tisse un parfum chaud de pain d'épice et de fruit confit.","p":"La banane séchée passait pour nourrissante et énergique, viatique des longues marches sous le soleil. La cannelle était réputée stomachique et réchauffante, 'amie du ventre et des froidures', et l'on en usait volontiers l'hiver.","c":"Préférer des bananes séchées souples et brunes, non desséchées à l'excès, qui rendront tout leur miel. Un seul bâton de cannelle suffit pour une bonne mesure, faute de quoi l'épice domine et assèche.","d":"« Banane sèche et cannelle d'or réchauffent le buveur qui dort. »"},"rh-menthe-sauvage":{"h":"La menthe doit son nom à la nymphe Minthê de la mythologie grecque, métamorphosée en herbe odorante au bord des chemins. Les jardins monastiques la cultivaient pour parfumer hydromels et vins de table, et les marins des Antilles la mêlaient volontiers au rhum frais des distilleries de canne. Sa fragrance se libère dès qu'on froisse la feuille entre les doigts.","p":"La menthe était réputée rafraîchir l'haleine, apaiser l'estomac lourd et dissiper les langueurs de l'été ; les anciens herbiers la classaient parmi les plantes 'réjouissantes du cœur'.","c":"Cueillir la menthe sauvage avant la floraison, quand l'huile parfumée est la plus dense ; froisser les feuilles sans les broyer pour éviter l'amertume, et servir bien frais.","d":"« Menthe au verre, menthe au pré, garde l'esprit toujours léger. »"},"rh-poire":{"h":"La poire, fruit de la cour des rois, ornait déjà les vergers romains qui en comptaient de nombreuses variétés greffées. Les moines et les jardiniers de France en firent un art, multipliant les noms savoureux au fil des saisons. En eau-de-vie comme en macération, elle livre un parfum fuyant que les distillateurs ont toujours jugé difficile à capturer.","p":"La poire passait pour un fruit doux et rafraîchissant, ami de l'estomac délicat ; on la disait propre à désaltérer et à tempérer les humeurs chaudes.","c":"Choisir des poires de saison juste mûres, encore fermes et très parfumées ; trop blettes, elles tournent à la bouillie et brouillent la limpidité de la liqueur.","d":"« Poire cueillie à la bonne heure parfume le verre et réjouit le buveur. »"},"rh-bounty":{"h":"La noix de coco, cœur de cette friandise, voyagea sur tous les océans grâce à sa coque flottante capable de germer après de longues dérives. Les navigateurs la nommèrent 'coco' pour les trois yeux de sa coque évoquant un visage grimaçant. Mariée au chocolat, elle compose une douceur insulaire que le rhum prolonge naturellement.","p":"Le lait de coco était tenu pour nourrissant et rafraîchissant sous les tropiques, tandis que le cacao passait pour réconfortant et propre à relever les esprits abattus.","c":"Laisser fondre lentement la confiserie dans le rhum tiède sans la brusquer, puis filtrer avec soin pour retenir le gras qui troublerait la liqueur ; servir frais, en très petit verre.","d":"« Coco du large et sucre fin, font d'un rhum un doux festin. »"},"rh-coco-vanille":{"h":"La noix de coco accompagne depuis des siècles les cuisines des îles, où l'on tire de sa chair râpée un lait crémeux à toute heure. Le cocotier, surnommé 'arbre aux mille usages', nourrit, abreuve et abrite ceux qui le cultivent. Sur les plantations sucrières, son mariage avec le rhum allait de soi, l'un et l'autre nés du même soleil.","p":"La chair du coco était réputée nourrissante et adoucissante, et son eau passait pour étancher la soif et rafraîchir le corps échauffé par les chaleurs.","c":"Préférer une noix lourde et pleine d'eau, à la chair bien blanche ; la râper finement libère davantage de parfum, et une gousse de vanille fendue sublime l'ensemble.","d":"« Sous le cocotier qui se penche, le rhum se fait douceur de dimanche. »"},"rh-tonka":{"h":"La fève de tonka provient d'un grand arbre des forêts d'Amérique du Sud, dont la graine noire et ridée embaume l'amande, la vanille et le foin coupé. Les parfumeurs l'ont longtemps prisée pour fixer leurs essences, et les pâtissiers en râpent une poussière sur crèmes et entremets. Son arôme tient à la coumarine, qui exhale tout son charme à dose infime.","p":"La tonka était réputée tonique et réconfortante, et l'on en glissait jadis dans les armoires pour parfumer le linge. Riche en coumarine, elle ne se prête qu'à de très menues quantités, car son excès la rend nuisible : qu'une seule fève suffise à parfumer toute la bouteille.","c":"Râper la fève plutôt que de la laisser entière, et n'en mettre qu'un soupçon ; goûter régulièrement, car le parfum gagne en force au fil des jours et tourne vite à l'amer.","d":"« Fève de tonka, main légère : un grain parfume, deux exagèrent. »"},"rh-gingembre":{"h":"Le gingembre, rhizome venu d'Asie, fut l'une des premières épices à voyager le long des routes caravanières jusqu'aux tables d'Europe. Au Moyen Âge, on le comptait parmi les épices de chambre offertes en fin de banquet, et son nom passa de langue en langue jusqu'à nous. Sa saveur mordante et chaude en fit l'allié des boissons fortifiantes.","p":"Le gingembre était réputé réchauffer le corps, aiguiser l'appétit et faciliter la digestion ; les vieux traités le rangeaient parmi les épices 'échauffantes' propres à ranimer les frileux.","c":"Choisir un rhizome ferme à la peau lisse, le trancher sans l'éplucher entièrement pour garder son piquant ; doser avec mesure, car il prend vite le dessus sur la vanille et la cannelle.","d":"« Gingembre au flacon, feu sans flamme, réchauffe le corps et réveille l'âme. »"},"rh-raisin-muscat":{"h":"Le muscat compte parmi les plus anciens cépages cultivés, déjà loué pour sa saveur musquée par les agronomes de l'Antiquité. Son nom même évoque le musc, tant son parfum se distingue de tout autre raisin. Séché ou mêlé aux figues, il porte le sucre et le soleil des vendanges au cœur de la macération.","p":"Le raisin mûr passait pour restaurer les forces et adoucir la poitrine, et le vin de muscat était tenu pour cordial et réjouissant. Les figues sèches qui l'accompagnent étaient réputées pectorales et nourrissantes.","c":"Choisir des grains bien dorés et sucrés, à la peau fine, en écartant ceux qui marquent le moindre flétrissement amer ; une bâton de cannelle suffit à lier le tout sans masquer le fruit.","d":"« Muscat et figue au même flacon, font d'un soir d'automne une chanson. »"},"rh-figues-fraiches":{"h":"La figue, l'un des plus vieux fruits cultivés du bassin méditerranéen, nourrissait déjà les peuples de l'Antiquité qui la séchaient pour l'hiver. Le figuier, généreux et rustique, prospère sur les terres pauvres et donne un fruit sucré au cœur de pourpre. Associée à la lavande, elle compose un parfum tout entier tourné vers le Midi.","p":"La figue était réputée adoucissante, nourrissante et bienfaisante pour la poitrine ; on en faisait des cataplasmes et des sirops contre la toux. La lavande passait pour calmante et propre à clarifier l'esprit.","c":"Cueillir les figues à parfaite maturité, lourdes et fendues d'une goutte de miel à la base ; les fendre en quatre pour libérer la pulpe, et n'user de la lavande qu'avec retenue pour ne pas verser dans le savonneux.","d":"« Figue mûre et brin de lavande, font un nectar que l'on quémande. »"},"rh-abricots":{"h":"L'abricot voyagea depuis les vergers d'Asie centrale jusqu'aux jardins méditerranéens, où il trouva un climat à sa mesure. Son nom, passé par l'arabe et le latin, évoque le fruit 'précoce' qui mûrit avant l'été. Doré et velouté, il fut longtemps réservé aux tables soignées avant de gagner tous les vergers.","p":"L'abricot mûr était tenu pour rafraîchissant et bienfaisant à l'estomac. On gardera toutefois de croquer ses noyaux, dont l'amande amère renferme un principe vénéneux qui se libère à la mastication.","c":"Choisir des abricots bien mûrs et parfumés, dénoyautés avec soin ; pour une note amandée, glisser un noyau concassé tout au plus, jamais davantage, et le retirer après quelques semaines.","d":"« Abricot d'or au mois de juin, parfume le verre jusqu'au matin. »"},"rh-epices":{"h":"Le mélange d'épices fortes ravive la mémoire des grandes routes commerciales, quand cannelle, girofle et muscade valaient leur pesant d'or sur les marchés. Chaque port marchand entretenait ses recettes secrètes de vins et de liqueurs épicés. Réunies dans le rhum des îles, ces épices recomposent l'arôme des cargaisons d'autrefois.","p":"Les épices royales étaient réputées réchauffer le sang, fortifier l'estomac et aider la digestion des repas copieux ; on les jugeait souveraines contre les froidures de l'hiver. La muscade, en revanche, devait rester chichement dosée, son excès passant pour troubler les sens.","c":"Concasser les épices grossièrement pour libérer leur parfum sans noyer la liqueur de poudre ; goûter souvent, car girofle et muscade dominent vite, et filtrer dès que l'équilibre est trouvé.","d":"« Qui sait doser girofle et cannelle tient au flacon une part d'éternel. »"},"rh-fraises-tagada":{"h":"La fraise des jardins, telle que nous la connaissons, naquit du croisement fortuit de deux espèces rapportées des Amériques au siècle des explorations. Avant elle, on se contentait des menues fraises des bois cueillies aux lisières. La friandise rose qui parfume ce rhum n'est qu'un lointain et malicieux écho de ce fruit, traduit en sucre et en confiserie.","p":"La fraise fraîche était réputée rafraîchissante et amie du teint, et l'on prêtait à son suc des vertus dépuratives. La confiserie, elle, n'apporte que sa douceur sucrée et son parfum éclatant, sans nulle prétention médicinale.","c":"Compter les bonbons avec mesure, car le sucre prend vite le dessus ; les laisser fondre à froid sans secouer, puis filtrer pour ôter le voile gélatineux qui troublerait la liqueur.","d":"« Bonbon fondu, rhum rosé, voilà l'enfance retrouvée. »"},"rh-kiwis-jaunes":{"h":"Le kiwi, longtemps nommé 'groseille de Chine', est originaire des vallées de l'Asie orientale avant d'être acclimaté aux antipodes, où il prit son nom d'oiseau. La variété jaune, plus douce et moins acidulée que la verte, livre une chair couleur de miel. Sa saveur fraîche et exotique convient au rhum des îles comme une main à un gant.","p":"Le kiwi était tenu, dans son pays d'origine, pour tonique et rafraîchissant ; sa pulpe juteuse passait pour étancher la soif et réjouir le palais lassé.","c":"Choisir des kiwis jaunes souples sous le doigt, à la chair bien dorée ; les peler et les trancher fin, et ne pas trop prolonger la macération, car leurs pépins finissent par donner une pointe d'amertume.","d":"« Kiwi doré sous le soleil, donne au rhum un goût de réveil. »"},"rh-pommes-tatin":{"h":"La pomme, fruit nourricier de tous les climats tempérés, accompagne les hommes depuis la plus haute antiquité des vergers. La tarte renversée qui inspire ce rhum naquit, dit-on, d'une cuisson conduite à l'envers dans une auberge de Sologne. Caramélisée et vanillée, la pomme y prend des accents d'automne et de feu de bois.","p":"La pomme était réputée rafraîchissante, amie de l'estomac et propre à entretenir la bonne humeur ; un vieil adage la disait suffisante à éloigner le médecin de la maison.","c":"Choisir des pommes fermes et un peu acidulées, qui tiennent à la cuisson sans se défaire ; les faire dorer au caramel avant de les noyer dans le rhum ambré donne toute la note 'tatin'.","d":"« Pomme au caramel, rhum couleur d'ambre, parfument tout un soir de chambre. »"},"rh-brulant":{"h":"Le piment, rapporté des Amériques au temps des grandes traversées, gagna en quelques décennies les cuisines de tout l'Ancien Monde, des îles aux comptoirs d'Orient. Le petit 'piment oiseau', minuscule et redoutable, doit son nom aux volatiles qui en répandent les graines. Dans le rhum, il compose une boisson de bravade autant que de plaisir.","p":"Le piment était réputé échauffer puissamment le sang et stimuler la digestion. Sa force exige toutefois la plus grande prudence : un excès brûle le palais et irrite les entrailles, et l'on conseillera de n'en glisser qu'une ou deux gousses.","c":"Fendre les piments sans les écraser pour doser leur ardeur, et goûter chaque semaine car la chaleur monte vite ; les retirer dès que la morsure est franche, sous peine d'une liqueur intenable.","d":"« Piment au rhum, prudence au verre : qui boit trop vite touche l'enfer. »"},"rh-cafe-vanille":{"h":"Le caféier, originaire des hauts plateaux d'Éthiopie, gagna le monde arabe par les ports du Yémen avant de conquérir l'Europe au temps des cabarets et des premières « maisons de café ». La vanille, gousse d'une orchidée grimpante du Mexique, voyagea sur les mêmes routes marchandes et passa longtemps pour un luxe d'apothicaire. Marier le grain torréfié à la gousse parfumée, c'est rassembler dans un flacon deux trésors que les navigateurs se disputaient.","p":"Le café passait pour un puissant tonique de l'esprit, chassant la somnolence et aiguisant l'entendement, tandis que la vanille était réputée flatter l'estomac et adoucir l'humeur. On en faisait volontiers un cordial de fin de soirée.","c":"Concasser les grains plutôt que les moudre fin, sous peine d'une liqueur trouble et amère ; fendre la gousse dans sa longueur pour en libérer les graines. Servir frais, en très petit verre, après le repas.","d":"« Grain de café, gousse de miel, font veiller l'homme et rêver le ciel. »"},"rh-canneberge-framboise":{"h":"La canneberge, airelle des tourbières d'Amérique du Nord, fut longtemps cueillie par les peuples premiers qui l'écrasaient avec la graisse et la viande séchée pour en faire des provisions de marche. Les colons la nommèrent crane-berry, baie de la grue, pour la fleur recourbée comme le col de l'oiseau. La framboise, plus familière de nos haies, lui apporte un parfum de sous-bois que les ronciers offrent à qui sait les braver.","p":"La canneberge était tenue pour rafraîchissante et bénéfique aux voies basses du corps ; la framboise passait pour adoucir la gorge et tempérer les ardeurs de l'été. Toutes deux entraient dans les sirops d'office.","c":"Piquer les canneberges d'un coup d'aiguille ou les concasser, car leur peau cireuse résiste à l'alcool. Goûter avant d'ajouter le sucre, la canneberge restant acidulée jusqu'au bout.","d":"« Baie des marais, baie des halliers, en un flacon font bon ménage entier. »"},"rh-caramel":{"h":"Le caramel naît d'un geste très ancien : la cuisson du sucre jusqu'au seuil du brûlé, là où le blanc se fait ambre et le doux se fait amer. Les confiseurs d'autrefois en tiraient sucres d'orge et pastilles, et la friandise au caramel mou devint une douceur de poche pour les enfants. Le dissoudre dans l'eau-de-vie, c'est rendre liquide et chaude une mémoire de pâtisserie.","p":"On prêtait au sucre cuit une vertu réconfortante et adoucissante pour la gorge irritée, et l'on suçait volontiers une pastille caramélisée contre la toux sèche. C'était surtout une gourmandise consolatrice.","c":"Faire fondre les bonbons à feu très doux, ou à chaud dans le rhum, pour éviter qu'ils ne massent en pâte collante. Cette liqueur, riche et sucrée, se sert glacée et à très petite dose.","d":"« Sucre poussé au bord du noir donne aux soirs un goût d'espoir. »"},"rh-cassis-groseille":{"h":"Le cassis, ou groseillier noir, fut longtemps regardé d'un œil méfiant pour l'odeur âcre de ses feuilles, avant que l'on découvrît la richesse de sa baie sombre et que les jardins de Bourgogne n'en fassent une gloire. La groseille rouge, plus ancienne dans nos vergers du Nord, ornait les treilles et les tartes des fermes. Réunir le noir et le rouge en un même bocal, c'est marier la profondeur et la vivacité des fruits du groseillier.","p":"Le cassis était réputé fortifiant et bon pour les articulations raides, sa feuille passant même pour soulager les douleurs ; la groseille, rafraîchissante, calmait la soif des fiévreux. On en tirait des ratafias d'apothicaire.","c":"Égrapper soigneusement et écraser légèrement les baies pour libérer le jus sans broyer les pépins amers. Une pincée de cannelle suffit : trop d'épice écrase le fruité du cassis.","d":"« Cassis noir et groseille en feu font le ratafia des aïeux. »"},"rh-citron-gingembre":{"h":"Le citron, agrume venu d'Asie et acclimaté par les Arabes sur les rivages de la Méditerranée, fut le précieux remède des marins contre le mal des longues traversées. Le gingembre, rhizome noueux des moussons d'Orient, voyagea sur la route des épices et valait parfois son pesant d'argent sur les étals médiévaux. Frotter l'écorce dorée du fruit contre le feu de la racine, c'est unir le soleil des vergers et la chaleur des comptoirs lointains.","p":"Le citron était tenu pour grand purificateur et préservatif contre le scorbut, tandis que le gingembre passait pour échauffer l'estomac, réveiller l'appétit et fortifier les tempéraments froids. On en faisait des élixirs de l'hiver.","c":"N'employer que le zeste, sans le blanc amer, et trancher le gingembre frais sans l'éplucher entièrement. Plus la racine repose, plus elle pique : goûter à mi-maturation.","d":"« Zeste d'or et racine ardente réchauffent le sang qui s'absente. »"},"rh-citron-gingembre-piment":{"h":"Le piment oiseau, minuscule et redoutable, vient des terres tropicales d'Amérique d'où il essaima par les caravelles vers l'Afrique et l'Asie, où il devint partout l'âme des cuisines de feu. Son nom dit la taille de l'oiseau qui en raffole et en répand les graines. Quelques gousses suffisent à embraser tout un flacon, et l'on en use comme d'une braise plus que d'un fruit.","p":"Le piment était réputé échauffer puissamment le corps et stimuler les digestions paresseuses ; on le maniait toutefois avec prudence, car sa morsure irrite la bouche et les entrailles sensibles, et la macération concentre vite son feu. Mieux vaut une goutte de trop peu qu'une de trop.","c":"Fendre un seul piment et le retirer dès que l'ardeur convient, car il continue d'infuser jour après jour. Servir cette liqueur en larmes plutôt qu'en rasade, pour réveiller un plat sans incendier le palais.","d":"« Petit oiseau au bec de braise, qui l'éveille s'en trouve à l'aise, qui l'abuse en perd la fournaise. »"},"rh-coco-gingembre":{"h":"La noix de coco, fruit du cocotier des littoraux tropicaux, traversa les océans en flottant d'île en île, ce qui lui valut chez les marins une réputation de voyageuse infatigable. Les comptoirs d'autrefois en faisaient grand cas pour son lait, sa chair et son eau rafraîchissante. Mariée au gingembre venu des mêmes latitudes chaudes, elle troque sa douceur laiteuse contre un trait de chaleur épicée.","p":"La chair de coco passait pour nourrissante et reconstituante, propre à rendre des forces aux corps amaigris, tandis que le gingembre réveillait l'estomac engourdi. On y voyait un baume des climats lourds.","c":"Râper la chair fraîche plutôt que d'user de poudre, pour un parfum plus rond et soyeux. Filtrer avec soin à travers une étamine fine, car le coco rend un voile gras qu'il faut clarifier au froid.","d":"« Lait des îles, feu de racine : douceur qui dort, chaleur qui mine. »"},"rh-des-bois":{"h":"La fraise des bois et la framboise sauvage furent les premières douceurs des sous-bois, cueillies bien avant que l'on songeât à les ranger en planches alignées. Les Romains déjà chantaient le parfum de la petite fraise, et nos grands-mères allaient en remplir des paniers de feuilles le long des lisières. Y joindre menthe et vanille, c'est recomposer tout un sentier d'été dans la fraîcheur d'une bouteille.","p":"La fraise était réputée rafraîchissante et bénéfique au teint, la framboise adoucissante pour la gorge ; la menthe, elle, passait pour faciliter la digestion et raviver les esprits las. C'était la liqueur des promeneurs.","c":"Choisir des fruits cueillis à pleine maturité et les employer sans tarder, car leur parfum fuit vite. Ajouter la menthe en fin de macération seulement, sous peine d'une amertume herbacée.","d":"« Au bois qui sent la fraise mûre, l'été se garde en confiture. »"},"rh-douceur":{"h":"L'oranger, venu de Chine par les jardins des califes, fit longtemps les délices des cours princières qui l'abritaient dans leurs orangeries dorées. Le clou de girofle, bouton séché d'un arbre des îles aux épices, valait jadis si cher qu'on le comptait à l'unité et qu'on s'en disputait les comptoirs lointains. Piquer l'orange de girofle est un geste de Noël aussi ancien que les premières pommes d'ambre parfumées des chambres.","p":"L'écorce d'orange amère était réputée tonique et stomachique, propre à relever l'appétit ; le girofle passait pour assainir l'haleine, calmer la rage de dents et réchauffer les humeurs froides. On en faisait un cordial des veillées d'hiver.","c":"Préférer des oranges non traitées et n'en lever que le zeste coloré, le blanc apportant l'amertume. Deux ou trois clous de girofle suffisent largement, leur parfum dominant tout s'il abonde.","d":"« Orange et clou en bon accord gardent l'hiver hors du logis encore. »"},"rh-violette":{"h":"La violette, modeste fleur des talus et des sous-bois de printemps, fut chérie des parfumeurs et des confiseurs, et les villes du Sud-Ouest en firent jadis une spécialité de pétales cristallisés au sucre. Son emblème de discrétion et de fidélité ornait les billets galants d'autrefois. La friandise à la violette en perpétue le parfum poudré, qu'il suffit de fondre dans l'eau-de-vie pour réveiller un printemps oublié.","p":"La fleur de violette était réputée adoucissante et pectorale, et l'on en faisait des sirops contre l'enrouement et la toux des enfants. On lui prêtait aussi le pouvoir d'apaiser les esprits agités et de favoriser un doux sommeil.","c":"Faire fondre les bonbons à froid en remuant peu, pour garder une teinte limpide et mauve. Cette liqueur délicate craint la lumière, qui pâlit sa couleur : la conserver à l'ombre, en flacon teinté.","d":"« Fleur qui se cache au bord du pré parfume mieux qui sait l'aimer. »"},"rh-fraise-menthe":{"h":"La fraise de nos jardins, telle que nous la connaissons charnue et vermeille, naquit d'un mariage tardif entre une fraise d'Amérique et une autre du Chili, rapportées par les voyageurs curieux des Lumières. La menthe, elle, court dans nos potagers depuis l'Antiquité, où elle parfumait déjà les eaux et les onguents. Réunir le fruit rouge et la feuille fraîche, c'est cueillir d'un même geste la chaleur et l'ombre du jardin.","p":"La fraise passait pour rafraîchissante et bonne au sang, et l'on en frottait même le visage pour l'éclat du teint ; la menthe était tenue pour stomachique et propre à dissiper les lourdeurs d'estomac. Ensemble, elles faisaient une liqueur de belle saison.","c":"N'employer la menthe qu'en feuilles entières et la retirer avant qu'elle ne noircisse et ne tourne à l'amer. Choisir des fraises pleinement parfumées, quitte à les laisser quelques heures au sucre avant de les noyer.","d":"« Fraise au soleil, menthe à l'ombrage font la fraîcheur de tout breuvage. »"},"rh-fraise-basilic":{"h":"Le basilic, herbe royale dont le nom même évoque le roi, vint de l'Inde par les jardins de la Méditerranée, où on le tint pour sacré autant que culinaire. On en glissait jadis des brins aux fenêtres pour écarter les mouches et porter bonheur au logis. Frotté contre la fraise et le citron vert, son parfum poivré et anisé révèle une alliance inattendue où l'herbe exalte le fruit.","p":"Le basilic était réputé cordial et stomachique, propre à réconforter le cœur et à dissiper les vapeurs de la mélancolie ; on lui prêtait aussi la vertu de faciliter les digestions difficiles. C'était l'herbe des humeurs joyeuses.","c":"Ajouter le basilic frais en fin de macération, quelques jours seulement, car infusé trop longtemps il vire à l'herbe coupée. Marier fraises fraîches et fraises séchées donne à la fois éclat et profondeur au parfum.","d":"« Herbe de roi sur fruit de mai parfume ce que l'on n'attendait. »"},"rh-kiwi-banane":{"h":"Le kiwi, longtemps nommé groseille de Chine, ne prit son nom d'oiseau qu'au temps où les vergers de l'autre bout du monde en firent commerce et le rebaptisèrent du petit volatile sans ailes. La banane, elle, nourrit depuis des temps immémoriaux les peuples des tropiques, où on la cuit, sèche et fermente de mille façons. Réunir ces deux fruits, c'est marier l'acidité verte des antipodes et la rondeur sucrée des îles chaudes.","p":"On prêtait à la banane une vertu nourrissante et reconstituante, propre à soutenir les forces, tandis que le kiwi, riche et acidulé, passait pour rafraîchissant et tonifiant. Adoucis de miel, ils faisaient un cordial roboratif.","c":"Choisir des kiwis bien mûrs mais fermes et des bananes à peine tachées, trop blettes elles troublent la liqueur. Le miel se substitue avec bonheur à une part du sucre pour arrondir l'ensemble.","d":"« Fruit du Sud et fruit lointain, en flacon n'en font plus qu'un. »"},"rh-kiwi-poire-noisette":{"h":"La noisette, fruit du coudrier de nos haies, fut l'une des toutes premières récoltes des hommes des forêts, qui en faisaient provision pour l'hiver bien avant les champs de blé. Sa baguette servait aux sourciers à quêter l'eau cachée, et l'arbuste passait pour porteur de secrets. Torréfiée et noyée d'eau-de-vie auprès de la poire et du kiwi, elle apporte sa note grillée et beurrée qui lie les fruits comme un fil d'automne.","p":"La noisette était tenue pour nourrissante et fortifiante, propre à redonner du corps aux convalescents ; on lui prêtait une huile douce, bonne aux poitrines fragiles. Associée à la poire, fruit réputé rafraîchissant, elle composait une liqueur de table réconfortante.","c":"Concasser et faire légèrement griller les noisettes avant macération pour en tirer tout le parfum. Filtrer cette liqueur deux fois, car la noisette laisse un dépôt huileux qu'un long repos au frais permet de clarifier.","d":"« Noisette au feu, poire au verger, font le doux soir de l'arrière-saison. »"},"rh-mangues-bananes-flambees":{"h":"La mangue, fille des forêts de l'Inde et de la Birmanie, fut vénérée jusque dans les jardins des temples avant de gagner les Antilles dans les cales des navigateurs. Son nom nous vient du tamoul 'mān-kāy' que les marchands portugais transformèrent en 'manga'. Flambée à la créole avec la banane, elle prolonge ces tables d'outre-mer où le rhum servait à parfumer autant qu'à conserver.","p":"La pulpe dorée passait pour rafraîchir les humeurs et soutenir l'estomac sous les climats brûlants, tandis que la banane était tenue pour un fruit nourrissant des convalescents.","c":"Choisir des mangues souples au parfum prononcé et des bananes encore un peu fermes, qui tiennent mieux à la flambée ; servir frais après un long repos d'au moins trois mois.","d":"« Mangue au four et banane au feu, content le ventre et content les yeux. »"},"rh-mangues-framboises":{"h":"La framboise, ronce des clairières et des lisières montagnardes d'Europe, portait jadis le nom de 'fraise des bois ligneuse' avant que les jardiniers ne l'apprivoisent. Mariée à la mangue tropicale, elle unit deux mondes : le sous-bois tempéré et la chaleur des îles. Cette alliance rappelle les cargaisons d'épices et de fruits où le Nord et le Sud se rencontraient dans le même bocal.","p":"La framboise était réputée rafraîchissante et propre à apaiser les fièvres légères, et son vinaigre passait pour adoucir les gorges enrouées.","c":"Préférer des framboises bien mûres mais fermes, ajoutées en fin de macération pour préserver leur parfum fragile ; filtrer avec soin, car leurs grains troublent volontiers la liqueur.","d":"« Framboise et mangue au même verre, font voyager sans quitter sa chaire. »"},"rh-mangues-passion":{"h":"Le fruit de la passion doit son nom aux missionnaires qui, dans les Amériques, crurent lire dans sa fleur les instruments de la Passion : la couronne d'épines et les clous. La liane, originaire du Brésil, fut bientôt cultivée sous toutes les latitudes chaudes. Unie à la mangue et à la cannelle, elle compose une liqueur d'une vivacité presque exotique.","p":"La pulpe acidulée était tenue pour tonique et désaltérante, et l'on prêtait à son infusion la vertu d'apaiser les esprits agités avant le sommeil.","c":"Récolter les fruits quand leur peau se plisse, signe de pleine maturité aromatique ; doser le sucre avec mesure, car la passion garde toujours une pointe d'acidité bienvenue.","d":"« Quand la passion ride sa peau, le nectar dedans est plus beau. »"},"rh-myrtilles-miel":{"h":"La myrtille, humble baie des landes et des sous-bois acides, teintait jadis la bouche des bergers de montagne et l'encre des copistes pressés. On la nommait 'raisin des bruyères' dans les pays du Nord, où l'on en faisait des confitures noires comme la nuit. Adoucie de miel, elle entre dans cette liqueur de veillée propre aux hauteurs.","p":"La baie était réputée resserrer le ventre et fortifier la vue des veilleurs, tandis que le miel passait pour adoucir la poitrine et baumer les gorges fatiguées.","c":"Cueillir les baies bien noires et lustrées, ou les choisir surgelées hors saison ; choisir un miel parfumé mais discret, qui souligne le fruit sans l'écraser.","d":"« Myrtille et miel font bon ménage, l'une noircit, l'autre soulage. »"},"rh-noisettes":{"h":"Le noisetier, ou coudrier, comptait parmi les arbres sacrés des anciens peuples celtes, et l'on taillait dans ses branches les baguettes des sourciers. Sa graine huileuse nourrissait les hivers bien avant les céréales cultivées. Longuement macérée, elle donne à cette liqueur une rondeur de pâtisserie ancienne, entre le pralin et la crème.","p":"La noisette était tenue pour un fruit fortifiant et nourrissant, propre à soutenir les forces des marcheurs et des moissonneurs.","c":"Torréfier légèrement les noisettes avant la macération pour révéler leur arôme, et patienter de longs mois, car ce fruit livre sa richesse avec lenteur ; filtrer deux fois pour ôter toute trace d'huile.","d":"« Noisette en bocal patiente, six lunes durant se fait plus lente. »"},"rh-orange-cannelle-vanille":{"h":"L'oranger amer voyagea des jardins de Chine vers la Perse, puis vers les vergers d'Andalousie, portant avec lui le parfum de son zeste autant que de sa fleur. Mariée à la cannelle de Ceylan et à la vanille des Amériques, l'orange compose ici un accord de comptoir d'épices, tel qu'on l'aimait aux tables de fête. Ces trois aromates réunissaient autrefois tout l'orient rêvé des marchands.","p":"Le zeste d'orange était réputé cordial et stomachique, et la cannelle passait pour réchauffer les sangs froids et faciliter les digestions lourdes de l'hiver.","c":"Ne prélever que le zeste d'oranges non traitées, en évitant le blanc amer de l'écorce ; un seul bâton de cannelle suffit, car elle domine vite tout le reste.","d":"« Orange, cannelle et vanille en chœur, font de l'hiver un verre de chaleur. »"},"rh-pamplemousse-menthe":{"h":"Le pamplemousse rose est un enfant tardif des vergers d'agrumes, né du croisement fortuit de l'orange et du pomélo dans les îles des Caraïbes. Sa chair rosée et sa pointe d'amertume en firent un fruit de table apprécié des créoles. Relevé de menthe fraîche, il donne une liqueur d'une fraîcheur presque jardinière.","p":"L'agrume était tenu pour apéritif et rafraîchissant, et la menthe passait de longue date pour réveiller les esprits assoupis et soulager les estomacs paresseux.","c":"Choisir des pamplemousses lourds et parfumés, et n'ajouter la menthe qu'en fin de macération, car ses feuilles tournent à l'amertume si on les laisse trop infuser.","d":"« Pamplemousse et menthe au jardin, rendent léger le plus lourd festin. »"},"rh-peches-citrons-verts":{"h":"La pêche, que les Romains nommaient 'malum persicum', la pomme de Perse, n'en venait pas moins de Chine, où elle symbolisait depuis des siècles la longévité. Le long des routes de la soie, son noyau parfumé fit le voyage vers l'Occident. Avivée du citron vert des tropiques, elle compose une liqueur d'été tendre et acidulée.","p":"La pulpe de pêche était réputée adoucissante et bienfaisante pour les entrailles ; on se gardait toutefois des amandes de son noyau, dont l'amertume trahit un principe dangereux à forte dose.","c":"Choisir des pêches bien mûres et fondantes, à peler avant macération pour éviter l'amertume du duvet ; presser le citron vert au dernier moment pour garder sa vivacité.","d":"« Pêche de Perse et citron vert, parfument l'été dans le verre. »"},"rh-peches-poires-framboises":{"h":"La poire, fruit des vergers tempérés cultivé depuis la haute Antiquité, comptait jadis des centaines de variétés que l'on couchait par écrit dans les pomologies des grands jardins. Réunie à la pêche et à la framboise, elle forme ici une corbeille de fin de saison, comme on en pressait pour les conserves d'automne. Trois fruits, trois textures, pour une liqueur d'une douceur ronde.","p":"La poire était tenue pour un fruit rafraîchissant et bénin, propre à délier les ventres noués, tandis que la framboise apportait sa note acidulée réputée désaltérante.","c":"Marier des poires fondantes à des pêches mûres, et ne joindre les framboises qu'en fin de course pour préserver leur fragile parfum ; une macération régulièrement remuée donne une liqueur plus harmonieuse.","d":"« Poire, pêche et framboise unies, font une corbeille en bouteille. »"},"rh-vanille-cafe":{"h":"La vanille, gousse d'une orchidée grimpante du Mexique, demeura longtemps un secret jalousement gardé par les peuples qui la mariaient déjà au cacao. Le café, lui, gagna l'Europe par les ports du Levant et les premières maisons où l'on s'attablait pour deviser. Réunis dans le rhum, ils composent une liqueur de table sombre et veloutée, digne des fins de souper.","p":"La vanille était réputée cordiale et propre à relever les esprits abattus, et le café passait pour chasser le sommeil et raviver la vivacité de l'entendement.","c":"Fendre la gousse de vanille pour libérer ses grains, et choisir un café fraîchement torréfié plutôt que moulu de longue date ; ne pas prolonger l'infusion du café, qui durcit et amertume la liqueur.","d":"« Vanille et café font bon office, l'une endort, l'autre vous hisse. »"},"rh-vanille-citrons-verts":{"h":"Le citron vert, ou lime, suivit la canne à sucre dans les plantations des îles, où marins et boucaniers le tenaient pour un rempart contre les maux des longues traversées. Sa vivacité tranche heureusement avec la rondeur sombre de la vanille. Cette alliance simple résume tout l'esprit des liqueurs créoles, où l'acide réveille le parfum.","p":"Le jus de lime était réputé tonique et propre à prévenir les langueurs des navigateurs, tandis que la vanille passait pour adoucir et réconforter les humeurs.","c":"Ne presser le jus de citron vert qu'au moment d'assembler, pour conserver sa fraîcheur, et user d'une vanille charnue et souple ; goûter avant d'achever le sucrage, car l'acidité évolue au repos.","d":"« Lime vive et vanille douce, font la liqueur qui se retrousse. »"},"rh-atemoya":{"h":"L'atémoya, fruit né du mariage de l'anone cœur-de-bœuf et du chérimole, porte un nom forgé de pièces, mêlant les langues des Amériques d'où viennent ses parents. Sa chair crémeuse, sucrée comme une crème pâtissière, en fait l'un des fruits les plus tendres des vergers tropicaux. Relevée de banane et de cannelle, elle donne une liqueur onctueuse et rare.","p":"La pulpe sucrée était tenue pour nourrissante et adoucissante ; on prenait soin d'en écarter les pépins noirs, réputés âcres et tenus pour malsains.","c":"Cueillir l'atémoya quand elle cède sous le doigt, signe de maturité parfaite, et ôter soigneusement tous les pépins ; sa chair fragile demande une filtration patiente.","d":"« Cœur tendre de l'atémoya, fond au verre comme neige au mois de mai. »"},"rh-banane-sechee":{"h":"Le séchage de la banane est un art ancien des terres chaudes, où l'on concentrait au soleil la pulpe pour traverser les saisons sans réfrigération. Séchée, elle gagne un goût de miel et de pain d'épices que le fruit frais ne connaît pas. C'est cette douceur confite que la macération vient cueillir, relevée de vanille et de cannelle.","p":"La banane séchée était tenue pour un aliment énergique et soutenant, prisé des voyageurs, et la cannelle qui l'accompagne passait pour réchauffer et faciliter la digestion.","c":"Choisir des bananes séchées moelleuses et non sucrées en sus, qui parfument sans alourdir ; surveiller la macération, car le fruit sec boit l'alcool et épaissit volontiers la liqueur.","d":"« Banane au soleil mûrie deux fois, garde l'été tout au fond du bois. »"},"rh-carambole":{"h":"La carambole, ce fruit-étoile des forêts d'Asie du Sud-Est, fut nommée 'pomme de Goa' par les marchands portugais qui la découvrirent sur les côtes de l'Inde. Tranchée, elle dessine une étoile à cinq branches qui orne les coupes des fêtes tropicales. Mariée à la rhubarbe acidulée, elle compose une liqueur claire et piquante.","p":"La carambole était réputée rafraîchissante et désaltérante ; on conseillait toutefois la modération à qui avait les reins fragiles, par prudence ancienne envers son suc acidulé.","c":"Choisir des caraboles dorées et charnues, plus douces que les vertes encore acides ; trancher en étoiles fines pour offrir la plus grande surface à la macération et filtrer pour garder la liqueur limpide.","d":"« Étoile à cinq branches dans le verre, fait briller le soir comme un éclair. »"},"rh-casse-fistula":{"h":"La casse fistula, ou casse des boutiques, est le fruit en long bâton du Cassia fistula, arbre des Indes orientales dont la pulpe noire et sucrée voyagea longtemps dans les officines d'apothicaires. On la mariait aux préparations médicinales pour en adoucir l'amertume, et la réglisse qui l'accompagne ici prolonge cette tradition de douceur de comptoir. Sous les tropiques, on nommait volontiers l'arbre « pluie d'or » pour ses grappes jaunes pendantes.","p":"La pulpe de casse était réputée laxative et rafraîchissante, prescrite comme remède doux pour relâcher les humeurs ; à dose mesurée seulement, car la pulpe agit franchement sur les entrailles. La réglisse passait pour adoucir la gorge et apaiser les âcretés.","c":"Choisir des gousses bien noires et souples, dont la pulpe colle au doigt ; filtrer soigneusement pour retenir les fibres ligneuses. Se sert frais, en très petit verre digestif après le repas.","d":"« Casse en bâton, réglisse en chemin, font le ventre léger au matin. »"},"rh-cempedak":{"h":"Le cempedak, cousin du jacquier, mûrit dans les forêts moites de la péninsule malaise et de Bornéo, où sa chair dorée embaume jusque sous les arbres. Les villageois le consommaient frais, frit ou fermenté, et sa parenté avec le jaque en fait l'un de ces fruits-géants que les marchands d'épices rapportaient des îles. La citronnelle et la cannelle qui l'escortent rappellent les marchés de l'Insulinde.","p":"Le cempedak, fruit nourrissant, était tenu pour réconfortant et fortifiant chez les peuples qui en faisaient un mets de fête. La citronnelle passait pour assainir et faciliter la digestion des plats lourds.","c":"N'employer qu'un fruit pleinement mûr, à la chair fondante et parfumée, car vert il reste fade. Une citronnelle fraîchement froissée libère mieux ses huiles ; servir frais, en fin de repas exotique.","d":"« Fruit des îles longuement mûri, parfume le verre et réjouit l'esprit. »"},"rh-corossol":{"h":"Le corossol, fruit hérissé de l'Annona muricata, vient des Amériques tropicales d'où il gagna l'Afrique et l'Asie au gré des navigations. Sa chair blanche, acidulée et crémeuse, fut prisée en boissons et en sorbets dès que le sucre la rendit accessible. Le macis et le piment-oiseau qui l'accompagnent rappellent les comptoirs où fruits doux et épices ardentes se côtoyaient.","p":"La pulpe du corossol était réputée rafraîchissante et calmante, et l'on prêtait à ses feuilles en infusion des vertus apaisantes pour le sommeil. Le macis passait pour tonique et le piment pour réveiller les langueurs de l'estomac, à user d'une main légère.","c":"Cueillir le fruit juste mou sous le pouce, avant qu'il ne tourne, et le débarrasser de ses pépins amers. Doser le piment avec retenue pour ne pas masquer la chair ; servir bien frais.","d":"« Chair de neige et feu caché, font le cœur du buveur étonné. »"},"rh-dattes":{"h":"La datte, fruit du palmier-dattier, nourrit depuis les temps les plus reculés les caravanes des déserts d'Orient et du Maghreb, où on la nommait « pain du voyageur ». Confite par le soleil, riche en sucres, elle entrait dans les sirops et les conserves des oasis. L'anis et la cannelle qui l'accompagnent ici évoquent les routes d'épices qui croisaient celles du dattier.","p":"La datte était tenue pour très nourrissante et reconstituante, donnée aux faibles et aux marcheurs épuisés pour refaire les forces. L'anis passait pour chasser les vents et la cannelle pour réchauffer l'estomac alangui.","c":"Choisir des dattes moelleuses et charnues, dénoyautées, sans excès de cristallisation ; l'anis se mesure avec mesure, car il domine vite. Laisser reposer longuement et servir à température de chambre.","d":"« Datte du désert et grain d'anis, réchauffent qui les boit la nuit. »"},"rh-feijoa":{"h":"Le feijoa, ou goyavier du Brésil, est le fruit d'un arbuste des hautes terres sud-américaines, à la chair granuleuse au parfum d'ananas et de menthe. Acclimaté plus tard sur les rivages tempérés, il y devint curiosité de jardin et de table. Le genièvre et la cardamome qui l'escortent ici lui prêtent une fraîcheur résineuse digne d'un cordial du Nord.","p":"Le feijoa, fruit acidulé et odorant, était apprécié comme rafraîchissant et tonique du palais. Le genièvre passait pour aider la digestion et soutenir les reins, et la cardamome pour parfumer l'haleine et réveiller l'appétit.","c":"Cueillir le fruit tombé ou cédant à peine sous la pression, car il développe alors tout son arôme ; en gratter la pulpe à la cuiller. La cardamome se concasse au dernier moment ; servir frais.","d":"« Goyave du Sud et baie du Nord, s'accordent au verre sans discord. »"},"lq-liqueur-de-cacao":{"h":"Le cacaoyer, arbre des forêts d'Amérique centrale, livre des fèves que les peuples mésoaméricains tenaient pour si précieuses qu'ils en faisaient monnaie et breuvage sacré. Rapporté en Europe par les navigateurs, le chocolat y devint d'abord boisson de cour, amère puis adoucie de sucre et d'épices. La cannelle et la vanille qui l'accompagnent ici fidèlement rappellent ces premiers chocolats parfumés.","p":"Le cacao était réputé fortifiant, cordial et propre à relever les esprits abattus ; on le disait nourrissant comme un aliment autant que flatteur au goût. La cannelle et la vanille passaient pour réchauffer et réjouir le cœur.","c":"Préférer un cacao non sucré de bonne origine, bien amer, et le délayer sans grumeaux avant l'alcool. La liqueur s'éclaircit en reposant ; laisser décanter longuement et soutirer délicatement le clair au-dessus du dépôt.","d":"« Fève brune et longue patience, font la liqueur de connivence. »"},"lq-liqueur-de-cafe":{"h":"Le caféier, originaire des hautes terres d'Éthiopie, gagna l'Arabie puis l'Europe où les maisons de café devinrent lieux de commerce et de causerie. La fève torréfiée, longtemps réservée à l'infusion chaude, se prêta vite aux liqueurs où l'alcool capte son amertume parfumée. On en faisait un breuvage d'esprits éveillés autant que de gosiers gourmands.","p":"Le café était réputé tenir l'esprit en éveil et dissiper les somnolences, et passait pour aider la digestion des repas lourds. On le buvait volontiers après table, comme tonique du soir.","c":"Concasser grossièrement des grains fraîchement torréfiés plutôt que d'employer de la poudre, qui trouble la liqueur. Goûter à mesure, car le café fonce et amertume avec le temps ; filtrer sur tissu serré.","d":"« Grain torréfié dans l'alcool dort, et tient l'esprit en éveil encor. »"},"lq-liqueur-de-camomille":{"h":"La camomille, petite fleur des champs au cœur d'or, était cueillie de longue date dans les jardins de simples et les herbiers monastiques. Son nom, venu du grec, évoque la « pomme à terre » pour son odeur de fruit ; on en bordait les allées et les pelouses parfumées. De tout temps on la réserva aux tisanes du soir et aux remèdes domestiques.","p":"La camomille était réputée apaisante et propre à calmer les digestions difficiles comme les nerfs agités ; on la donnait volontiers avant le coucher. On lui prêtait aussi la vertu d'adoucir les coliques légères.","c":"N'employer que les capitules bien ouverts et fraîchement séchés, à l'arôme franc, sans excès qui rendrait la liqueur amère. Une macération trop longue tourne au foin ; goûter et arrêter dès le parfum venu.","d":"« Fleurette d'or au soir cueillie, berce le buveur jusqu'au lit. »"},"lq-liqueur-de-cannelle-1":{"h":"La cannelle, écorce roulée du cannelier de Ceylan, fut l'une des épices les plus convoitées des routes maritimes, valant naguère son pesant d'or aux comptoirs d'Orient. Les apothicaires et les marchands se la disputaient pour les vins épicés et les confiseries des grandes tables. Mariée au rhum brun, elle retrouve la chaleur des hypocras d'autrefois.","p":"La cannelle était réputée cordiale et stomachique, propre à réchauffer le corps et à fortifier l'estomac affaibli ; on la tenait pour souveraine contre les froidures de l'hiver. On lui prêtait aussi la vertu de relever les défaillances.","c":"Préférer des bâtons fins de cannelle de Ceylan, plus suave que la cannelle commune, et les rompre pour libérer l'arôme. La macération gagne à rester mesurée, car l'écorce devient âpre ; servir à température douce.","d":"« Écorce d'or aux longs voyages, met de l'été dans les frimas d'âge. »"},"lq-liqueur-de-cannelle-2":{"h":"Cette seconde façon marie l'écorce de cannelle à la pomme golden, accord ancien des cuisines du Nord où la pomme fondue et l'épice chaude composaient compotes et beignets d'automne. La cannelle, écorce précieuse venue de Ceylan par les routes des épices, donne à la pomme sa note de pâtisserie chaude. C'est la mémoire des vergers et des âtres réunie dans un même verre.","p":"La cannelle était réputée stomachique et réchauffante, et la pomme passait pour rafraîchissante et bonne au ventre ; ensemble on les disait propres à réjouir l'estomac. On tenait ce mariage pour aimable aux digestions paresseuses.","c":"Choisir des pommes golden bien mûres et sucrées, coupées sans le cœur, pour une chair douce qui parfume sans aigreur. Filtrer après la macération pour ôter la pulpe ramollie ; laisser reposer avant de goûter.","d":"« Pomme du verger, cannelle au logis, content le palais et le pays. »"},"lq-liqueur-de-carvi":{"h":"Le carvi, dont la graine ressemble au cumin, croît dans les prairies d'Europe et fut de longue date semé pour parfumer pains, fromages et choux des pays du Nord. Les Anciens le nommaient cumin des prés, et les herbiers le rangeaient parmi les graines carminatives des cordiaux domestiques. On en aromatisait aussi les dragées de fin de banquet.","p":"Le carvi était réputé carminatif et digestif, propre à chasser les vents et apaiser les ballonnements après les repas copieux. On le donnait volontiers aux estomacs lents et aux enfants pour les coliques légères.","c":"Écraser légèrement les graines bien sèches juste avant de les mettre à macérer, pour qu'elles rendent leur huile. Le carvi enivre vite la liqueur de son parfum ; surveiller la durée et filtrer dès l'arôme jugé suffisant.","d":"« Graine des prés au repas du soir, fait le ventre en paix et l'humeur en joie. »"},"lq-liqueur-de-cassis-1":{"h":"Le cassis, baie noire du groseillier noir, fut longtemps cultivé dans les jardins et les haies pour ses fruits et ses feuilles odorantes, et c'est en Bourgogne qu'il connut sa plus belle fortune en ratafias et liqueurs. Son parfum musqué et profond en fit l'âme de bien des cordiaux régionaux. On le tenait pour une baie de santé autant que de plaisir.","p":"Le cassis était réputé tonique et propre à soulager les rhumatismes, et l'on prêtait à ses feuilles comme à ses fruits des vertus diurétiques et fortifiantes. On en faisait volontiers une liqueur de réconfort.","c":"Choisir des grappes bien mûres, noires et fermes, égrappées et légèrement écrasées pour libérer le jus. La couleur et le parfum demandent du temps ; laisser macérer longuement et filtrer avec soin pour la limpidité.","d":"« Baie de Bourgogne au noir velours, fait la liqueur des longs séjours. »"},"lq-liqueur-de-cassis-2":{"h":"Cette variante unit le cassis à la framboise et aux épices de chambre, girofle et macis, à la manière des ratafias parfumés des tables d'autrefois. Le cassis, baie reine des jardins bourguignons, y trouve dans la framboise une complice plus suave et plus rouge. C'est un accord de vergers et de comptoir, où le fruit noir s'allège d'une note pourpre.","p":"Le cassis était réputé tonique et la framboise rafraîchissante et bonne aux fièvres légères ; les épices de girofle et de macis passaient pour réchauffer et faciliter la digestion. On tenait l'ensemble pour un cordial réjouissant.","c":"Mêler des fruits bien mûrs en gardant le cassis dominant, la framboise n'apportant qu'une touche ; girofle et macis se dosent par pincées pour ne pas couvrir le fruit. Filtrer finement, car les petites baies troublent la liqueur.","d":"« Cassis et framboise au même flacon, mêlent le pourpre et le noir bien bon. »"},"lq-liqueur-de-cerfeuil":{"h":"Le cerfeuil, fine ombellifère des potagers, parfumait de longue date les soupes et les sauces du printemps, et son nom venu du grec signifie « feuille qui réjouit ». Les jardins monastiques le tenaient parmi les herbes aromatiques et médicinales. Ici il s'associe à la menthe et à l'absinthe pour un cordial vert d'inspiration ancienne.","p":"Le cerfeuil était réputé dépuratif et bon pour le sang au renouveau du printemps, et la menthe stomachique et rafraîchissante. L'absinthe, en revanche, doit être maniée avec prudence et parcimonie, car son essence renferme la thuyone, principe nuisible à forte dose : on n'en mettra qu'un soupçon.","c":"Employer du cerfeuil fraîchement cueilli et la menthe juste froissée pour garder le vert et l'arôme ; ne glisser l'absinthe qu'en très petite quantité. Filtrer tôt et servir frais, en très petit verre.","d":"« Herbe verte au soupçon d'amertume, se boit menu de peur qu'on s'enrhume. »"},"lq-liqueur-de-cerises-noires":{"h":"La cerise noire, fille du merisier des bois domestiqué au fil des siècles, fut longtemps la confidente des vergers monastiques, où l'on guignait sa chair sombre pour les conserves d'hiver. Son nom même évoque la guigne, ce fruit charnu et presque noir que l'on mettait à confire dans l'eau-de-vie dès que la saison déclinait. Les régions du Nord-Est, friandes de kirsch, en firent un trésor de fin de repas.","p":"La cerise était tenue pour rafraîchissante et bénéfique au sang ; on prêtait à sa queue, infusée à part, des vertus dépuratives. On se gardera toutefois de laisser les noyaux concassés macérer trop longuement, car l'amande qu'ils renferment libère un principe amer apparenté au cyanure.","c":"Choisir des cerises bien noires et fermes, à peine cueillies, en écartant les fruits éclatés. Une longue patience au sombre et une mise en bouteille à l'abri de la lumière préservent la robe rubis presque grenat.","d":"« Cerise noire en bocal close, garde au cœur l'été qui repose. »"},"lq-liqueur-facon-chartreuse-jaune":{"h":"Les liqueurs de plantes à la robe dorée descendent en droite ligne des élixirs des cloîtres, où l'on assemblait racines, semences et safran selon des recettes jalousement gardées. L'angélique, dite parfois herbe des anges, et la badiane y tenaient le premier rang, mariées au carvi et au fenouil. Le safran, plus précieux que l'or à poids égal, leur prêtait sa teinte de miel et son parfum de noblesse.","p":"Ce mariage de semences et de racines était réputé souverain pour soutenir l'estomac et réchauffer les humeurs après les agapes. L'angélique passait pour fortifiante et cordiale, tandis que le safran, à dose mesurée, était dit réjouir le cœur.","c":"Doser le safran avec retenue, quelques filaments suffisant à colorer et parfumer, sous peine d'amertume médicinale. Laisser reposer plusieurs semaines après filtration, le temps que les arômes de racine s'accordent à ceux des graines.","d":"« Or de safran et herbe d'ange, font la liqueur que rien n'égale. »"},"lq-liqueur-facon-chartreuse-verte":{"h":"Les élixirs verts des chartreux passent pour les plus secrets des breuvages d'herbes, assemblant des dizaines de simples cueillis à la rosée. Menthe, mélisse, sauge et coriandre y donnent la fraîcheur, quand l'angélique en soutient l'ossature aromatique. La couleur verte, autrefois, naissait de la chlorophylle même des feuilles longuement infusées, sans nul artifice.","p":"On disait ces liqueurs propres à raffermir l'estomac et à dissiper les lourdeurs, la sauge passant pour conserver et la mélisse pour apaiser. La tanaisie, qui entre ici, demande prudence : ses fleurs, riches en thuyone, ne sauraient figurer qu'en très petite mesure, car à forte dose la plante devient nuisible.","c":"Réserver la tanaisie à quelques pétales seulement et privilégier les herbes fraîches, cueillies par temps sec. Une double macération, courte puis longue, permet d'extraire la verdeur sans tomber dans l'âcreté.","d":"« Trente herbes en un seul verre, content le ciel et désaltèrent. »"},"lq-liqueur-de-cherry-brandy":{"h":"Le cherry brandy, dont le nom anglais trahit l'engouement d'outre-Manche pour la cerise à l'eau-de-vie, descend des ratafias de guignes que l'on relevait d'épices chaudes. Cerises noires et aigres s'y disputent la place, tempérées de framboise, cannelle et girofle. Ce fut longtemps la liqueur des soirées d'hiver, servie au coin de l'âtre dans de petits verres taillés.","p":"On lui prêtait une chaleur cordiale, bienvenue contre les frimas, la cannelle et le girofle étant réputés stimuler la digestion. Les noyaux, si on les emploie, doivent rester en faible nombre, car leur amande recèle un principe toxique qu'une longue macération libère.","c":"Marier cerises douces et aigres pour un équilibre franc, et n'ajouter les épices qu'avec mesure afin de ne pas masquer le fruit. Filtrer après un mois, puis laisser vieillir : le bouquet n'en sera que plus rond.","d":"« Guigne et girofle au même verre, font l'hiver moins long à traverser. »"},"lq-liqueur-de-chicoree":{"h":"La chicorée, plante des bords de chemins à la fleur d'un bleu tendre qui se ferme à midi, fut nommée par les Anciens un mets autant qu'un remède. Ses fleurs et ses racines accompagnèrent longtemps les tables du Nord, où la racine torréfiée remplaça le café aux temps de disette. On la cueillait au matin, avant que le soleil n'eût refermé ses corolles.","p":"La chicorée était tenue pour amie du foie et de la digestion, son amertume passant pour ouvrir l'appétit et purifier les humeurs. On la disait rafraîchissante et propre à régler les voies de la bile.","c":"Cueillir les fleurs au lever du jour, lorsqu'elles sont pleinement ouvertes, et les employer sans tarder car elles se fanent vite. Le girofle, employé d'une main légère, en arrondit l'amertume native.","d":"« Fleur de chicorée au matin, ferme l'œil sitôt midi venu. »"},"lq-liqueur-de-citron":{"h":"Le citron, venu d'Orient par les routes anciennes avant de gagner les rivages méditerranéens, fut d'abord fruit de jardin princier autant que remède de marins. Sa liqueur, parente du limoncello des côtes du Sud, ne retient que l'huile parfumée des zestes, où réside toute l'âme du fruit. On la servait glacée, après le repas, comme une promesse de fraîcheur.","p":"Le citron était réputé tonique et propre à rafraîchir le sang, son zeste passant pour aiguiser l'appétit et soutenir l'estomac. On lui prêtait aussi le pouvoir d'assainir et de fortifier.","c":"N'employer que des citrons non traités, en ne prélevant que le zeste jaune sans la peau blanche, amère et ingrate. Servir bien frappé, sorti tout droit de la glacière, dans de petits verres givrés.","d":"« Zeste de citron, point de blanc, garde la liqueur sans tourment. »"},"lq-liqueur-de-clementines":{"h":"La clémentine, née tardivement d'un heureux croisement entre mandarinier et bigaradier dans les jardins d'Afrique du Nord, doit son nom à un religieux jardinier qui l'aurait remarquée. Fruit d'hiver par excellence, elle parfume les fêtes de fin d'année de son zeste odorant. Sa liqueur prolonge dans la coupe la douceur acidulée de la saison froide.","p":"Comme ses cousins agrumes, la clémentine était réputée tonique et rafraîchissante, propre à réjouir et à ouvrir l'appétit. Son zeste parfumé passait pour soutenir agréablement la digestion des repas de fête.","c":"Préférer des clémentines non traitées à la peau fine et bien parfumée, en travaillant surtout les zestes. Servie fraîche après le dessert, elle s'accorde aux pâtisseries d'épices de la saison.","d":"« Clémentine au temps des veillées, met l'été dans l'hiver enfermé. »"},"lq-liqueur-de-coing":{"h":"Le coing, fruit antique du cognassier, fut chez les Anciens consacré aux symboles d'amour et de bonheur, offert lors des noces avant qu'il ne devînt fruit de confiturier. Dur et âpre cru, il ne livre son parfum de miel et de rose qu'à la cuisson ou à la macération. Sa pâte et sa gelée d'or ambré garnissaient jadis les buffets d'automne.","p":"Le coing était tenu pour resserrant et bénéfique aux entrailles, sa chair astringente passant pour apaiser les flux. On usera des amandes amères avec parcimonie, car émondées et trop nombreuses elles libèrent un principe apparenté au cyanure.","c":"Choisir des coings bien mûrs, dorés et odorants, et les essuyer du duvet qui les couvre avant de les râper. Quelques amandes amères suffisent à relever sans danger le parfum du fruit.","d":"« Coing trop dur pour la dent crue, devient miel dans l'alcool tenu. »"},"lq-liqueur-de-coquelicot":{"h":"Le coquelicot, fleur fragile des moissons qui rougit les blés d'été, fut de tout temps lié au sommeil et au repos, cousin paisible du pavot. Ses pétales chiffonnés, d'un écarlate vif, donnent une liqueur d'un rouge profond et d'un parfum délicat. On les cueillait au champ, à la fraîche, avant que le vent ne les eût dispersés.","p":"Le coquelicot était réputé adoucissant et propice au calme, ses pétales passant pour apaiser la toux et favoriser un sommeil léger. On le tenait pour une fleur paisible, amie des nuits sereines.","c":"Récolter les pétales par temps sec, sans la base noire qui les amertume, et les employer aussitôt car ils perdent vite leur couleur. Une pointe de cannelle suffit à soutenir leur parfum sans l'écraser.","d":"« Pétale de coquelicot fané, dans l'alcool reprend sa rougeur d'été. »"},"lq-liqueur-douce-de-coriandre":{"h":"La coriandre, dont les graines parfumées furent trouvées jusque dans les tombeaux des pharaons, compte parmi les plus vieilles épices cultivées par l'homme. Son nom grec, qui rappelle la punaise, évoque l'odeur âcre de la plante fraîche, bien différente du parfum chaud et citronné de la graine mûre. Les apothicaires d'autrefois la mêlaient au vin pour en relever la saveur.","p":"La graine de coriandre était réputée carminative et amie de l'estomac, propre à dissiper les vents et à faciliter la digestion. On la disait aussi tonique, capable de réveiller doucement les appétits paresseux.","c":"Concasser légèrement les graines pour en libérer l'huile, et choisir des semences mûres, dorées et odorantes. Le mariage du vin blanc et de l'eau-de-vie demande un repos prolongé pour fondre les saveurs.","d":"« Graine de coriandre au vin mêlée, rend la table mieux digérée. »"},"lq-liqueur-de-cumin":{"h":"Le cumin, semence dorée venue d'Orient, fut une épice si prisée des Anciens qu'elle servait parfois de monnaie d'échange et de symbole de fidélité. Son parfum chaud et terreux relevait les pains et les fromages bien avant de parfumer les liqueurs. Marié au citron, il donne un breuvage à la fois épicé et vif.","p":"Le cumin était tenu pour souverain contre les lourdeurs et les ballonnements, réputé carminatif et propre à réchauffer le ventre. On lui prêtait aussi la vertu d'aiguiser l'appétit avant le repas.","c":"Faire revenir un instant les graines à sec avant la macération réveille leur parfum, sans les laisser brunir. Le zeste de citron, ajouté à la fin, en allège la saveur terreuse.","d":"« Pincée de cumin au fond du verre, allège le ventre et désaltère. »"},"lq-liqueur-de-curacao":{"h":"Le curaçao tire son nom d'une île des Antilles où poussait une orange amère, descendante sauvage des arbres apportés par les navigateurs. C'est l'écorce séchée de cette bigarade, presque immangeable fraîche, qui livre à la liqueur son amertume noble et son parfum puissant. Le bois de Pernambouc, jadis, lui prêtait sa teinte d'ambre clair.","p":"L'écorce d'orange amère était réputée tonique et stomachique, propre à fortifier l'estomac et à relever les appétits engourdis. On la tenait pour amie de la digestion, son amertume passant pour bienfaisante après les repas.","c":"Sécher soigneusement les écorces de bigarade et n'en garder que la partie colorée, la peau blanche apportant une amertume trop crue. Cannelle et girofle, employés avec mesure, en arrondissent le caractère.","d":"« Orange amère et sèche écorce, font la liqueur d'autant plus forte. »"},"lq-liqueur-de-cynorrhodon-gratte-cul":{"h":"Le cynorrhodon, fruit écarlate de l'églantier que la sagesse populaire nomme sans façon gratte-cul, doit ce surnom au poil irritant de ses graines, dont les enfants faisaient autrefois farce. Cueilli après les premières gelées, lorsqu'il devient blet et sucré, il fut longtemps une réserve de douceur pour les fins d'automne. On en tirait gelées et confitures dans les campagnes.","p":"Le cynorrhodon était fort estimé comme fortifiant et restaurant, réputé soutenir les forces durant la saison froide. On le tenait pour ami des défenses du corps et propre à raffermir les constitutions affaiblies.","c":"Attendre que les fruits soient bien mûrs et blets, après les gelées, et les ouvrir pour ôter le poil intérieur qui démange. Une longue macération sur sucre candi adoucit l'âpreté de l'églantier.","d":"« Gratte-cul pris après la gelée, en douceur s'est métamorphosé. »"},"lq-liqueur-de-figues":{"h":"La figue, fruit des civilisations méditerranéennes, fut chantée comme un présent du soleil et figurait aux tables les plus anciennes, fraîche ou séchée pour l'hiver. Son arbre, le figuier, passait pour protecteur et nourricier, et son fruit melliflu n'avait nul besoin de sucre pour combler. Mûre à point, la figue libère dans l'alcool tout son miel et son parfum confit.","p":"La figue était réputée adoucissante et nourrissante, son suc passant pour apaiser les gorges enrouées et soutenir les forces. On la tenait pour un fruit doux aux entrailles, ami des digestions paresseuses.","c":"N'employer que des figues bien mûres, fondantes et lourdes, à la peau prête à se fendre. Une courte macération suffit, le fruit livrant vite ses arômes ; une gousse de vanille en prolonge la rondeur.","d":"« Figue mûre à se fendre, dans l'alcool n'a rien à attendre. »"},"lq-liqueur-de-fraises":{"h":"La fraise cultivée que nous connaissons naît au XVIIIe siècle du croisement fortuit de deux espèces venues d'Amérique, dont la fraise du Chili rapportée par l'ingénieur Frézier — patronyme que la rumeur a plaisamment rapproché du fruit. Avant elle, l'Europe ne goûtait que les menues fraises des bois, ramassées sous les ronciers et tenues pour un mets de table princière. On la mariait volontiers au vin et aux épices douces pour en relever le parfum fugace.","p":"La fraise passait pour rafraîchissante et amie de la peau ; on lui prêtait la vertu d'apaiser les humeurs échauffées et de réjouir le cœur des convalescents.","c":"Choisir des fraises odorantes et bien rouges à cœur, cueillies à pleine maturité ; un trait de citron et un soupçon de cannelle soutiennent leur arôme volatil sans le masquer. Servir frais, après un repos d'au moins quarante jours.","d":"« Fraise au parfum vite enfui, se garde en flacon jusqu'à l'hiver gris. »"},"lq-liqueur-de-fraises-a-la-cannelle":{"h":"La fraise des bois, modeste et sauvage, fut la seule fraise d'Europe durant des siècles ; on la trouvait en lisière des taillis, et les herboristes la cultivaient déjà dans les jardins de cloître pour ses feuilles autant que pour ses fruits. Son parfum concentré, jugé supérieur à celui des grosses fraises de jardin, la fit longtemps préférer des gourmets. L'usage de la rehausser de cannelle, épice de chambre des banquets médiévaux, ennoblissait ce fruit des sous-bois.","p":"On disait la fraise des bois tonique et rafraîchissante, et la cannelle réputée réchauffer l'estomac ; ensemble, on les tenait pour aimables aux digestions paresseuses.","c":"Récolter les fraises des bois par temps sec, le matin, car leur arôme s'évente vite ; doser la cannelle d'une main légère pour qu'elle escorte le fruit sans le dominer.","d":"« Petite fraise et brin d'écorce, au verre donnent grande force. »"},"lq-liqueur-douce-de-fraises-a-la-vanille":{"h":"La fraise et la vanille forment une alliance de fortune récente, car la gousse, gardée jalousement par les peuples du Mexique, ne se répandit en Europe qu'avec la conquête du Nouveau Monde. Longtemps réservée aux tables fortunées tant elle coûtait cher, la vanille adoucit ici l'acidité vive de la fraise. Cette douceur en fait une liqueur de dame, légère et parfumée.","p":"La vanille était réputée cordiale et réconfortante, propre à relever les esprits abattus, tandis que la fraise passait pour rafraîchir le sang ; on en faisait volontiers une boisson de fête.","c":"Fendre la gousse de vanille dans sa longueur pour en libérer les graines parfumées ; choisir des fraises bien mûres et sucrées, et laisser reposer trois semaines à l'abri de la lumière.","d":"« Vanille et fraise au même flacon, font d'un sirop une chanson. »"},"lq-liqueur-de-framboises":{"h":"La framboise tire son nom du vieux mot désignant la ronce des bois, et l'on en cueillait les fruits sur les coupes forestières bien avant qu'on songeât à les cultiver. Les anciens herbiers la classaient parmi les ronces du mont Ida, d'où son nom savant, et la disaient née sur les pentes de cette montagne de Crète. Fragile et vite gâtée, elle se prêtait admirablement à la conservation dans l'eau-de-vie.","p":"On prêtait à la framboise des vertus rafraîchissantes et adoucissantes pour la gorge ; son vinaigre passait jadis pour calmer les fièvres et étancher la soif des malades.","c":"Travailler des framboises parfaitement saines, car un seul fruit gâté trouble toute la macération ; un clou de girofle et un point de vanille en arrondissent la vivacité. Filtrer avec patience à travers un linge fin.","d":"« Framboise qui rougit au bois, parfume longtemps le buffet de noix. »"},"lq-liqueur-de-genievre":{"h":"La baie de genièvre, fruit bleu-noir du genévrier des landes et des garrigues, parfume les liqueurs du Nord depuis que les distillateurs flamands en firent l'âme de leur eau-de-vie. On en brûlait jadis les rameaux pour assainir l'air des chambres de malades, et son bois servait aux fumaisons. Sa saveur résineuse et poivrée la distingue de toute autre épice de nos contrées.","p":"Le genièvre était tenu pour souverain des reins et de la digestion, réputé chasser les vents et réchauffer les corps engourdis ; on le recommandait toutefois avec mesure, sa chaleur étant jugée trop vive pour les tempéraments échauffés.","c":"Concasser légèrement les baies bien mûres et noires pour qu'elles rendent leur parfum ; un alcool un peu plus fort en extrait mieux les résines. Laisser mûrir longuement pour adoucir la verdeur.","d":"« Baie de genièvre au teint d'orage, réchauffe le ventre du grand âge. »"},"lq-liqueur-de-girofle-frais":{"h":"Le clou de girofle est le bouton floral séché d'un arbre des îles Moluques, ces fameuses « îles aux épices » que les navigateurs se disputèrent âprement. Si précieux qu'on le comptait jadis à poids d'or, il parfumait les pommes d'ambre et les épices de chambre des cours princières. Marié ici à l'orange, il compose un accord chaud et balsamique cher aux liqueuristes d'autrefois.","p":"Le girofle passait pour fortifier l'estomac, assainir l'haleine et apaiser le mal de dents, vertu pour laquelle on le mâchait ; sa chaleur intense commandait toutefois de n'en user qu'avec retenue.","c":"User des clous avec parcimonie, car leur puissance domine vite l'ensemble ; les zestes d'orange non traitée, prélevés sans la peau blanche amère, en équilibrent l'ardeur. Goûter en cours de macération pour arrêter à point.","d":"« Qui du girofle abuse au verre, n'y goûte plus que l'amertume austère. »"},"lq-liqueur-de-gingembre":{"h":"Le gingembre, racine noueuse venue d'Orient, voyagea le long des routes des épices bien avant l'ère des grandes navigations ; les Romains le connaissaient déjà, et le Moyen Âge en raffolait dans ses sauces et ses dragées. On en confisait les rhizomes au miel pour les conserver, et nul banquet d'apparat ne s'en passait. Sa morsure poivrée et citronnée en fit l'épice des cordiaux réchauffants.","p":"Le gingembre était réputé échauffer l'estomac, exciter l'appétit et ranimer les sangs froids ; on le tenait pour un remède aux digestions lourdes et un cordial des temps frileux.","c":"Choisir un rhizome ferme et charnu, à la peau lisse ; le râper finement libère davantage de feu qu'un simple tronçon. Une pincée de safran lui prête sa robe d'or sans en troubler le goût.","d":"« Racine qui mord et qui pique, rend la froidure moins inique. »"},"lq-liqueur-de-graines-de-fenouil-1":{"h":"Le fenouil, ombellifère du pourtour méditerranéen, fournit des graines anisées que l'Antiquité tenait pour aliment des athlètes et symbole de vigueur. On en semait jadis aux portes pour éloigner les esprits malins, et les jeûneurs en mâchaient pour tromper la faim. Ses semences parfument depuis longtemps pains, dragées et liqueurs digestives.","p":"La graine de fenouil était réputée carminative et amie de la digestion, propre à dissiper les vents et à rafraîchir l'haleine ; les nourrices en usaient pour favoriser la montée du lait.","c":"Écraser légèrement les graines au mortier juste avant la macération pour en réveiller l'huile parfumée ; cannelle et girofle, dosés discrètement, en soutiennent la note anisée. Filtrer finement, car les semences laissent un fin limon.","d":"« Graine de fenouil après le repas, allège le ventre et délie le pas. »"},"lq-liqueur-de-graines-de-fenouil-2":{"h":"Le mariage du fenouil et de l'anis vert relève d'une vieille parenté de saveurs, car ces deux ombellifères partagent l'anéthol, cette essence qui leur donne leur parfum commun. Les liqueuristes méridionaux ont de tout temps joué de cet accord, parfois avec la badiane venue de Chine, étoile à huit branches longtemps mystérieuse. Cette simplicité fait toute la finesse d'un digestif anisé.","p":"Fenouil et anis passaient l'un comme l'autre pour apaiser les coliques et faciliter les digestions difficiles ; on les recommandait après les repas trop copieux pour soulager l'estomac alourdi.","c":"Doser anis et fenouil à parts égales pour un accord franc, ou laisser le fenouil dominer pour plus de rondeur ; un alcool de fruit neutre laisse mieux parler les semences. Goûter avant d'arrêter, l'anis prenant vite le dessus.","d":"« Anis et fenouil de compagnie, font au gosier douce harmonie. »"},"lq-liqueur-de-groseilles":{"h":"La groseille à grappes, perle translucide des jardins du Nord, fut longtemps cultivée dans les vergers de cloître pour ses fruits acidulés et sa gelée vermeille. On la nommait jadis « grouseille », et son acidité vive en faisait l'amie des sauces aigres-douces des grandes tables. Rouge ou blanche, elle se prête à merveille aux liqueurs claires et désaltérantes.","p":"La groseille était tenue pour rafraîchissante et apéritive, propre à étancher la soif des fiévreux et à tempérer la bile ; on la donnait volontiers l'été aux estomacs échauffés.","c":"Égrener les grappes avec soin, en ôtant les fruits verts qui apportent une âpreté désagréable ; sucrer généreusement pour contrebalancer l'acidité naturelle. Servir bien frais, en fin de repas estival.","d":"« Groseille en grappe au soleil mûrie, rend la soif d'été réjouie. »"},"lq-liqueur-de-jasmin":{"h":"Le jasmin, dont le nom nous vient de la Perse à travers les langues d'Orient, fut introduit dans nos jardins par les navigateurs qui en rapportèrent les boutures odorantes. Les parfumeurs de Grasse en firent l'une de leurs fleurs reines, tant son arôme est puissant et délicat à la fois. Cueillie à la nuit tombante, quand son parfum s'exhale le plus fort, sa fleur compose une liqueur d'une rare élégance.","p":"On prêtait au jasmin des vertus apaisantes et réjouissantes pour l'âme ; son odeur passait pour dissiper la mélancolie et adoucir les humeurs chagrines.","c":"Cueillir les fleurs fraîchement écloses, de préférence au soir, et n'user que de variétés odorantes et non traitées ; une macération courte suffit, car une infusion trop longue tourne à l'entêtant. Filtrer dès le parfum obtenu.","d":"« Fleur de jasmin cueillie à la brune, embaume le flacon mieux qu'aucune. »"},"lq-liqueur-de-kaki":{"h":"Le kaki, fruit de l'arbre que les botanistes nomment plaqueminier, nous vient d'Extrême-Orient où on le révère depuis des siècles, et son nom savant évoque le « pain des dieux ». Tardif, il pare les jardins de ses lanternes orangées quand les feuilles sont tombées. Cueilli encore ferme, il faut attendre qu'il devienne blet et tendre pour que disparaisse son astringence et se révèle sa douceur de miel.","p":"Le kaki bien mûr était tenu pour nourrissant et adoucissant ; on le rangeait parmi les fruits d'automne réconfortants, sa pulpe melliflue passant pour amie des gorges sèches.","c":"N'employer que des kakis parfaitement blets, presque coulants, faute de quoi l'astringence gâte la liqueur ; la vanille en prolonge la note de miel. Laisser mûrir le breuvage à l'abri pour qu'il gagne en velouté.","d":"« Kaki cueilli dur perd son fiel, blet et fondant il se fait miel. »"},"lq-liqueur-de-laitue":{"h":"La laitue, modeste salade du potager, fut autrefois plus médecine que mets : son suc laiteux, qui sourd des tiges montées en graine, lui valut une réputation de plante du repos. Les Anciens la disaient consacrée aux nuits paisibles, et les jardins monastiques en cultivaient pour assoupir les esprits agités. Associée ici à la chicorée amère, elle compose une liqueur singulière, héritière des élixirs apaisants d'autrefois.","p":"La laitue, surtout montée, était réputée calmante et propre à favoriser le sommeil ; son lait passait pour adoucir les ardeurs et tempérer les veilles, et l'on en usait avec mesure comme d'un doux somnifère.","c":"Choisir des laitues bien fermes, voire montées en tige pour un suc plus marqué ; la chicorée apporte l'amertume qui équilibre la fadeur de la salade. Filtrer soigneusement, la verdure laissant un trouble tenace.","d":"« Laitue au soir prise en breuvage, mène au sommeil par doux ombrage. »"},"lq-liqueur-de-laurier":{"h":"Le laurier-sauce, noble arbre de la Méditerranée, ceignait le front des poètes et des vainqueurs, et son nom même est resté dans nos lauréats et nos baccalauréats. Toujours vert, il était voué à Apollon et planté près des demeures pour la protection qu'on lui prêtait. Ses feuilles aromatiques parfument depuis l'Antiquité bouillons et marinades ; en liqueur, elles livrent un parfum balsamique et profond.","p":"Le laurier était réputé tonique et stomachique, propre à réchauffer l'estomac et à faciliter les digestions lourdes ; on n'en usait toutefois qu'à petites doses, ses feuilles étant jugées par trop vigoureuses pour qui en abusait. Garde-toi de le confondre avec le laurier-rose ou le laurier-cerise, qui sont vénéneux.","c":"N'employer que les feuilles du véritable laurier-sauce, fraîches et bien vertes, en petite quantité car leur arôme est puissant ; le miel en arrondit l'amertume herbacée. Goûter en cours de macération pour ne pas verser dans l'âcreté.","d":"« Feuille de laurier, peu mais bien choisie, parfume le verre et non l'apothicairerie. »"},"lq-liqueur-de-lait":{"h":"La liqueur de lait, parfois nommée 'crème de lait' dans les recueils domestiques d'autrefois, naît d'un mariage curieux : on fait cailler le lait avec le zeste de citron et l'alcool, puis on filtre le petit-lait clarifié, limpide comme une eau de source. Ce procédé du 'lait clarifié' (milk punch des Anglais) servait jadis à conserver longtemps une boisson laitière sans qu'elle ne tourne. Les fermes en tiraient un nectar nacré, doux et rond, qu'on offrait aux relevailles et aux convalescents.","p":"Le lait entier passait pour nourrissant et adoucissant, réputé apaiser les âpretés de l'estomac et envelopper de douceur les esprits trop vifs de l'eau-de-vie ; on le tenait pour une boisson de réconfort plus que de fête.","c":"Laisser le caillé se déposer plusieurs jours avant de filtrer lentement à travers un linge fin, sans presser, pour obtenir une liqueur claire et non trouble. Se sert très frais, à la manière d'un digestif soyeux.","d":"« Lait caillé, citron pressé, en liqueur d'or s'est transformé. »"},"lq-liqueur-de-magnolia":{"h":"Le magnolia tire son nom du botaniste montpelliérain Pierre Magnol, qui œuvra à classer les plantes par familles. Arbre venu des forêts d'Asie et d'Amérique, il fut accueilli dans les jardins d'agrément pour ses larges fleurs charnues au parfum de citron et de gingembre. Les pétales, macérés frais, livrent un arôme rare, à la fois floral et épicé, que peu de liquoristes ont su capter.","p":"L'écorce et les boutons de certains magnolias étaient employés dans les pharmacopées orientales pour dénouer les tensions et faciliter la respiration ; la fleur, plus douce, n'était guère prisée que pour son parfum. On la prendra ici en simple plaisir de bouche, sans lui prêter de vertu assurée.","c":"Cueillir les pétales bien ouverts et immaculés, au matin, et les employer sur-le-champ car ils brunissent vite. Retirer la macération dès le parfum atteint, sous peine d'amertume, et servir frais en fin de repas.","d":"« Fleur de Magnol au verre offerte, parfume l'âme à peine ouverte. »"},"lq-liqueur-de-caramel":{"h":"Le caramel n'est que sucre poussé au feu jusqu'à brunir, mais ce simple sortilège de la chaleur fascine depuis que l'on sait fondre le sucre de canne et de betterave. Les confiseurs du dix-neuvième siècle en firent les caramels mous, friandises de fête foraine et de poche d'enfant. En liqueur, ces bonbons fondus dans l'alcool restituent un parfum chaud de beurre brûlé et de sucre roux.","p":"On ne prêtait au caramel nulle vertu de remède, sinon celle, bien profane, de consoler et de réchauffer le cœur par sa seule douceur ; c'était la gourmandise faite liqueur, à boire avec mesure.","c":"Choisir des caramels au lait nature, sans arôme artificiel, et les laisser fondre à feu très doux pour qu'ils ne se figent pas. Servir tiède sur une glace à la vanille, ou frais en toute petite quantité tant la liqueur est riche.","d":"« Sucre au feu qui se fait brun, vaut au verre tous les festins. »"},"lq-liqueur-de-mandarine":{"h":"La mandarine doit son nom aux mandarins de Chine, hauts dignitaires dont la robe de soie avait, dit-on, la teinte de ce fruit d'hiver. Venue tardivement vers les rivages de la Méditerranée, elle s'y acclimata si bien qu'elle devint le fruit des étrennes et des Noëls. Son zeste, gorgé d'huiles parfumées, donne une liqueur ambrée d'un fruité plus tendre et plus suave que l'orange.","p":"Comme tous les agrumes, la mandarine était réputée rafraîchissante et propre à réveiller l'appétit ; son écorce parfumée passait pour aider la digestion des repas de fête. On la tenait pour une douceur tonique des froidures hivernales.","c":"N'employer que des fruits non traités, et ne prélever que la fine pellicule orangée du zeste, sans le blanc amer qui dessous se cache. Une longue macération arrondit le fruité ; servir frais après un repas copieux.","d":"« Mandarine au cœur de l'hiver, met du soleil au fond du verre. »"},"lq-liqueur-de-manzana":{"h":"Manzana n'est autre que le mot espagnol pour la pomme, fruit que l'on dit le plus ancien de nos vergers, chanté des jardins d'Hespérides jusqu'aux pommeraies de Normandie. Cette liqueur courte, faite de jus de pommes et d'eau-de-vie à peine sucrée, imite les apéritifs verts d'Ibérie. Rapide à préparer, elle garde toute la fraîcheur croquante du fruit.","p":"La pomme avait réputation d'assainir l'haleine et de réjouir l'estomac ; le vieux dicton qui la donne pour éloigner le médecin témoigne de la confiance qu'on lui portait. On la tenait pour fruit sain entre tous, aimable au corps comme à l'esprit.","c":"Préférer un jus de pommes pur et trouble, non pasteurisé si possible, pour garder le goût du fruit pressé. La macération étant brève, surveiller le sucre afin que la liqueur reste vive ; se boit fraîche, voire glacée.","d":"« Pomme au pressoir, pomme au flacon, garde au logis sa guérison. »"},"lq-liqueur-de-melisse":{"h":"La mélisse, dont le nom grec évoque l'abeille car ses fleurs attirent l'essaim, fut surnommée 'citronnelle' pour son feuillage froissé qui sent le citron. Les religieux carmes en firent jadis leur fameuse eau, mêlée d'écorces et d'épices, panacée des défaillances. Macérée avec zestes, girofle et macis, elle livre une liqueur verte et balsamique, héritière de ces eaux de mélisse d'autrefois.","p":"La mélisse était réputée souveraine contre les vapeurs, les palpitations et la mélancolie, calmant les nerfs agités et réjouissant le cœur ; on la disait amie des esprits troublés. Ses vertus apaisantes lui valurent une place de choix dans les armoires des apothicaires.","c":"Cueillir les feuilles avant la pleine floraison, lorsque leur parfum citronné est à son comble, et les employer bien fraîches. Ne pas trop prolonger la macération des zestes, qui tournent vite à l'amer ; se déguste frais, à la fin du repas.","d":"« Mélisse au soir calme l'humeur, et rend au dormeur sa douceur. »"},"lq-liqueur-de-melon":{"h":"Le melon, venu d'Orient par les routes anciennes, conquit les potagers d'Italie puis ceux du Comtat où les papes d'Avignon, dit-on, en raffolaient. Fruit d'été par excellence, sucré et musqué, il se prête mal à la conserve mais offre en liqueur un parfum surprenant, miellé et fleuri. Sa chair fondante, macérée dans l'alcool, en restitue toute la rondeur estivale.","p":"On tenait le melon pour rafraîchissant et propre à désaltérer les fièvres de l'été, mais les anciens médecins le disaient de digestion délicate, recommandant de le prendre avec mesure et jamais l'estomac vide. En liqueur, sa douceur prudente passe pour amie de l'arrière-bouche.","c":"Choisir un melon parfaitement mûr, lourd et parfumé au pédoncule, dont la chair embaume déjà. Retirer soigneusement les graines et le filandreux du cœur ; servir la liqueur bien fraîche, en apéritif d'été.","d":"« Melon cueilli au plein soleil, met dans le verre un goût de miel. »"},"lq-liqueur-de-menthe-1":{"h":"La menthe poivrée, fille tardive d'un croisement entre menthe aquatique et menthe verte, fut remarquée dans les jardins d'Angleterre pour son ardeur fraîche, plus mordante que ses sœurs. Son nom rappelle la nymphe Minthé, que la légende des Grecs changea en herbe odorante. En liqueur, ses cinquante branches infusées donnent un vert profond et un souffle glacé qui rafraîchit le palais.","p":"La menthe était réputée stimuler la digestion, dissiper les nausées et clarifier l'esprit par sa vivacité même ; on en frottait les tables des festins pour aiguiser l'appétit. On la tenait pour la plus tonique des herbes de bouche.","c":"Employer un beau bouquet de menthe poivrée bien fraîche et la retirer dès que l'infusion a pris sa couleur, sans laisser les feuilles noircir. Un zeste de citron en relève l'éclat ; se sert très frais, presque glacé.","d":"« Menthe au verre, esprit léger, chasse l'ennui du dernier dé. »"},"lq-liqueur-de-menthe-2":{"h":"Voici la menthe prise dans sa forme la plus prompte, où les feuilles fraîches s'unissent à un sirop de menthe pour redoubler la couleur et le parfum. Cette manière rapide rappelle les pippermints de comptoir, ces liqueurs d'un vert éclatant qu'on servait glacées dans les cafés d'autrefois. C'est la menthe sans patience, vive et franche, faite pour les soirs pressés.","p":"La menthe poivrée passait pour rafraîchir l'haleine et soulager les lourdeurs après les repas trop riches ; sa fraîcheur même la rendait amie des estomacs paresseux. On la prenait volontiers comme un coup de fouet aromatique.","c":"Doser le sirop de menthe avec retenue pour ne pas masquer la feuille fraîche sous le sucre. La macération étant courte, goûter souvent ; se déguste très frais, allongé d'eau glacée pour un breuvage d'été.","d":"« Vert flacon vite rempli, désaltère sans long répit. »"},"lq-liqueur-de-menthe-3":{"h":"Cette troisième menthe se distingue par l'usage des fleurs autant que des feuilles, cueillies à la pleine saison quand l'épi mauve coiffe les tiges. Les anciens herbiers comptaient maintes menthes, sauvages des fossés ou cultivées des jardins, et chacune offrait sa nuance. En mêlant feuilles et fleurs, on capte un parfum plus complet, à la fois herbacé et miellé.","p":"Toutes les menthes étaient tenues pour carminatives et digestives, propres à dénouer les ballonnements et réveiller les sens engourdis ; les fleurs y ajoutaient une douceur réputée plus apaisante. On en faisait des tisanes du soir comme des liqueurs de table.","c":"Récolter les sommités fleuries par temps sec, quand le parfum est le plus dense, et les rincer à peine. Un citron éclaircit la robe et avive le goût ; filtrer avec soin car les fleurs lâchent un fin duvet.","d":"« Feuille et fleur dans le bocal, font la liqueur sans nul égal. »"},"lq-liqueur-de-millepertuis":{"h":"Le millepertuis, dont les feuilles tenues à contre-jour semblent criblées de mille trous minuscules, fut appelé 'herbe de la Saint-Jean' car on le cueillait au solstice d'été. Réputé chasser les humeurs sombres, on le suspendait jadis aux portes pour écarter le mauvais œil. Ses fleurs jaunes, macérées, teintent l'alcool d'un beau rouge sang qui surprend toujours.","p":"Le millepertuis était réputé réjouir l'âme abattue et adoucir les chagrins, d'où son vieux surnom de 'chasse-diable' ; on en faisait une huile pour les plaies. On notera toutefois qu'il rend la peau sensible au soleil et qu'il contrarie certains remèdes, raison de le prendre avec discernement et modération.","c":"Cueillir les fleurs en plein épanouissement, autour de la Saint-Jean, par temps ensoleillé. Les citrons équilibrent l'amertume herbacée ; laisser reposer plusieurs semaines pour que la teinte rubis se développe pleinement.","d":"« Fleur de la Saint-Jean au flacon, met du rubis et de l'an bon. »"},"lq-liqueur-de-mirabelles-au-rhum":{"h":"La mirabelle, petite prune dorée et sucrée, est la fierté des vergers de Lorraine où elle mûrit en grappes à la fin de l'été. Son nom, peut-être issu de l'italien pour 'belle à voir', convient à ces billes d'or piquetées de roux. Mariée ici au rhum plutôt qu'à l'eau-de-vie, elle prend un accent voyageur, plus rond et caramélisé.","p":"La prune en général était tenue pour rafraîchissante et légèrement laxative, amie des digestions difficiles ; la mirabelle, plus sucrée, passait surtout pour un régal fortifiant. On la prisait comme douceur de fin de saison.","c":"Choisir des mirabelles bien mûres, presque tombantes, dont le parfum embaume ; on peut en laisser quelques noyaux pour un soupçon d'amande, sans excès. Une longue macération au rhum fond les saveurs ; se sert frais.","d":"« Mirabelle au rhum mariée, vaut deux étés dans la veillée. »"},"lq-liqueur-de-mure":{"h":"La mûre des ronces, fruit noir et libre des haies et des chemins, n'a jamais demandé de jardinier : elle s'offre à qui veut braver les épines de septembre. Les anciens y voyaient le fruit du pauvre, gratuit et abondant, dont on tachait ses doigts en cheminant. Macérée, elle donne une liqueur d'un pourpre profond, âpre et fruitée à la fois.","p":"La mûre et les feuilles de ronce étaient réputées astringentes, employées en gargarismes contre les maux de gorge et les gencives enflammées ; le fruit passait pour rafraîchir le sang. On la tenait pour saine autant que savoureuse.","c":"Cueillir les mûres bien noires et molles, gorgées de jus, en évitant les rouges encore acides. Filtrer avec soin pour retenir les nombreux pépins ; laisser vieillir quelques mois pour que l'âpreté s'arrondisse.","d":"« Mûre des ronces au doigt cueillie, paie d'un nectar son épine hardie. »"},"lq-liqueur-de-myrte":{"h":"Le myrte, arbuste sacré de la Méditerranée, était dédié à Vénus et tressé en couronnes pour les noces et les vainqueurs. Ses baies bleu-noir et ses feuilles luisantes embaument la garrigue de Corse et de Sardaigne, où l'on en tire depuis longtemps une liqueur ambrée fameuse. Toute la plante, baies et rameaux, parfume ici l'eau-de-vie d'un arôme résineux et balsamique.","p":"Le myrte était réputé tonique et balsamique, ami des voies respiratoires et de la digestion ; les anciens lui prêtaient aussi le pouvoir d'aviver l'amour, en mémoire de la déesse qu'il honorait. On le tenait pour une plante de bien-être autant que d'agrément.","c":"Récolter les baies bien mûres à l'entrée de l'hiver et les rameaux feuillés en parallèle, pour équilibrer le fruité et le résineux. Ne pas trop prolonger la macération des feuilles, plus âpres ; servir frais en digestif.","d":"« Myrte de Vénus au flacon clos, garde l'amour et le repos. »"},"lq-liqueur-de-myrtille":{"h":"La myrtille, petite airelle des sous-bois et des landes de montagne, fut longtemps glanée par les bergers des Vosges et du Massif central avec un peigne de bois nommé « ramasse-myrtilles ». Son nom dérive du latin 'myrtillus', diminutif de la myrte dont les anciens lui trouvaient l'air. On en teignait les laines et l'on barbouillait volontiers les langues des enfants chapardeurs, trahis par leur bleu indélébile.","p":"La baie était réputée resserrer le ventre et fortifier la vue des veilleurs et des archers ; on la disait amie des yeux fatigués et du sang paresseux.","c":"Choisir des baies bien noires et mates, cueillies par temps sec ; un seul bâtonnet de cannelle suffit, sous peine d'étouffer le parfum sauvage du fruit. Servir frais après un long repos à l'abri de la lumière.","d":"« Qui suit la myrtille au flanc du mont, en rapporte les doigts plus bleus que le front. »"},"lq-liqueur-de-nefles":{"h":"La nèfle, ce fruit aigre qu'il faut laisser blettir avant d'oser y mordre, ornait les vergers d'autrefois et l'on disait d'une chose tardive qu'elle venait « à la Saint-Glinglin, comme nèfle ». Le néflier, arbuste noueux, donnait au jardinier patient une chair fondante seulement passé les premières gelées. Ses noyaux, parfumés à l'amande, servaient jadis à corser eaux-de-vie et ratafias.","p":"La pulpe blette était tenue pour adoucir les entrailles et calmer les flux du ventre. Mais l'amande contenue dans le noyau renferme un principe amer apparenté à celui des noyaux d'abricot : on n'en use qu'avec parcimonie, car à forte dose il devient redoutable.","c":"Concasser les noyaux sans excès et limiter strictement leur nombre afin de parfumer sans nuire ; une longue macération douce vaut mieux qu'une charge trop généreuse. Filtrer avec soin avant de mettre en flacon.","d":"« Nèfle hâtive est nèfle amère ; qui sait attendre boit son nectar. »"},"lq-liqueur-de-noisette-au-whisky":{"h":"La noisette, fruit du coudrier, est l'une des plus vieilles compagnes de l'homme des forêts d'Europe, dont les coquilles jonchent les foyers préhistoriques. La baguette de coudrier, aux mains du sourcier, passait pour déceler les sources cachées et les trésors enfouis. Cueillie verte au cœur de l'été, la noisette livre alors un lait délicat que le whisky d'outre-Manche revêt d'un manteau ambré et fumé.","p":"L'amande était réputée nourrissante et propre à redonner des forces aux convalescents et aux marcheurs épuisés ; le miel d'acacia ajouté la rendait baume autant que régal.","c":"Cueillir les noisettes encore vertes en juillet, alors que la coque demeure tendre, et les concasser pour libérer leur huile parfumée. Laisser reposer de longs mois en lieu sombre avant de filtrer et de goûter.","d":"« Noisette en lait, whisky en or, font au coudrier doux réconfort. »"},"lq-liqueur-de-noix":{"h":"La noix verte cueillie autour de la Saint-Jean, quand le brou est encore tendre et que la coque ne s'est pas durcie, est la matière reine des vins et liqueurs de nos campagnes. Le noyer, arbre majestueux mais réputé porter ombre néfaste à qui dort sous lui, donnait au paysan de quoi teindre, soigner et réjouir. Sa cueillette de juin était affaire de patience et de tabliers tachés de noir indélébile.","p":"Le brou amer passait pour tonifier l'estomac, réveiller l'appétit et purifier le sang aux changements de saison ; on en faisait volontiers un cordial de fin de repas.","c":"Trancher les noix encore laiteuses, dont le couteau traverse aisément le cœur, avant que la coque ne se forme. Le sucre candi et les épices arrondissent l'amertume ; un long repos brunit et assouplit la liqueur.","d":"« Noix de la Saint-Jean, noire à la main, fait l'amer du soir et le baume du lendemain. »"},"lq-liqueur-de-noyaux-d-abricots":{"h":"Les noyaux d'abricot, qu'on aurait jetés, recelaient pour les anciens un trésor parfumé : leur amande au goût d'amande amère, dont on tirait le « persicot » et autres ratafias de noyaux fort prisés aux tables d'autrefois. Casser les noyaux après la confiture était un rite d'arrière-saison, fait à la pierre ou au marteau sur le seuil. Le parfum qui en montait évoquait à la fois la frangipane et la cerise.","p":"On prêtait à ces amandes une vertu digestive et apéritive. Mais elles renferment de l'amygdaline, qui libère un poison violent : il convient d'en user à très petite dose et de ne jamais en abuser, car le remède agréable y côtoie le venin.","c":"Ne mettre qu'une poignée mesurée de noyaux concassés, jamais davantage, et préférer un long séjour à une infusion trop chargée. La cannelle et le girofle masquent l'âpreté sans la trahir.","d":"« Du noyau le parfum est doux, mais trop d'amande mène à bout. »"},"lq-liqueur-de-noyaux-d-abricots-aux-epices":{"h":"Cette liqueur de noyaux relevée d'épices de chambre prolonge un usage médiéval où le parfum d'amande amère se mariait au safran, à la cannelle et au macis pour parer la boisson de couleurs et d'arômes de cour. Le safran, plus précieux que l'or au poids, signait les tables fastueuses et teintait le breuvage d'un or chaud. On rapprochait volontiers ce nectar du « persicot » des apothicaires.","p":"Le mélange était tenu pour échauffer et réjouir le cœur autant que pour aider la digestion des repas lourds. Toutefois l'amande des noyaux recèle un principe vénéneux apparenté au cyanure : la mesure s'impose, et l'on n'en charge jamais la macération à l'excès.","c":"Doser le safran avec retenue, quelques filaments suffisant à colorer et parfumer toute la bouteille. Concasser peu de noyaux, laisser longuement reposer, puis filtrer deux fois pour obtenir une robe limpide.","d":"« Safran pour l'or, noyau pour l'âme, mais garde mesure à ta flamme. »"},"lq-liqueur-de-noyaux-de-peches":{"h":"Le noyau de pêche, cousin de celui de l'abricot, fournissait jadis aux ménagères une amande parfumée dont elles relevaient crèmes, ratafias et vins de noyau. La pêche, venue de Perse par les routes anciennes, en garde le nom dans son ancienne appellation de 'pomme de Perse'. On gardait précieusement les noyaux de l'été pour les casser à la veillée d'automne.","p":"L'amande était réputée stomachique et propre à parfumer les digestifs de fête. Comme celle de l'abricot, elle contient pourtant un principe amer toxique : on n'en met qu'une faible quantité, et jamais l'on n'en fait un usage immodéré.","c":"Choisir des noyaux de pêches bien mûres, les fendre pour en extraire l'amande, et n'en infuser qu'un nombre modeste. La vanille adoucit l'amertume ; un repos prolongé harmonise le tout avant filtration.","d":"« Amande de pêche en flacon discret : parfum de roi, poison muet. »"},"lq-liqueur-de-pissenlit":{"h":"Le pissenlit, dont les fleurs d'or constellent les prés au premier soleil, doit son nom rustique à sa réputation de faire « pisser au lit », tant on lui prêtait de vertus sur les eaux du corps. On l'appelait aussi « dent-de-lion » pour ses feuilles découpées. Sa fleur, cueillie en plein avril, donnait la « cramaillotte » jurassienne et bien des ratafias printaniers.","p":"La plante entière était tenue pour dépurative, amie du foie et des reins, et bonne à dégager le sang des langueurs de l'hiver. On la buvait comme tonique de saison.","c":"Cueillir les fleurs bien ouvertes par une matinée ensoleillée et n'en garder que les pétales jaunes, le vert apportant une amertume tenace. L'orange amère soutient le parfum ; filtrer finement les pétales avant la mise en flacon.","d":"« Fleur d'or des prés au mois d'avril, rend le sang clair et l'humeur subtil. »"},"lq-liqueur-de-poire":{"h":"La poire William, douce et musquée, est l'héritière des poiriers que les anciens grevaient déjà de mille variétés dans leurs vergers clos. On l'enfermait parfois, jeune, dans la bouteille au verger même, pour qu'elle y grossisse autour du goulot, prodige qui émerveillait les convives. Sa chair fondante en fait depuis toujours la reine des eaux-de-vie de fruit.","p":"La poire mûre passait pour rafraîchir et adoucir les tempéraments échauffés, et l'on en faisait un fruit de douceur recommandé aux estomacs délicats.","c":"Choisir une poire à parfaite maturité, parfumée et fondante au toucher, car une poire ferme rend une liqueur sans âme. La trancher au dernier moment pour éviter qu'elle brunisse, et la servir bien fraîche.","d":"« Poire trop dure ne vaut le flacon ; mûre à point, elle chante au menton. »"},"lq-liqueur-de-primeveres":{"h":"La primevère, première à fleurir quand l'hiver desserre son étreinte, annonçait le renouveau et fut nommée pour cela 'prime vère', soit le premier printemps. Mêlée ici à la violette et à la fleur d'acacia, elle compose un bouquet de liqueur tout en fraîcheur florale. On la nommait aussi « coucou » dans les campagnes, car elle paraissait avec le chant de l'oiseau.","p":"La fleur était réputée apaiser les nerfs, adoucir la toux et favoriser un sommeil tranquille ; on la cueillait comme remède doux des premiers beaux jours.","c":"Récolter les corolles par temps sec, juste écloses, et les mettre à macérer le jour même pour qu'elles ne se fanent point. Mêler les trois fleurs en parts mesurées et filtrer délicatement pour garder leur teinte tendre.","d":"« Trois fleurs d'avril au même flacon, font au buveur tout doux frisson. »"},"lq-liqueur-de-prunelles":{"h":"La prunelle, petit fruit noir et âpre de l'épine noire qui borde nos haies, ne se laisse approcher qu'après les premières gelées qui domptent son astringence. Le buisson épineux, le 'prunellier', servait de clôture vive et donnait aussi le bois des cannes et des fléaux. On en tirait jadis l'épine-vinette des campagnes et de robustes ratafias d'arrière-saison.","p":"Le fruit était tenu pour resserrer le ventre et fortifier les gencives ; son âpreté même passait pour assainir la bouche et tonifier les chairs molles.","c":"Cueillir les prunelles après les premières gelées, ou les passer au froid, pour briser leur amertume rêche. Une pointe de cannelle et un long repos dans le vin et l'alcool arrondissent leur caractère sauvage.","d":"« Prunelle avant gel n'est que tourment ; gelée venue, elle adoucit son sang. »"},"lq-liqueur-de-prunes":{"h":"La prune, fruit aimable des vergers de tout le pays, donna ses lettres de noblesse aux conserves de l'été et aux eaux-de-vie de nos provinces. Rapportée, dit-on, des croisades, elle aurait laissé l'expression « pour des prunes », souvenir d'expéditions revenues les mains presque vides. Sa chair sucrée, mariée au vin blanc et à la cannelle, compose une liqueur de table généreuse.","p":"La prune était réputée rafraîchir les sangs et délier doucement le ventre paresseux ; on la disait amie des digestions difficiles.","c":"Choisir des prunes bien mûres et parfumées, quetsches ou reines-claudes selon le goût, et les fendre pour libérer leur jus. Le vin blanc sec apporte de la fraîcheur ; laisser reposer plusieurs semaines avant de filtrer.","d":"« Prune mûre au fond du flacon vaut mieux que mille au gré du vent. »"},"lq-liqueur-de-raisin":{"h":"Le raisin, fruit de la treille et père du vin, est de toutes les cultures la plus chargée de symboles, des vendanges antiques aux celliers de nos aïeux. Choisi blanc et bien sucré, il livre ici un nectar plus suave que le vin lui-même, relevé de cannelle et de girofle à la mode des hypocras. La vigne, taillée et choyée depuis des siècles, demeure la compagne fidèle des tables de fête.","p":"Le raisin mûr était tenu pour redonner des forces et réjouir le cœur ; on prescrivait jadis des « cures de raisin » à l'automne pour rétablir les corps affaiblis.","c":"Choisir des grains blancs gorgés de sucre, à parfaite maturité, et les fouler légèrement pour qu'ils rendent leur jus. Doser cannelle et girofle d'une main retenue ; un repos prolongé fond les épices dans le fruit.","d":"« Raisin doré en doux flacon, fait de septembre un long chanson. »"},"lq-liqueur-de-reglisse":{"h":"La réglisse, ou « bois doux », tire sa saveur de la racine d'une légumineuse cultivée depuis l'Antiquité du bassin méditerranéen aux confins de l'Asie. On en mâchait les bâtons noirs pour le seul plaisir du sucre boisé, et les enfants en quêtaient chez l'apothicaire comme une friandise. Mariée à la menthe fraîche, elle compose un digestif d'un noir profond et d'une douceur réglissée.","p":"La racine était réputée adoucir la gorge, calmer la toux et apaiser les aigreurs de l'estomac. On la consomme cependant avec mesure, car un usage soutenu et abondant peut échauffer le sang et troubler les humeurs du corps.","c":"Briser les bâtons de réglisse pour qu'ils libèrent mieux leur suc lors de la macération, et n'ajouter la menthe qu'en bouquet discret afin qu'elle accompagne sans dominer. Servir à température de cave, en fin de repas.","d":"« Bois doux au verre, menthe à la dent, font le soir noir et le ventre content. »"},"lq-liqueur-de-rhubarbe":{"h":"La rhubarbe nous vient des confins de la Chine et du Tibet, où sa racine voyagea longtemps par la route de la soie avant que ses tiges acidulées ne gagnent les potagers d'Europe. Son nom porte la trace du Rha, ancien appellatif de la Volga le long de laquelle on en faisait commerce. Plante de la patience, elle ne livre ses pétioles charnus qu'au sortir du printemps, lorsque la sève monte et que la couleur tourne au corail.","p":"La racine de rhubarbe était jadis prisée des apothicaires pour ses vertus dépuratives et son action sur les humeurs paresseuses ; la tige, plus douce, passait pour rafraîchir et aiguiser l'appétit. On se gardait toutefois des feuilles, tenues pour âcres et malsaines, que l'on ne mettait jamais au bocal.","c":"Choisir des tiges bien fermes, d'un beau rose soutenu, en écartant toujours le limbe des feuilles. Une pointe de cardamome écrasée au mortier réveille l'acidité du fruit ; servir frais, après quelques semaines de repos à l'ombre.","d":"« Rhubarbe au verre, gaillard à terre. »"},"lq-liqueur-de-rhum-au-cafe":{"h":"Le café, né des hauts plateaux d'Éthiopie où l'on dit que les chèvres en révélèrent l'ardeur, conquit d'abord les cités d'Arabie avant d'enflammer les salons d'Occident. Son mariage avec le rhum des îles raconte le grand négoce des Antilles, où la canne et le grain noir voyageaient sous les mêmes voiles. De cette rencontre naît une liqueur sombre et veloutée, digne des fins de soirée.","p":"Le café était réputé chasser le sommeil et ranimer les esprits engourdis ; on lui prêtait la vertu de réveiller l'entendement et de soutenir la veille studieuse. Marié au rhum, il composait un cordial qu'on disait propre à dénouer les digestions lourdes des grands repas.","c":"Préférer des grains fraîchement torréfiés et concassés à gros grain plutôt que moulus fin, pour éviter l'amertume et le trouble. Filtrer avec soin au linge serré, et laisser la vanille fondre ses arômes durant tout le repos.","d":"« Café dans le rhum, l'esprit reprend son aplomb. »"},"lq-liqueur-de-romarin":{"h":"Le romarin, « rosée de mer » selon son nom latin, parfume les garrigues des rivages méditerranéens depuis la plus haute Antiquité. On en tressait des couronnes pour les noces comme pour les funérailles, en gage de fidélité et de souvenir, et l'on brûlait ses rameaux pour assainir l'air des chambres. Sa fleur bleue, butinée des abeilles, donnait un miel renommé entre tous.","p":"On tenait le romarin pour un puissant tonique, capable de fortifier la mémoire et de raffermir le cœur défaillant ; il entrait jadis dans la fameuse Eau de la Reine de Hongrie, vantée pour rendre vigueur aux membres las. On le disait aussi ami de la digestion après les viandes grasses.","c":"Cueillir les fleurs par temps sec, en pleine floraison, à l'écart des chemins poussiéreux. Une infusion brève suffit, car une macération trop longue tire un goût camphré ; servir en petit verre, à température de cave.","d":"« Brin de romarin au flacon, garde l'esprit et le menton. »"},"lq-liqueur-de-roses":{"h":"La rose, reine des jardins, fut cultivée des Perses aux Romains autant pour son parfum que pour ses pétales, dont on tirait eaux et confitures dans tout l'Orient. Au Moyen Âge, les roseraies des cloîtres fournissaient la rose de Provins, dite officinale, que l'on séchait pour la conserver tout l'an. Sa distillation en eau de rose embaumait les tables princières et les onguents des dames.","p":"L'eau et le sirop de rose étaient réputés adoucir les humeurs échauffées, réjouir le cœur et resserrer doucement les chairs. On leur prêtait une vertu cordiale et apaisante, propre à calmer les vapeurs et à parfumer l'haleine.","c":"N'employer que des roses non traitées et odorantes, en ôtant le talon blanc et amer à la base de chaque pétale. Macérer brièvement pour préserver la couleur et le parfum, puis servir bien frais, en filet, sur un dessert pâle.","d":"« Rose au flacon, baume au cœur et au fronton. »"},"lq-liqueur-de-sauge":{"h":"La sauge tire son nom du latin salvia, « celle qui sauve », tant les anciens la tenaient en estime parmi les simples du jardin. On répétait jadis le dicton de l'École de Salerne demandant comment l'homme pourrait mourir quand pousse la sauge en son courtil. Ses feuilles veloutées et grises parfumaient les viandes, les tisanes et les vins des convalescents.","p":"La sauge était réputée souveraine pour réconforter l'estomac, raffermir les gencives et soutenir les forces déclinantes ; on la disait amie de la longévité. On la maniait toutefois avec mesure, car prise sans retenue elle échauffe et trouble plus qu'elle n'apaise.","c":"Cueillir des feuilles jeunes et saines avant la floraison, et n'en mettre qu'une poignée mesurée pour éviter l'amertume. Le girofle et le zeste de citron tempèrent son caractère ; laisser reposer à l'abri du jour.","d":"« Sauge au logis, le mire au repos. »"},"lq-liqueur-de-sommeil-xvie-siecle":{"h":"Cette liqueur du sommeil rassemble les plantes que les herboristes d'autrefois nommaient amies de la nuit, et dont les vertus se transmettaient de cahier en cahier. La valériane, dont la racine attire singulièrement les chats, parfumait les jardins de simples des couvents ; l'aubépine, fleur de mai, et la passiflore, plus tard venue des Amériques, complètent ce bouquet du repos avec la mélisse douce.","p":"On disait ces plantes propres à dénouer les tensions de l'esprit et à inviter au sommeil les veilleurs agités ; la valériane surtout passait pour calmer les humeurs trop vives. Cordial du soir, il se prenait en très petite mesure, car on le voulait apaisant et non assoupissant à l'excès.","c":"Doser chaque plante à parts égales et en quantité modeste, le safran n'étant ajouté qu'en pincée pour la couleur et le parfum. Servir un dé à coudre au coucher, jamais davantage ; le miel et la vanille en adoucissent l'amertume herbeuse.","d":"« Goutte du soir, nuit sans déboire. »"},"lq-liqueur-de-baies-de-sureau":{"h":"Le sureau noir, arbre des haies et des lisières, accompagne les demeures rurales depuis des temps immémoriaux, au point qu'on le disait habité d'un esprit protecteur qu'il fallait saluer avant d'en couper le bois. Ses ombelles de fleurs blanches parfument le printemps, et ses grappes de baies noires mûrissent à l'arrière-saison. On en faisait vins, sirops et gelées dans toutes les campagnes.","p":"Les baies mûres de sureau étaient réputées sudorifiques et bienfaisantes pour affronter les frimas et les refroidissements. Mais on ne les employait jamais crues ni vertes, car la baie non mûre et les autres parties de l'arbre renferment des principes âcres et nuisibles ; il faut les vouloir bien noires et parfaitement mûres.","c":"Ne récolter que les grappes d'un noir profond, en écartant soigneusement les baies rouges ou tournantes, et les égrapper à la fourchette. Une cuisson ou une macération prolongée assagit le fruit ; la vanille en arrondit la sauvagerie.","d":"« Baie noire bénit, baie verte trahit. »"},"lq-liqueur-de-the":{"h":"Le thé, présent immémorial de la Chine au monde, fut d'abord boisson de lettrés et de moines avant de gagner par les caravanes et les clippers les tasses de toute la chrétienté. Le thé noir, plus oxydé et corsé, voyageait mieux que le vert et devint le compagnon des après-midi d'Occident. Sa feuille roulée libère, à l'eau bouillante, tanins et arômes ambrés.","p":"Le thé était réputé éclaircir l'esprit, dissiper la somnolence et soutenir l'attention durant les longues veilles. On lui prêtait aussi de favoriser la digestion et de tempérer les excès de table par sa légère astringence.","c":"Choisir un thé noir de belle feuille et l'infuser brièvement à l'eau bouillante pour éviter l'amertume des tanins surchauffés. Une écorce de cannelle accompagne sa rondeur ; filtrer au linge fin avant la mise en flacon.","d":"« Thé au verre, veille sans misère. »"},"lq-liqueur-de-the-aux-epices":{"h":"Le mariage du thé et des épices rejoue les routes anciennes où la feuille de Chine croisait le gingembre, la cardamome et le girofle des îles lointaines. Dans les contrées de l'Inde, on parfumait depuis longtemps les infusions de racines et de graines pour les rendre réconfortantes. Ce breuvage épicé porte la mémoire des comptoirs où s'échangeaient ces trésors odorants.","p":"Les épices chaudes, gingembre et cardamome en tête, étaient réputées réchauffer le ventre et activer une digestion paresseuse, tandis que le girofle passait pour assainir l'haleine. Unies au thé tonique, elles composaient un cordial des soirées d'hiver.","c":"Concasser légèrement les graines de cardamome et le girofle pour en libérer le parfum, sans surcharger la main. Infuser le thé à part et l'unir froid aux épices macérées ; un repos de quelques semaines fond les arômes.","d":"« Thé sans épice est habit sans malice. »"},"lq-liqueur-de-thym":{"h":"Le thym, modeste sous-arbrisseau des coteaux secs, embaumait déjà les rites des anciens, qui en brûlaient pour purifier les temples et en glissaient dans les couches pour éloigner les bêtes. Son nom évoque le courage, et l'on disait jadis qu'une senteur de thym rendait l'âme vaillante. La cueillette de ses fleurs mauves, l'été, à l'heure chaude, charge la plante de tout son arôme.","p":"Le thym était réputé pectoral et fortifiant, ami des poitrines encombrées et des digestions lentes ; on le tenait aussi pour assainir et réconforter. Son alliance au miel passait pour adoucir la gorge et soutenir le souffle.","c":"Ramasser les sommités fleuries l'été, par temps sec, loin des bords de route. Le miel remplace ici le sucre et lie l'amertume herbeuse ; laisser reposer à l'abri, puis filtrer fin avant de mettre en bouteille.","d":"« Thym dans le miel, courage du ciel. »"},"lq-liqueur-de-tilleul":{"h":"Le tilleul, grand arbre des places de village et des allées seigneuriales, abritait jadis les assemblées et les danses sous son ombre généreuse. Sa floraison de juin, légère et mellifère, embaume les soirs d'été et attire un peuple d'abeilles. On en récoltait les fleurs pour la tisane du soir, breuvage familier de toutes les maisons.","p":"La fleur de tilleul était réputée calmante et adoucissante, amie des nerfs agités et des sommeils difficiles ; on la disait propre à apaiser les tensions et à favoriser la sueur lors des refroidissements. Cordial doux, il convenait aux fins de journée.","c":"Cueillir les fleurs juste écloses, avec leur bractée, par temps sec et avant la pluie qui en ternit le parfum. Une macération courte préserve leur finesse ; servir frais, en petite quantité, au terme du repas.","d":"« Fleur de tilleul au soir, berce sans le vouloir. »"},"lq-liqueur-de-tournesol":{"h":"Le tournesol, venu des grandes plaines d'Amérique où les peuples premiers le cultivaient pour ses graines, éblouit l'Europe à la Renaissance par sa fleur d'or qui suit la course du soleil. On le nomma fleur du soleil pour cette fidélité au jour, et il devint l'emblème des champs lumineux de l'été. Ses pétales rayonnants, plus rarement employés que ses graines, donnent une teinte dorée aux préparations.","p":"On prêtait jadis au tournesol des vertus adoucissantes et l'on en tirait des onguents apaisants pour la peau ; ses graines passaient pour nourrissantes et bienfaisantes. La liqueur de ses pétales se voulait surtout réjouissante par sa couleur de soleil.","c":"Ne prélever que les pétales jaunes, en écartant le cœur granuleux qui apporte de l'amertume. Les cueillir en pleine floraison et les employer aussitôt ; la vanille soutient leur parfum discret et la macération révèle leur teinte ambrée.","d":"« Fleur qui suit le jour, met du soleil au flacon de séjour. »"},"lq-liqueur-de-vanille-au-rhum-blanc":{"h":"La vanille, gousse parfumée d'une orchidée grimpante, naquit dans les forêts du Mexique où les peuples anciens l'unissaient déjà au cacao des breuvages sacrés. Longtemps stérile hors de son berceau faute de l'insecte qui la fécondait, elle ne s'épanouit aux îles que lorsqu'on apprit à la marier à la main. Son alliance au rhum blanc des Antilles compose un duo des tropiques d'une suavité profonde.","p":"La vanille était réputée cordiale et réconfortante, propre à réjouir les sens et à fortifier doucement l'estomac ; on lui prêtait même de relever les esprits abattus. Son parfum chaud passait pour adoucir l'âpreté des alcools forts.","c":"Choisir des gousses grasses et souples, brillantes et bien noires, à fendre dans la longueur pour en gratter les graines. Le rhum blanc met sa pureté au service du parfum ; une longue macération et un peu de sirop de canne arrondissent le tout.","d":"« Vanille au rhum, douceur sans nul brouhaha. »"},"lq-liqueur-de-vanille":{"h":"La vanille, seule orchidée dont on récolte le fruit, fut le trésor parfumé que l'Ancien Monde découvrit dans le sillage des conquêtes des Amériques. Son nom espagnol évoque la petite gousse, vainilla, fine et allongée comme une cosse. Précieuse et longue à préparer, elle demeura un luxe des tables raffinées avant que sa culture ne gagne les îles de l'océan Indien.","p":"On tenait la vanille pour un aromate cordial, réjouissant le cœur et soutenant l'estomac fatigué ; certains lui prêtaient même la vertu de ranimer les langueurs et d'égayer l'humeur. Son parfum suave en faisait l'ornement des préparations de fête.","c":"Préférer des gousses charnues et odorantes, qu'on fend pour en libérer les graines minuscules. Une macération patiente extrait toute la profondeur du parfum ; servir frais, en petit verre, au terme d'un repas.","d":"« Gousse au flacon, parfum sans façon. »"},"lq-liqueur-verte-de-citronnelle":{"h":"La citronnelle, qu'on nomme aussi mélisse ou herbe au citron selon les contrées, doit son nom à l'odeur d'agrume que froissent ses feuilles. Apportée des jardins de Méditerranée et des cloîtres médiévaux, elle parfumait jadis les tisanes du soir et chassait, disait-on, les fièvres de l'été. Sa verdeur acidulée en faisait une herbe de cordial, mêlée volontiers à la menthe pour rafraîchir l'haleine.","p":"On lui prêtait des vertus calmantes et digestives, propres à dénouer l'estomac noué et à apaiser les humeurs agitées avant le repos.","c":"Cueillir les feuilles jeunes et bien vertes avant la floraison, car elles perdent ensuite de leur arôme citronné. Filtrer avec soin pour ôter le moindre brin, et servir frais en fin de repas.","d":"« Qui de citronnelle fait sa coupe, garde l'esprit clair et l'humeur souple. »"},"lq-liqueur-de-venus-xvii-siecle":{"h":"Les liqueurs dites « de Vénus » fleurissaient aux tables galantes du Grand Siècle, où l'on prêtait aux semences et aux épices chaudes le pouvoir d'échauffer le sang et d'attiser l'inclination. La graine de carotte sauvage, base de cette recette, était de longue date rangée parmi les simples réputés stimulants. Mêlée au cumin, à la cannelle et au safran, elle composait un breuvage d'apparat aux couleurs d'or.","p":"Ces semences et ces épices étaient tenues pour cordiales et échauffantes, propres à raviver les esprits et, croyait-on, à éveiller la tendresse ; on s'en gardait néanmoins à dose immodérée.","c":"Concasser légèrement les graines pour libérer leurs huiles avant la macération. Laisser reposer en lieu sombre, puis filtrer deux fois pour obtenir une liqueur limpide et dorée.","d":"« Graine et safran en la fiole dormant, réveillent au verre plus d'un cœur languissant. »"},"lq-liqueur-de-verveine":{"h":"La verveine, herbe sacrée des anciens, ornait les autels et les couronnes des messagers de paix avant les traités. Les Romains l'appelaient verbena et l'employaient aux rites de purification ; au village, on la suspendait au seuil pour écarter le mauvais sort. La verveine odorante, venue d'Amérique aux jardins d'Europe, lui ajouta plus tard son franc parfum citronné, prisé des liquoristes.","p":"Elle était réputée digestive et apaisante, bonne à calmer les nerfs et à faciliter le sommeil après les repas trop riches.","c":"Préférer les feuilles fraîches et odorantes, cueillies avant la pleine chaleur du jour. Ne pas prolonger la macération outre mesure, sous peine d'une amertume herbacée qui voilerait le citronné.","d":"« Verveine au soir cueillie, console qui sans elle s'ennuie. »"},"lq-liqueur-de-vespetro-xviii-siecle":{"h":"Le vespétro est une liqueur ancienne dont le nom plaisant trahit l'usage : on la disait propre à libérer les vents et à délier les digestions pesantes. Faite de graines aromatiques — angélique, coriandre, fenouil et anis — elle figurait parmi les ratafias de ménage que l'on tirait à la cave pour les fins de banquet. Sa réputation carminative en fit longtemps un remède de bonne femme autant qu'un plaisir de table.","p":"Les semences réunies passaient pour souverainement digestives et carminatives, dissipant les ballonnements et réchauffant l'estomac fatigué.","c":"Écraser les graines au mortier pour en exalter l'arôme, et n'ajouter les zestes de citron qu'en évitant le blanc, qui apporte l'amertume. Une longue macération arrondit les saveurs.","d":"« Vespétro après ripaille, dénoue le ventre et la canaille. »"},"lq-liqueur-de-vieux-garcon":{"h":"Le pot du vieux garçon, ou « bachelor's jam », est une tradition des campagnes où l'on enrichissait peu à peu un même bocal des fruits de chaque saison, abricots de juin, cerises de juillet, prunes d'automne. Le célibataire, faute de confitures de ménagère, y noyait sa récolte dans l'eau-de-vie et le sucre. Le bocal patientait jusqu'aux fêtes, gardant la mémoire colorée de tout un été.","p":"On y voyait un cordial réconfortant, tonique des soirs froids, où chaque fruit ajoutait sa douceur ; les noyaux laissés entiers gagnent toutefois à n'être point trop nombreux.","c":"Ajouter les fruits bien sains au fil de leur maturité, en couvrant toujours d'alcool et d'autant de sucre. Réserver les fruits confits pour accompagner desserts et glaces.","d":"« Au pot du vieux garçon point de saison perdue : tout fruit qui mûrit y trouve sa vertu. »"},"lq-liqueur-de-violettes":{"h":"La violette, fleur de modestie et de mémoire, embaumait les jardins médiévaux et les confiseries des dames. Toulouse en fit une gloire, candie au sucre ou distillée en parfum, et l'on raconte qu'elle figura parmi les fleurs favorites des cours impériales. Sa teinte mauve et son parfum fugace en firent l'une des fleurs les plus courtisées des liquoristes.","p":"On lui attribuait des vertus pectorales et adoucissantes, bonnes à calmer la toux et à apaiser les gorges irritées.","c":"Ne retenir que les violettes odorantes fraîchement écloses, à l'écart des bords de chemin. La macération doit rester brève pour préserver la couleur et le parfum, prompts à se faner.","d":"« Modeste au bois, la violette en verre fait la reine du mois. »"},"lq-liqueur-de-zestes-d-agrumes":{"h":"Les agrumes, venus d'Orient par les routes des marchands, gagnèrent les vergers d'Italie et de Provence où leurs zestes parfumés devinrent trésor de cuisine. Orange, citron, clémentine et pamplemousse offrent dans leur écorce les huiles les plus odorantes du fruit, que les liquoristes captent à l'alcool. Marier ces écorces, c'est composer un bouquet d'agrumes plus riche qu'aucun fruit pris seul.","p":"Les zestes étaient réputés toniques et apéritifs, stimulant l'appétit et réjouissant les esprits par leur fraîcheur.","c":"Choisir des fruits non traités et ne prélever que la fine peau colorée, sans le blanc amer. Bien filtrer, puis laisser reposer quelques semaines pour fondre la vivacité des écorces.","d":"« De quatre écorces une seule liqueur, c'est tout le verger en une senteur. »"},"lq-liqueur-d-eau-de-fleur-d-oranger":{"h":"La fleur d'oranger, ou fleur de bigaradier, donne par distillation l'eau parfumée qui embaumait les fontaines des palais andalous et les pâtisseries du Sud. On en aspergeait jadis les mariées et les linges, et son parfum devint emblème de pureté et de fête. L'eau de fleur d'oranger, longtemps tirée des jardins de Grasse et de Méditerranée, parfume autant les douceurs que les liqueurs.","p":"Elle passait pour calmante et antispasmodique, propre à apaiser les nerfs agités et à favoriser un sommeil paisible.","c":"User d'une eau de fleur d'oranger de qualité, au parfum franc et non chargé. Inutile de macérer longtemps : la liqueur se monte presque aussitôt et se sert bien fraîche.","d":"« Fleur d'oranger en fiole close, parfume le soir et l'âme repose. »"},"lq-liqueur-d-estragon":{"h":"L'estragon, dont le nom dérive du latin médiéval pour « petit dragon », tirerait cette appellation de sa racine sinueuse comme un serpent, ou de l'usage qu'on en fit contre les morsures venimeuses. Venu des steppes d'Asie centrale, il gagna les jardins d'Europe par les routes médiévales et s'imposa comme herbe maîtresse des fines cuisines. Son arôme anisé et poivré en fit aussi un aromate de liqueurs de ménage.","p":"On le tenait pour apéritif et digestif, stimulant de l'appétit ; riche en estragole, son essence demande une main mesurée et une consommation modérée.","c":"Cueillir l'estragon en juin ou juillet, avant que les tiges ne durcissent. Une macération courte suffit à capter son parfum sans tomber dans l'amertume herbacée.","d":"« Petit dragon en la bouteille, pique la langue et la réveille. »"},"lq-liqueur-d-eucalyptus":{"h":"L'eucalyptus, géant venu des terres australes, ne gagna les jardins et pharmacies d'Europe qu'à mesure que les voyageurs en rapportèrent feuilles et semences. On planta ses bosquets dans les contrées marécageuses, croyant son odeur balsamique capable d'assainir l'air et d'écarter les fièvres. Sa feuille mentholée et camphrée devint vite remède des bronches et parfum des préparations d'hiver.","p":"Son essence était réputée balsamique et pectorale, dégageant la respiration des refroidissements ; fort concentrée, elle se prend toujours à petite dose.","c":"N'employer que quelques feuilles, car l'eucalyptus domine vite tout assemblage. La cannelle adoucit sa fraîcheur médicinale ; servir en très petits verres après le repas.","d":"« Une feuille suffit, deux étouffent : à l'eucalyptus la mesure étoffe. »"},"lq-liqueur-d-hysope":{"h":"L'hysope, herbe sainte des Écritures dont on usait pour les aspersions purificatrices, fut une plante de cloître par excellence, cultivée au jardin des simples pour ses sommités fleuries bleues. Les moines liquoristes la comptaient parmi les herbes aromatiques de leurs élixirs réputés. Son parfum camphré et un peu amer en fait une signature des vieilles liqueurs de plantes.","p":"On la disait pectorale et digestive, bonne aux refroidissements de poitrine ; son essence renferme toutefois une cétone qui la rend nuisible à forte dose, et l'on s'en tient à de petites quantités.","c":"Cueillir les sommités fleuries fraîches, en pleine floraison, et n'en mettre qu'une poignée mesurée. Servir en liqueur de fin de repas, par petits verres seulement.","d":"« Hysope du moine, à petite mesure : trop généreuse, elle tourne à l'injure. »"},"lq-liqueur-d-or":{"h":"Les liqueurs pailletées d'or descendent du Danziger Goldwasser, élixir réputé né dans les villes marchandes de la Baltique, où l'on faisait danser de fines feuilles d'or dans un alcool d'épices. L'or, tenu pour métal noble et incorruptible, conférait au breuvage un prestige de table princière. Cannelle, muscade, girofle et cardamome composaient le bouquet chaud digne d'un cordial de fête.","p":"Ce concert d'épices passait pour cordial et tonique, réchauffant le corps et fortifiant l'estomac ; l'or, inerte, ne servait que la beauté du flacon.","c":"Doser les épices d'une main légère pour ne point étouffer les agrumes, puis filtrer avec soin avant d'ajouter les paillettes d'or. Remuer doucement avant de servir pour les faire scintiller.","d":"« L'or au fond du verre ne nourrit ni ne paie, mais réjouit l'œil qui le côtoie. »"},"lq-liqueur-d-orange-ou-cointreau-maison":{"h":"Les liqueurs d'orange descendent en droite ligne du curaçao, né du mariage entre l'eau-de-vie et les écorces d'oranges amères de l'île antillaise. Les maisons d'Angers en firent au dix-neuvième siècle un triple-sec d'une grande pureté, dont cette recette de ménage cherche l'écho. L'orange douce, plus tendre que la bigarade, donne ici une liqueur ambrée d'une franchise de fruit.","p":"L'écorce d'orange était réputée stomachique et tonique, propre à ouvrir l'appétit et à réconforter la digestion.","c":"User d'oranges non traitées et ne garder que le zeste, sans le blanc amer. Une longue macération et un repos en bouteille fondent la vivacité de l'écorce en rondeur.","d":"« Belle orange à la peau dorée, fait la liqueur la plus prisée. »"},"lq-liqueur-d-orange-au-sirop-d-erable":{"h":"Cette liqueur unit l'orange des vergers du Sud au sirop d'érable des forêts du Nord, douceur que les peuples d'Amérique tiraient de l'entaille des grands arbres bien avant l'arrivée des colons. La sève recueillie au dégel, longuement réduite, donne ce miel d'arbre à la saveur boisée. Mariée à l'écorce d'orange et aux épices chaudes, elle compose un cordial d'automne aux accents de cabane à sucre.","p":"L'orange était tenue pour tonique et l'érable pour reconstituant ; ensemble ils font une liqueur réconfortante des soirées fraîches.","c":"Choisir un sirop d'érable ambré, assez prononcé pour tenir tête aux épices. Mesurer la cannelle et le girofle pour ne point masquer le boisé de l'érable ; servir légèrement frais.","d":"« Orange du Sud, érable du Nord, en un seul verre s'accordent encore. »"},"lq-liqueur-du-pendu-a-l-orange":{"h":"Le nom pittoresque de « liqueur du pendu » désignait jadis ces breuvages où une orange tout entière, hérissée de clous de girofle, demeurait suspendue par un fil au goulot du bocal, semblant flotter dans l'eau-de-vie sans toucher le fond. L'armagnac, plus vieille eau-de-vie de Gascogne, distillée dès le bas Moyen Âge, prêtait à cette préparation son feu ambré et sa rusticité. Le fruit clouté évoquait aussi la pomme d'ambre, ou pomander, que l'on portait autrefois contre les miasmes.","p":"L'écorce d'orange amère et le girofle étaient tenus pour stomachiques et cordiaux, propres à réchauffer l'estomac après les repas de fête. On leur prêtait aussi la vertu d'assainir l'haleine et de réconforter les humeurs.","c":"Choisir une orange non traitée à peau épaisse, la suspendre sans qu'elle baigne, et veiller à ce qu'elle ne touche jamais la paroi, sous peine de moisissure. Se déguste à température de cave, dans un petit verre, à la fin du repas.","d":"« Orange au gibet de fil pendue, donne liqueur d'or, jamais perdue. »"},"lq-liqueur-du-pendu-a-la-poire":{"h":"Sur le même principe que sa cousine à l'orange, cette liqueur tirait son nom de la poire que l'on faisait croître à l'intérieur même du flacon : on engageait, au verger, le jeune fruit dans la bouteille encore vide, puis on l'y laissait mûrir à l'attache, pendu à sa branche. La poire Williams, obtenue en Angleterre au tournant du XVIIIᵉ siècle puis répandue partout, devint la reine de cet artifice de bouilleur de cru.","p":"La poire passait pour un fruit doux et rafraîchissant, favorable à la digestion et apaisant pour les voies du ventre. On disait son eau-de-vie propre à dénouer les estomacs lourds après ripaille.","c":"N'employer que des poires à parfaite maturité, fondantes et juteuses, car un fruit vert ne livre qu'une liqueur âpre. Servir frais mais non glacé, pour ne pas étouffer le bouquet floral du fruit.","d":"« Poire en bouteille close enfermée, vaut un verger en un flacon serré. »"},"lq-liqueur-noisetine":{"h":"La noisette, fruit du coudrier, accompagne l'homme depuis les âges les plus reculés, et l'on en a retrouvé des coques carbonisées dans bien des foyers préhistoriques d'Europe. Le coudrier, ou noisetier, fut longtemps tenu pour arbre de divination : c'est de son bois souple qu'on taillait la baguette du sourcier en quête de sources cachées. Sa liqueur dorée, dite « noisetine », prolonge cette familiarité ancienne en bouteille.","p":"La noisette, riche et nourrissante, était réputée fortifiante et propre à soutenir les corps affaiblis ; on la conseillait volontiers aux convalescents. Son huile servait aussi d'onguent adoucissant.","c":"Faire légèrement torréfier les noisettes avant de les concasser réveille leur parfum grillé et donne à la liqueur toute sa profondeur. Laisser bien reposer après filtration, car ce sont les liqueurs de fruits secs qui gagnent le plus à patienter.","d":"« Qui sait attendre la noisette mûre, boit la patience dans sa bouture. »"},"lq-liqueur-persicot":{"h":"Le persicot, dont le nom vient du persica latin désignant la pêche, comptait parmi les liqueurs de noyaux fort prisées sous l'Ancien Régime, où l'on tirait des amandes d'abricot et de pêche un parfum proche de la cerise et de l'amande amère. Relevé de girofle, de muscade et de safran, il figurait au rang des « ratafias d'office » que les maisons aisées préparaient elles-mêmes.","p":"Les épices qui le composent passaient pour digestives et cordiales. On se gardera toutefois de forcer la dose de noyaux : les amandes amères renferment un principe qui, libéré en quantité, devient un poison ; nos anciens, par prudence, n'en mettaient qu'avec mesure.","c":"Concasser les noyaux sans en abuser, et ne jamais prolonger outre mesure la macération, qui exalterait l'amertume. Filtrer avec soin sur étamine fine pour retenir tout débris de coque.","d":"« Du noyau prends peu, du parfum prends mieux ; trop d'amande amère fâche les cieux. »"},"lq-liqueur-prunelline":{"h":"La prunelle, petit fruit noir et âpre du prunellier qui hérisse les haies et les talus, ne devient mangeable qu'après les premières gelées, qui domptent sa rudesse. Les épines redoutables de l'arbuste, dit aussi épine noire, en faisaient une clôture vivante des champs, et le bois de la prunelline servit longtemps à tailler cannes et gourdins. Macérée à l'eau-de-vie, elle livre une liqueur d'un grenat sombre, mariée ici à l'amande et aux épices.","p":"La prunelle était tenue pour astringente et tonique, bonne contre les relâchements du ventre. Les amandes mondées qui l'accompagnent doivent rester en faible nombre, car l'amande amère recèle un principe vénéneux dont il convient de se défier.","c":"Cueillir les prunelles bien blettes, après la gelée, ou les passer un temps au congélateur pour amollir leur âpreté. Une longue patience de plusieurs mois arrondit la liqueur et fond les tanins.","d":"« Prunelle veut le gel pour s'adoucir, et le temps long pour s'épanouir. »"},"lq-pippermint-maison":{"h":"Le « peppermint », d'après l'anglais désignant la menthe poivrée, doit sa verdeur éclatante à cette menthe née d'un croisement spontané repéré en Angleterre, dont l'arôme glacé conquit les distillateurs. La menthe glaciale, plus mordante encore, pousse l'effet de fraîcheur à son comble. Cette version domestique imite, par le sirop et l'alcool, les liqueurs vertes des cafés d'autrefois.","p":"La menthe poivrée était réputée souverainement digestive et rafraîchissante, propre à dissiper les lourdeurs d'estomac et à ranimer les esprits las. On en parfumait volontiers les boissons de l'été.","c":"Préparation prompte qui ne réclame guère de macération : il suffit de marier sirop, alcool et eau, puis de laisser reposer au frais. Se sert très frappée, voire sur glace pilée, pour en goûter toute la morsure mentholée.","d":"« Menthe au verre fait l'haleine claire et le cœur léger comme l'air. »"},"lq-shrubb-a-la-clementine-et-a-l-orange":{"h":"Le shrubb, dont le nom passé de l'arabe au mot anglais désigne une boisson aux agrumes, est devenu aux Antilles la liqueur des fêtes de Noël, où l'on marie au rhum les écorces d'orange amère séchées et les épices. Le bigaradier ayant gagné les îles avec les colons, ses zestes parfument depuis lors ce breuvage créole. La clémentine, fruit né au tournant du XXᵉ siècle, y apporte une douceur plus tendre.","p":"Les zestes d'agrumes, riches en huiles parfumées, et le girofle étaient tenus pour stomachiques et propres à réveiller l'appétit. La cannelle ajoutait à la liqueur sa chaleur réputée réconfortante.","c":"Ne prélever que la partie colorée du zeste, sans le blanc amer qui gâterait la liqueur. Servir frais en fin de repas ; quelques semaines de repos fondent l'ardeur du rhum dans le sucre et les épices.","d":"« Zeste et girofle au rhum mêlés, font Noël en fiole scellée. »"},"cr-creme-d-abricots":{"h":"L'abricot, dont le nom voyagea du latin par l'arabe avant de revenir en français, est originaire d'Asie et fut acclimaté de longue date sur les terres chaudes du pourtour méditerranéen. Fruit d'or du plein été, fragile et vite mûr, il fait depuis toujours le bonheur des confituriers et des liquoristes du Midi. Sa chair fondante, mariée au vin et à la cannelle, donne une crème ambrée et veloutée.","p":"L'abricot était réputé rafraîchissant et adoucissant, favorable aux poitrines et aux humeurs échauffées. On gardera mémoire toutefois que l'amande de son noyau, amère, ne saurait s'employer qu'avec grande retenue, car elle recèle un principe nocif.","c":"Choisir des abricots bien mûrs, parfumés et veloutés, plutôt qu'un fruit hâtif et ferme. Un soupçon de cannelle suffit à napper le fruit sans le masquer ; servir bien frais.","d":"« Abricot d'or au plein soleil mûri, vaut le miel du verger réjoui. »"},"cr-creme-de-cacao":{"h":"La fève de cacao, fruit d'un arbre des forêts d'Amérique centrale, fut tenue par les anciens peuples mésoaméricains pour un présent des dieux, au point d'en faire monnaie d'échange. Rapporté en Europe par les navigateurs espagnols, le cacao y devint d'abord breuvage de cour, épaissi et épicé, avant que les liquoristes n'en tirent des crèmes onctueuses. Le botaniste qui le baptisa lui donna un nom signifiant « nourriture des dieux ».","p":"Le cacao était réputé tonique et réconfortant, propre à relever les forces et à réjouir l'esprit ; on lui prêtait même la vertu de raviver l'ardeur. Pris en abondance le soir, il pouvait toutefois tenir l'œil ouvert.","c":"N'employer qu'un cacao amer de bonne qualité, sans sucre ajouté, pour garder à la crème toute sa franchise. Le lait demande un repos au frais et une consommation assez prompte, car il ne se conserve point comme les liqueurs claires.","d":"« Cacao des dieux en crème noyé, console le cœur ensommeillé. »"},"cr-creme-de-capucines":{"h":"La capucine, venue elle aussi des terres d'Amérique, doit son nom à l'éperon de sa fleur, que l'on jugea semblable au capuchon des frères capucins. Plante de jardin facile et joyeuse, elle offre fleurs, feuilles et boutons à la table, où l'on en relève les salades d'une saveur poivrée proche du cresson. Sa fleur d'un orange ardent donne à cette crème une teinte de soleil couchant.","p":"La capucine était réputée tonique et apéritive, et l'on prêtait à ses feuilles, riches d'une saveur piquante, des vertus fortifiantes. On la tenait aussi pour bonne aux voies respiratoires.","c":"Cueillir fleurs et feuilles au matin, sèches de rosée et bien épanouies, à l'écart des chemins poussiéreux. La macération étant brève, mieux vaut goûter souvent pour saisir l'instant où le parfum poivré est à son comble.","d":"« Fleur de capucine au jardin cueillie, met du soleil dans la bouteille emplie. »"},"cr-creme-de-cafe":{"h":"Le café, dont le grain est la graine d'un arbuste originaire des hauts plateaux d'Éthiopie, gagna le monde par la péninsule Arabique, d'où son nom voyagea de langue en langue. Les cafés de ville, lieux de conversation et d'esprit, en répandirent l'usage à travers l'Europe à partir du XVIIᵉ siècle. Sa liqueur sombre et parfumée prolonge en douceur le plaisir de la tasse.","p":"Le café était tenu pour stimulant et propre à dissiper les torpeurs, à éclaircir l'esprit et à soutenir les veilles. On le disait aussi favorable à la digestion, pris après les repas.","c":"Employer un café fraîchement moulu et de franc arôme, car un grain éventé ne livre qu'une liqueur plate. Filtrer avec soin sur papier ou linge fin pour retenir tout dépôt et obtenir une crème limpide.","d":"« Café en fiole au soir versé, tient l'esprit clair et l'ennui chassé. »"},"cr-cremino-de-cafe":{"h":"Le crémino, diminutif italien évoquant la crème, désigne ces versions adoucies au lait où la liqueur de café se fait plus ronde et plus tendre que dans sa robe noire. Le café, né des hauts plateaux d'Éthiopie et répandu par les cafés d'autrefois, y troque son amertume contre une caresse laiteuse. C'est la liqueur des gourmands qui aiment le café sans en redouter la mordant.","p":"Le café demeurait réputé tonique et propre à réveiller les esprits ; le lait, lui, passait pour adoucir et tempérer cette ardeur. Le mélange était jugé plus aimable aux estomacs délicats.","c":"Le lait imposant ses limites, cette crème se garde peu et se consomme dans les semaines qui suivent, conservée au frais. Bien la remuer avant de servir, car le lait tend à se séparer au repos.","d":"« Café au lait en crème adouci, plaît au palais qu'amertume aigrit. »"},"cr-creme-de-cerises":{"h":"La cerise, fruit du cerisier que la tradition voulut rapporté du Pont par les armées romaines, charme l'Europe depuis l'Antiquité, où son éclat vermeil annonçait les beaux jours. On en tira de longue date des breuvages fameux, du guignolet aux ratafias de noyaux. Bien noire et gorgée de sucre, elle donne une crème profonde et veloutée.","p":"La cerise était réputée rafraîchissante et propre à purifier le sang et à délier les humeurs. La queue du fruit, en tisane, passait pour favoriser l'écoulement des eaux du corps.","c":"Ne choisir que des cerises bien noires et parfaitement mûres, sucrées à point, car un fruit pâle donne une crème sans corps. Si l'on garde quelques noyaux pour le parfum d'amande, qu'ils restent peu nombreux, leur amande recelant un principe nocif.","d":"« Cerise noire au temps des nids, fait la liqueur du cœur ravi. »"},"cr-creme-de-chataignes":{"h":"La châtaigne, fruit du châtaignier que l'on nomma longtemps « arbre à pain » dans les pays de montagne, nourrit des régions entières aux temps où le blé manquait sur les terres pauvres et acides. Le Périgord, l'Ardèche et la Corse en firent une providence d'automne, séchée, moulue ou bouillie. Sa crème douce et farineuse garde le goût réconfortant des feux de l'arrière-saison.","p":"La châtaigne, nourrissante et riche, était tenue pour fortifiante et propre à soutenir les corps au labeur et à rassasier durablement. On la conseillait aux travailleurs et aux poitrines fatiguées.","c":"User de châtaignes bien fraîches et saines, sans trace de ver ni de moisissure, et les cuire avant macération pour libérer leur douceur. Une gousse de vanille fondue arrondit la liqueur ; servir frais, en fin de repas d'automne.","d":"« Châtaigne au feu d'automne dorée, vaut le pain des heures resserrées. »"},"cr-creme-de-fraises-des-bois":{"h":"La fraise des bois, petite et parfumée, cousine sauvage de nos fraisiers de jardin, croît à l'orée des forêts depuis bien avant que les jardiniers ne s'avisent de la domestiquer. Son nom latin, 'fragaria', évoque l'odeur (de 'fragare', exhaler un parfum) qui trahit sa cachette sous les feuilles. Au temps où l'on cueillait à genoux dans la rosée, on en faisait des conserves au sucre et des ratafias destinés aux dames de qualité.","p":"Le fruit était tenu pour rafraîchissant et propre à 'tempérer les ardeurs', et l'on prêtait à ses feuilles, en tisane, une vertu astringente bienvenue.","c":"Cueillir les fraises à parfaite maturité, par temps sec, et les mettre à macérer sans les laver à grande eau pour ne point délaver l'arôme. Servir frais, en fin de repas, sur une glace ou un fromage blanc.","d":"« Fraise des bois cachée sous l'ombrage, fait au flacon le plus tendre breuvage. »"},"cr-creme-de-framboises":{"h":"La framboise, fruit du ronce-framboisier des sous-bois montagnards, tire son nom ancien français de 'frambeise', mot peut-être issu d'un croisement entre la fraise et le germanique désignant la mûre. Longtemps simple cueillette de montagne, elle gagna les vergers et fut chérie pour ses sirops et ses ratafias d'un rouge profond.","p":"On la disait rafraîchissante et apéritive, propre à réveiller l'appétit ; son vinaigre passait pour adoucir les gorges enrouées.","c":"Choisir des framboises bien colorées et fermes, et ne pas prolonger la macération outre mesure, car le fruit, fragile, tourne vite à l'amertume des pépins. Filtrer avec soin au tamis fin.","d":"« Framboise au flacon vite cueillie, garde au palais toute sa folie. »"},"cr-creme-de-menthe":{"h":"La menthe doit son nom à la nymphe Minthê de la mythologie grecque, changée en herbe odorante, et son usage de plante aromatique remonte à la plus haute Antiquité, des banquets romains aux jardins de simples monastiques. Les anciens en frottaient les tables pour réjouir les convives, et l'on en tirait des liqueurs vertes prisées des cloîtres.","p":"La menthe était réputée stomachique et digestive, propre à rafraîchir l'haleine et à calmer les estomacs lourds ; on la recommandait après les repas copieux.","c":"Préférer les feuilles cueillies avant la floraison, plus riches en parfum, et ne les laisser infuser que le temps voulu, sous peine d'un goût d'herbe. Servir très frais, voire glacé.","d":"« Qui de menthe emplit sa coupe, allège la plus lourde soupe. »"},"cr-creme-de-mures":{"h":"La mûre des haies, fruit noir de la ronce qui hérisse nos chemins creux, fut de tout temps la cueillette du pauvre, glanée à mains nues malgré les épines à la fin de l'été. Son nom vient du latin 'morum', et l'on en tirait jadis des encres comme des confitures, là où la vigne ne donnait point de vin.","p":"Le fruit passait pour rafraîchissant et l'on prêtait à sa décoction une vertu astringente, bonne pour les gorges irritées et les gencives.","c":"Ne cueillir que les mûres parfaitement noires et lustrées, après les premières fraîcheurs de septembre, en délaissant celles encore rougeâtres qui pincent la langue. Bien filtrer pour retenir les grains.","d":"« Mûre des ronces noire et mûrie, vaut bien l'épine qui l'a nourrie. »"},"cr-creme-de-myrtilles":{"h":"La myrtille, baie bleue des landes et des sapinières d'altitude, fut longtemps récoltée au peigne de bois par les montagnards qui en faisaient commerce. Son nom dérive du latin 'myrtillus', diminutif du myrte, et son suc tenace teintait les doigts et les lèvres de ceux qui s'y attardaient. On en tira de longue date des teintures et des breuvages aux reflets pourpres.","p":"La baie était réputée resserrer les entrailles et fortifier la vue ; les anciens herbiers la conseillaient à ceux qui peinaient à voir au crépuscule.","c":"Choisir des baies bien mûres et sauvages de préférence, plus parfumées que les cultivées. Une pointe de cannelle relève leur douceur sans la masquer ; laisser reposer le flacon à l'abri du jour.","d":"« Bleuet des monts qui tache la main, teinte le verre et réjouit l'humain. »"},"cr-creme-de-feuilles-de-pecher":{"h":"La feuille de pêcher, longue et lancéolée, servait jadis au verger autant qu'à l'office, car on lui prêtait un parfum d'amande qui anoblissait les crèmes et les vins de ménage. Le pêcher, venu de Perse par les routes anciennes — d'où son nom 'persica' —, fut acclimaté dès l'Antiquité, et ses feuilles entraient dans maintes recettes de printemps.","p":"La feuille était réputée vermifuge et légèrement laxative ; mais elle recèle des composés voisins de l'amande amère qui libèrent un principe vénéneux, et l'on n'en usait qu'à dose mesurée, sans jamais forcer l'infusion.","c":"Cueillir les jeunes feuilles au printemps, après la chute des fleurs, et compter avec parcimonie. Une macération brève suffit à prendre le parfum sans concentrer ce qui doit rester discret.","d":"« Feuille de pêcher, parfum d'amandée, plaît à la coupe mais veut être mesurée. »"},"cr-creme-de-peches-de-vigne":{"h":"La pêche de vigne, à la chair sanguine et au noyau adhérent, doit son nom à l'antique usage de planter les pêchers au bout des rangs de ceps, où ils annonçaient aux vignerons l'arrivée des maladies de la treille. Plus rustique et plus parfumée que ses cousines de verger, elle mûrit tard, quand les vendanges approchent.","p":"La pêche passait pour rafraîchissante et adoucissante, propre à tempérer les chaleurs de l'été et à flatter les estomacs délicats.","c":"Choisir des pêches bien mûres et juteuses, à la chair rouge prononcée, qui donneront couleur et arôme. Quelques amandes du noyau peuvent relever le parfum, mais en très petit nombre seulement.","d":"« Pêche de vigne au sang vermeil, mûrit au pas du soleil de tonnelle. »"},"cr-creme-de-poires":{"h":"La poire, fruit du poirier que les anciens jardiniers greffaient avec un art jaloux, comptait des centaines de variétés dans les vergers d'autrefois, chacune nommée et choyée. Son nom vient du latin 'pirum', et on la cueillait souvent encore ferme pour la faire mûrir au fruitier, sur la paille, à l'abri du gel.","p":"La poire mûre était tenue pour rafraîchissante et bienfaisante au ventre, tandis qu'on disait des plus dures qu'elles 'pesaient à l'estomac' si on les mangeait crues.","c":"Préférer une variété fondante et bien parfumée, cueillie à juste maturité, ni verte ni blette. La vanille soutient sa délicatesse ; filtrer doucement pour garder la limpidité.","d":"« Poire à point cueillie en son automne, au flacon mûr sa douceur abandonne. »"},"cr-creme-de-pomme":{"h":"La pomme, fruit roi des vergers du Nord, accompagne l'homme depuis les âges les plus reculés, des pommes sauvages des forêts aux mille variétés greffées des abbayes. La 'golden', tardive venue, n'en perpétue pas moins l'antique usage de tirer du verger boissons et conserves, du cidre au ratafia, là où la vigne se faisait rare.","p":"La pomme était réputée rafraîchissante et bénigne, bonne au cœur et propre à 'réjouir les esprits' ; on la disait digestible entre toutes lorsqu'elle était bien mûre.","c":"Choisir des pommes à la fois sucrées et un peu acidulées pour éviter la fadeur, et hâter la mise en flacon avant que le jus ne brunisse. La vanille en arrondit l'acidité.","d":"« Pomme du verger bien mûrie, fait au logis liqueur fleurie. »"},"cr-creme-de-prunes":{"h":"La prune, fruit du prunier répandu de l'Orient jusqu'à nos haies, doit son nom au latin 'prunum' et fut de tout temps séchée en pruneaux pour les provisions d'hiver autant que distillée en eaux-de-vie. Les vieux vergers en gardaient maintes sortes, de la reine-claude dorée à la quetsche violette, chacune trouvant sa place au flacon comme au compotier.","p":"La prune était réputée laxative et rafraîchissante, recommandée à ceux que l'embarras des entrailles tourmentait ; on en faisait grand cas pour 'relâcher le ventre paresseux'.","c":"Choisir des prunes bien mûres et sucrées, et ne briser qu'avec mesure quelques noyaux si l'on veut une pointe d'amande, sans plus. Servir frais, après un repos prolongé du flacon.","d":"« Prune au soleil bien dorée, vaut au flacon double rosée. »"},"cr-creme-de-vanille":{"h":"La vanille, gousse d'une orchidée grimpante venue des terres chaudes du Nouveau Monde, fut longtemps un trésor rare et coûteux, mis sous clef au même titre que les épices royales. Son nom, diminutif espagnol de 'vaina', la gaine, évoque la cosse qu'il faut affiner avec patience pour qu'y naisse le parfum tant prisé des confiseurs.","p":"La vanille passait pour cordiale et tonique, réputée 'réjouir le cœur' et réveiller les esprits ; on la mêlait aux remèdes des convalescents et aux breuvages de fête.","c":"Choisir des gousses souples et grasses, point sèches ni cassantes, et les fendre dans la longueur pour livrer leurs grains. Le safran et le girofle, à dose discrète, en rehaussent la chaleur sans l'écraser.","d":"« Gousse fendue qui parfume la coupe, change en festin la plus simple soupe. »"},"cr-creme-facon-baileys":{"h":"Le mariage de la crème et du whisky relève d'une tradition celtique ancienne, où l'on adoucissait les eaux-de-vie d'orge par le lait et le miel pour en tempérer la rudesse. Le whisky, dont le nom gaélique 'uisge beatha' signifie 'eau de vie', se prêta naturellement à ces crèmes onctueuses que les hivers du Nord rendaient si réconfortantes au coin du feu.","p":"On tenait ces breuvages lactés pour réchauffants et nourrissants, propres à 'remettre du baume au cœur' dans les froidures ; le whisky y apportait sa chaleur cordiale.","c":"Cette crème, riche en lait et en œufs, ne se garde qu'au frais et se consomme dans le mois, sans attendre. La bien agiter avant de servir, glacée, en digestif.","d":"« Lait et whisky d'un même flacon, font au coin du feu bonne maison. »"},"cr-creme-de-kummel":{"h":"Le kümmel, dont le nom germanique désigne le cumin, est une liqueur ancienne des terres du Nord et de l'Est, où l'on parfumait les eaux-de-vie de ces graines aromatiques depuis des siècles. Confondu de longue date avec le carvi des prés, le cumin entrait dans les remèdes de table autant que dans le pain et les fromages des pays froids.","p":"La graine était réputée carminative et stomachique, souveraine contre les ventosités et les digestions pénibles ; on la mâchait après les repas pour apaiser le ventre.","c":"Concasser légèrement les graines avant macération pour qu'elles livrent leur huile, et n'ajouter le safran qu'à dose infime, pour la teinte plus que pour le goût. Laisser reposer longuement avant de filtrer.","d":"« Graine de cumin au fond du verre, fait au festin paix de l'estomac amer. »"},"cr-ratafia-d-absinthe-1902":{"h":"L'absinthe, la 'plante des dieux' que les Grecs nommaient 'apsinthion', fut depuis l'Antiquité la reine des amères, vouée à Artémis et réputée chasser vers et fièvres. Les ratafias d'autrefois, dont celui-ci porte millésime, l'unissaient au genièvre et à l'angélique pour en faire un cordial d'arrière-saison, dans le goût des liqueurs de ménage d'avant les interdits.","p":"L'absinthe était réputée tonique, vermifuge et fébrifuge, souveraine pour 'fortifier l'estomac' ; mais elle recèle la thuyone, principe qui devient pernicieux à forte dose, et l'on n'en usait jadis qu'avec une grande retenue.","c":"N'employer qu'une faible quantité de feuilles et veiller à ne point prolonger la macération, qui exalterait l'amertume et ce qu'elle cache. L'eau de fleur d'oranger en adoucit l'âpreté ; servir à très petite mesure.","d":"« Verte amère au flacon mesurée, soigne qui la boit à juste pesée. »"},"rt-ratafia-d-angelique-1750":{"h":"L'angélique, dite herbe aux anges, fut longtemps cultivée dans les jardins de monastères, notamment au Marais poitevin où ses tiges confites font encore la réputation de Niort. Son nom latin, Angelica archangelica, dit assez la place céleste qu'on lui prêtait au temps des grandes pestes, où l'on mâchait sa racine pour s'en croire protégé. Apéritive et chargée d'arômes verts et musqués, elle entre dans nombre de liqueurs monastiques.","p":"On la disait stomachique et cordiale, réchauffant l'estomac languissant et chassant les vents ; les anciens herboristes la rangeaient parmi les grandes plantes toniques. Sa saveur ambrée fait merveille en fin de repas.","c":"Ce ratafia velouté, où l'angélique épouse le cacao amer et la crème, se sert bien frais, en cuillère plutôt qu'au verre. Laisser reposer quelques jours que les arômes se marient avant de goûter.","d":"« Tige d'ange au fond du verre, allège le cœur et la chère. »"},"rt-ratafia-de-noyaux-au-miel-1829":{"h":"Les ratafias de noyaux comptent parmi les plus anciens de nos campagnes : on cassait les noyaux d'abricot ou de cerise pour en tirer l'amande, dont le parfum rappelle l'amande amère. Mariée au miel, cette amertume fine donnait une liqueur prisée des tables bourgeoises du temps de la Restauration. La recette se transmettait de mère en fille, chacune gardant son tour de main.","p":"On lui prêtait des vertus digestives et adoucissantes, le miel étant tenu pour un baume des gorges et des poitrines. Toutefois les amandes de noyaux renferment un principe qui libère du cyanure : on n'en mettra qu'avec mesure, et jamais en abondance.","c":"Concasser les noyaux sans les réduire en poudre, et respecter une petite dose pour rester en deçà du danger. Filtrer avec soin sur étamine fine et laisser vieillir : le temps arrondit l'amertume.","d":"« Noyau brisé, miel versé, douce amertume au palais. »"},"rt-ratafia-de-brou-de-noix-1785":{"h":"Le brou, cette enveloppe verte et charnue qui entoure la coque, se cueille à la Saint-Jean, quand la noix est encore tendre et que la lame y passe d'un trait. Riche en tanins, il noircit les doigts et teint la liqueur d'un brun profond ; les anciens en faisaient aussi une teinture pour le bois et la laine. Le ratafia de brou, austère et boisé, fut un cordial de famille bien avant la Révolution.","p":"On le tenait pour tonique et fortifiant, réputé soutenir les estomacs paresseux après les repas trop riches. Son amertume tannique, dit-on, réveillait les appétits las.","c":"Ne cueillir que des brous bien verts, avant durcissement de la coque, et manier gants aux mains pour épargner les doigts. Un long séjour en bonbonne, plusieurs mois, adoucit l'âpreté première.","d":"« À la Saint-Jean cueille le brou, plus tard le couteau s'y émousse jusqu'au bout. »"},"rt-ratafia-de-cassis-1820":{"h":"Le cassis, ce groseillier noir aux baies parfumées, connut sa gloire en Bourgogne où l'on vantait dès le XVIIIe siècle ses ratafias et cordiaux. Un fameux abbé en fit même l'éloge en attribuant mille vertus à sa feuille comme à son fruit. La baie, noire et musquée, donne une liqueur d'un pourpre épais qui sent l'arrière-saison.","p":"Feuilles et baies passaient pour toniques et rafraîchissantes, et l'on disait le cassis ami des articulations fatiguées. Son fruit gorgé de couleur en faisait un cordial réconfortant des soirées humides.","c":"Choisir des baies bien mûres, presque noires, et ne pas trop sucrer pour garder le mordant du fruit. Un repos au frais et une bonne filtration donnent à la robe sa limpidité.","d":"« Cassis de septembre en bouteille close, garde l'été quand l'hiver s'impose. »"},"rt-ratafia-de-cedrat":{"h":"Le cédrat est le plus ancien des agrumes parvenus jusqu'en Méditerranée, apporté de l'Orient bien avant l'orange et le citron. Son écorce épaisse et bosselée, peu juteuse mais éperdument parfumée, se confit en Corse et en Calabre depuis des siècles. On le tenait pour un fruit précieux, presque sacré dans certaines traditions.","p":"Son zeste odorant était réputé tonique et digestif, et l'on respirait son parfum pour ranimer les esprits défaillants. Les vieux traités le rangeaient parmi les agrumes cordiaux qui fortifient le cœur.","c":"Ne prélever que la partie colorée du zeste, en évitant le ziste blanc qui apporte une amertume rêche. Le cédrat aimant la douceur, équilibrer le sucre et laisser infuser longuement pour extraire tout son parfum.","d":"« Cédrat à l'écorce épaisse, c'est dans la peau que loge la richesse. »"},"rt-ratafia-cerises-et-framboises":{"h":"Cerise et framboise font depuis toujours bon ménage dans les conserves de nos vergers, l'une apportant la chair charnue, l'autre le parfum sauvage des ronciers. Les ratafias de fruits rouges, relevés d'un soupçon d'épice, garnissaient les buffets de noces campagnardes. Une pointe de coriandre fraîche, ici, leur prête un accent plus rare et résineux.","p":"On disait ces fruits rouges rafraîchissants et propres à apaiser les fièvres légères de l'été. Leur acidité gaie passait pour réveiller l'appétit et égayer l'humeur.","c":"Choisir des cerises bien mûres et des framboises à peine cueillies, qui rendent vite leur jus. Filtrer sans presser pour garder une robe claire, et servir frais en accord avec un entremets aux fruits.","d":"« Cerise et framboise au même flacon, font danser l'été sous le balcon. »"},"rt-ratafia-de-citronnelle-xvii-siecle":{"h":"Sous le nom ancien de citronnelle, nos aïeux désignaient le plus souvent la mélisse, cette labiée au feuillage froissé qui exhale le citron. Les religieuses en tiraient une fameuse eau de mélisse, célèbre depuis le XVIIe siècle pour ranimer les défaillances. Marié au zeste de citron et à la cannelle, ce ratafia prolonge cette tradition d'eaux cordiales.","p":"La mélisse était réputée calmante et stomachique, amie des cœurs agités et des digestions difficiles. On la prenait volontiers le soir pour adoucir les humeurs et favoriser le repos.","c":"Employer des feuilles fraîches et vertes, cueillies avant la floraison, où l'arôme citronné est le plus franc. Ne pas prolonger l'infusion outre mesure, sous peine d'une amertume herbacée ; servir frais après le repas.","d":"« Feuille froissée sent le citron, calme le soir d'un doux frisson. »"},"rt-ratafia-de-clementines":{"h":"La clémentine est une venue tardive parmi les agrumes, née en Afrique du Nord du croisement du mandarinier et d'un oranger amer, et dont le nom honore un père religieux qui l'aurait remarquée dans son jardin. Plus douce que la mandarine et sans pépins, elle s'est imposée sur les tables d'hiver. Ce ratafia au rhum et aux épices de chambre en fait un cordial des fêtes.","p":"Comme tous les agrumes, on la disait riche d'un zeste tonique et apéritif, propre à réveiller l'estomac. Mariée à la cannelle, au girofle et au macis, elle compose une liqueur chaleureuse de saison froide.","c":"Préférer des clémentines non traitées, dont on use le zeste sans crainte, et écarter le blanc trop amer. Doser les épices avec retenue pour qu'elles soutiennent le fruit sans le masquer ; servir tiède aux veillées d'hiver.","d":"« Clémentine et clou de girofle, en décembre le verre s'engloffe. »"},"rt-ratafia-de-coings":{"h":"Le coing, fruit dur et velouté que l'on ne mange jamais cru, parfume les vergers d'automne d'une odeur qui embaume toute une pièce. Les Anciens le consacraient à la déesse de l'amour, et il fut longtemps gage de bonheur offert aux jeunes mariés. Cuit en pâte, en gelée ou macéré au vin, il livre un arôme miellé incomparable.","p":"On le tenait pour astringent et fortifiant des entrailles, bon contre les relâchements d'estomac. Son parfum suave passait aussi pour réjouir les sens et réconforter les convalescents.","c":"Choisir des coings bien jaunes et odorants, et les essuyer de leur duvet avant de les râper ou trancher. Le fruit étant tannique, un repos prolongé et une généreuse part de sucre arrondissent la liqueur.","d":"« Coing parfumé dans la maison, vaut tout l'or de la saison. »"},"rt-ratafia-de-fleurs-au-miel":{"h":"Les ratafias de fleurs réunissaient au creux d'un même flacon les parfums du jardin : violette, œillet, et toutes corolles odorantes cueillies au petit matin. Adoucis de miel, ils tenaient lieu de cordial galant que l'on offrait dans les ruelles et les salons d'autrefois. Chaque fleur y apportait sa note, faisant de la liqueur un bouquet liquide.","p":"On prêtait à ces fleurs des vertus cordiales et adoucissantes, réjouissantes pour le cœur et propres à parfumer l'haleine. Le miel y ajoutait sa douceur, baume réputé des gorges et des humeurs lasses.","c":"Ne cueillir que des fleurs sûres et comestibles, par temps sec et sans rosée, en écartant tout calice vert qui verdirait le goût. Filtrer finement et user le miel avec mesure, pour que la douceur n'étouffe pas le parfum.","d":"« Bouquet noyé de miel doré, garde au flacon l'avril passé. »"},"rt-ratafia-de-fleurs-d-orangers":{"h":"La fleur du bigaradier, l'oranger amer, donne par distillation cette eau de fleur d'oranger qui embaume pâtisseries et liqueurs depuis le temps des cours méridionales. On en parfumait les desserts de fête et l'on en offrait aux mariées, dont la couronne en était tressée. Son néroli, parfum tiré de la même fleur, fit la fortune des parfumeurs de Grasse.","p":"L'eau de fleur d'oranger était réputée calmante et propre à apaiser les nerfs agités, qu'on prenait volontiers au coucher. On la disait amie des digestions et baume des humeurs trop vives.","c":"User d'une eau de fleur d'oranger véritable et non d'un arôme de synthèse, et la verser avec retenue car elle domine vite. Inutile de longue macération : un simple mariage au sirop suffit, à servir bien frais.","d":"« Fleur d'oranger au soir versée, berce le sommeil de la mariée. »"},"rt-ratafia-de-framboises":{"h":"La framboise, fruit du ronce des bois cultivé puis domestiqué dans nos jardins, garde de son origine sauvage un parfum que nul autre fruit n'égale. Son nom même rappellerait une vieille racine évoquant la mûre des taillis. Cueillie en pleine chaleur, elle se gâte en un jour, ce qui en fait depuis toujours un fruit que l'on hâte de confire ou de macérer.","p":"On la disait rafraîchissante et légèrement laxative, propre à tempérer les ardeurs de l'été. Son parfum gai passait pour réjouir l'humeur autant que le palais.","c":"Choisir des framboises mûres mais fermes, et les mettre à macérer le jour même, avant qu'elles ne tournent. Une simple infusion dans l'eau-de-vie sucrée suffit : trop de sucre noierait la finesse du fruit.","d":"« Framboise du jour à l'alcool plongée, dure un hiver, l'été sauvé. »"},"rt-ratafia-de-genievre":{"h":"La baie de genièvre, fruit bleu-noir d'un humble buisson des landes et garrigues, parfume depuis des siècles les marinades, les choucroutes et les eaux-de-vie du Nord. C'est elle qui donne au genièvre flamand et au gin leur âme résineuse. Récoltée en battant les branches piquantes sur un drap, elle mûrit lentement, demandant souvent deux années sur le rameau.","p":"On la tenait pour diurétique et tonique, amie des reins et des digestions lourdes, et l'on en brûlait jadis pour assainir l'air des chambres malades. Son arôme balsamique passait pour fortifiant ; à forte dose toutefois, elle échauffe et fatigue, et se prend avec mesure.","c":"Écraser légèrement les baies bien mûres pour en libérer l'arôme sans broyer la graine, qui apporterait de l'amertume. Une eau pure et un long repos donnent une liqueur nette ; servir frais, en digestif après les mets gras.","d":"« Baie de genièvre des terres maigres, allège la table aux plats trop aigres. »"},"rt-ratafia-de-grenade":{"h":"La grenade, fruit aux mille grains rubis enclos dans une coque de cuir, voyagea d'Orient vers la Méditerranée où elle devint emblème de fécondité et d'abondance. Les jardins de Grenade lui doivent leur nom, et son suc parfume le grenadine des comptoirs comme jadis les sirops d'apothicaire. Ouvrir une grenade, c'est libérer une cascade de perles acidulées.","p":"On la disait rafraîchissante et astringente, propre à tempérer les chaleurs et à resserrer les chairs relâchées. Son suc aigre-doux passait pour ranimer l'appétit et désaltérer les fiévreux.","c":"Choisir des grenades lourdes et bien colorées, signe de grains gorgés de jus, et les égrener en évitant la peau blanche amère. Filtrer pour retenir les pépins, et relever d'une pointe de cannelle qui épouse l'acidité du fruit.","d":"« Grain de grenade, perle de feu, teinte le verre et réjouit les yeux. »"},"rt-ratafia-de-grenoble-ou-de-teissier":{"h":"Ce ratafia dauphinois marie le jus des cerises noires à leurs propres amandes et à quelques feuilles de cerisier, selon un usage frugal où l'arbre tout entier nourrissait la liqueur. La cerise, fille du merisier sauvage, accompagne les vergers d'Europe depuis l'Antiquité et son nom même remonterait à la cité de Cérasonte, sur les rives du Pont-Euxin. À Grenoble, on aimait ces ratafias de fruits rouges que l'on tirait à la fin des moissons pour les offrir aux hôtes de passage.","p":"Le suc de cerise était tenu pour rafraîchissant et bienfaisant au sang, tandis que l'amande du noyau parfumait d'un fond délicat d'amande amère. On se gardera toutefois de prodiguer ces amandes de cerise, qui renferment un principe cyanhydrique : quelques-unes suffisent à l'arôme, l'excès est à fuir.","c":"Choisir des cerises bien noires et gorgées de soleil, et n'écraser qu'une poignée de noyaux pour relever sans dominer. Une longue garde en cave assouplit l'âpreté des feuilles et fond la cannelle dans le fruit.","d":"« Cerise noire et noyau fin, font le ratafia du matin. »"},"rt-ratafia-de-groseilles":{"h":"La groseille à grappes, modeste arbuste des jardins du Nord et des cloîtres médiévaux, fut longtemps cultivée pour sa fraîcheur acidulée avant de gagner les tables raffinées. Son nom paraît hérité du francique, et les anciens herboristes la rangeaient parmi les fruits « tempérants » propres à calmer les ardeurs de l'été. On la mettait en gelées, en sirops et en ratafias où sa pointe acide équilibrait la douceur du sucre.","p":"La groseille était réputée rafraîchissante et apéritive, bonne pour apaiser la soif et réveiller l'appétit aux jours de chaleur. On lui prêtait aussi une vertu légèrement laxative, que la décoction d'eau et le sucre venaient adoucir.","c":"Préférer des grappes mûres mais encore fermes, cueillies par temps sec pour préserver leur éclat. Servir frais, en fin de repas estival, après avoir bien clarifié la liqueur par une filtration soignée.","d":"« Groseille en grappe et sucre clair, désaltèrent qui boit à l'air. »"},"rt-ratafia-de-guignolet-a-l-ancienne":{"h":"Le guignolet, gloire de l'Anjou, tire son nom de la guigne, cette petite cerise à chair tendre que l'on associait aux griottes pour en corriger la douceur. Sa préparation se transmettait de génération en génération dans les manoirs angevins, où l'on patientait que les cerises noires aient atteint leur pleine maturité. L'ajout de framboises et d'épices de chambre lui conférait ce velouté qui fit sa renommée bien au-delà de la Loire.","p":"Les cerises noires étaient tenues pour cordiales et amies du cœur, propres à réjouir l'esprit et faciliter la digestion des repas copieux. La macération préservait sagement le fruit sans qu'on en brisât les noyaux à l'excès, dont l'amande recèle un principe à manier avec retenue.","c":"Mêler guignes, griottes et cerises noires pour conjuguer le sucre et l'acide, et n'épépiner qu'une partie des fruits afin de garder un soupçon de noyau. Laisser reposer en lieu frais et obscur avant de filtrer sur étamine.","d":"« Guigne et griotte au même verre, font une liqueur de bonne chère. »"},"rt-ratafia-de-jonquilles":{"h":"La jonquille, narcisse jaune des prairies humides, annonce le printemps de son parfum capiteux et fut de tout temps cueillie pour orner les chambres et embaumer les liqueurs de fleurs. Son nom remonte au latin juncus, le jonc, par allusion à ses feuilles fines et dressées. Les amateurs d'autrefois en tiraient un ratafia délicatement odorant, réservé aux palais curieux des senteurs florales.","p":"On prêtait jadis à ses fleurs des vertus calmantes et l'on goûtait surtout leur parfum suave. Mais le narcisse est plante âcre et vénéneuse en toutes ses parties : on n'emploiera que les pétales en infusion brève, sans jamais en abuser, car le bulbe et la sève sont à proscrire absolument.","c":"Ne retenir que les fleurs fraîchement écloses, écartant tige et cœur trop chargés. Limiter le temps de macération pour saisir le parfum sans extraire l'amertume, puis filtrer avec grand soin avant de servir en très petite mesure.","d":"« Belle jonquille au flacon d'or, plaît au nez mais point au corps. »"},"rt-ratafia-de-mures":{"h":"La mûre des ronces, butin des haies et des chemins creux, fut de longue date le fruit du pauvre que l'on cueillait au prix de quelques égratignures à la fin de l'été. Les Anciens connaissaient déjà la ronce, dont Dioscoride vantait l'usage, et le folklore voulait qu'on ne la cueillît plus passé la Saint-Michel, quand le diable l'aurait souillée. De ce fruit noir et juteux, on faisait gelées, vins et ratafias d'une belle teinte pourpre.","p":"La mûre était réputée rafraîchissante et astringente, bonne pour la gorge irritée et pour resserrer les humeurs. On en tirait jadis des gargarismes, et sa liqueur passait pour réconforter doucement après les marches d'automne.","c":"Choisir des mûres bien noires et fondantes, jamais rougeâtres, cueillies loin des bords de route poussiéreux. Filtrer avec patience à travers un linge serré pour ôter les petits grains, et laisser la couleur se parfaire en bouteille.","d":"« Mûre noire avant Saint-Michel, fait au flacon liqueur de miel. »"},"rt-ratafia-de-noyaux":{"h":"Le ratafia de noyaux compte parmi les plus anciennes liqueurs domestiques, tiré des amandes contenues dans les noyaux d'abricots et de pêches que l'on récoltait après les confitures. Cette économie du verger, où rien ne se perdait, donnait une liqueur au goût caractéristique d'amande amère, jadis fort prisée à la table bourgeoise. L'eau de rivière, plus douce que l'eau de puits, entrait dans les recettes soignées du temps.","p":"On disait ce ratafia stomachique et digestif, propre à clore agréablement les repas. Mais l'amande des noyaux recèle un principe cyanhydrique : la mesure ancienne d'un quart d'amandes pour le reste n'était pas fortuite, et l'on se gardera bien de forcer cette proportion.","c":"Concasser les amandes juste avant l'emploi pour libérer leur arôme, sans jamais en mettre plus que de raison. Une cannelle légère arrondit le bouquet ; filtrer après une longue macération en cave fraîche.","d":"« Du noyau tire ton parfum, mais n'en prends qu'un sur quatre, point un. »"},"rt-ratafiat-de-noix-recette-du-vxii-siecle":{"h":"Le ratafia de noix vertes, immémorial dans les campagnes, se prépare des noix encore tendres cueillies aux alentours de la Saint-Jean, quand la coque n'est pas formée et qu'une aiguille les traverse aisément. Le noyer, arbre tutélaire que les Romains appelaient l'arbre de Jupiter, fournissait bois, huile et cette liqueur ambrée que chaque maison tenait à honneur de mettre en fût. Le brou teinte l'eau-de-vie d'un brun profond et lui prête son amertume noble.","p":"La noix verte était tenue pour tonique et fortifiante, amie de l'estomac paresseux et réputée raffermir le corps. Son brou amer passait pour vermifuge et dépuratif dans la médecine des simples d'autrefois.","c":"Cueillir les noix vertes à la Saint-Jean, avant que le bois du noyau ne durcisse, et se protéger les mains que le brou teint durablement. Les deux clous de girofle suffisent : laisser brunir et mûrir de longs mois avant de goûter.","d":"« Noix de la Saint-Jean cueillie, fait la liqueur la mieux nourrie. »"},"rt-ratafia-de-peches":{"h":"La pêche, venue de Perse dans l'Antiquité par les routes de l'Orient — d'où son nom de malum persicum, la pomme de Perse —, gagna nos vergers comme un fruit de luxe à la chair parfumée. Sous l'appellation de ratafia de pêches, les recueils anciens mêlaient parfois la poire mûre et tout un cortège d'épices de chambre. On en faisait une liqueur dorée que l'on servait aux visites de cérémonie.","p":"La pêche était réputée rafraîchissante et bienfaisante à l'estomac échauffé, et l'on prêtait à ses fleurs et feuilles une vertu laxative douce. Les épices ajoutées, girofle et macis, passaient pour réchauffer et soutenir la digestion.","c":"Choisir des fruits parfaitement mûrs et juteux, parés de leur duvet, pour que le sucre du fruit porte la liqueur. Doser les épices avec retenue afin de ne pas masquer le parfum délicat de la pêche, et filtrer clair.","d":"« Pêche de Perse au verre versée, fait l'âme et le ventre apaisés. »"},"rt-ratafia-de-raisin-muscat":{"h":"Le raisin muscat, dont le nom évoque le musc tant son parfum est puissant, fut cultivé dès l'Antiquité méditerranéenne et célébré pour sa douceur sucrée. De son jus, les anciens vignerons tiraient ratafias et vins de liqueur, où l'eau-de-vie venait fixer le sucre naturel du fruit avant la fermentation complète. La cannelle, épice de prix venue d'Orient, en relevait la rondeur.","p":"Le raisin muscat était tenu pour cordial et nourrissant, ami des convalescents et propre à réconforter les esprits abattus. On le disait généreux au sang et bienfaisant en petite quantité, à la manière des vins doux d'autrefois.","c":"Presser un raisin bien mûr et sucré, cueilli aux premières gelées blanches qui concentrent son nectar. Muter le jus à l'eau-de-vie avant qu'il ne fermente, et laisser la cannelle infuser doucement avant de soutirer au clair.","d":"« Muscat doré dans l'eau-de-vie, garde l'été tout l'hiver durci. »"},"rt-ratafia-de-rossoli-dit-populo":{"h":"Le rossolis, liqueur fameuse des cours du Grand Siècle, doit son nom à la rosée du soleil — ros solis — et à la petite plante carnivore, la drosère, dont les feuilles luisantes semblent perlées de rosée même en plein jour. On l'appelait aussi populo, et cette eau cordiale épicée de girofle, poivre, coriandre et anis comptait parmi les délices des ruelles. Sa réputation galante en fit l'une des liqueurs les plus citées des XVIIe et XVIIIe siècles.","p":"Le rossolis passait pour réconfortant, stomachique et propre à réchauffer le cœur défaillant, vertu qu'on lui prêtait volontiers en raison de ses épices ardentes. La drosère y entrait à dose infime, simple curiosité de droguiste plutôt que principe actif, et l'on s'en tenait à la mesure ancienne sans jamais la forcer.","c":"Doser les épices chaudes avec mesure pour qu'aucune ne domine l'accord, et ne mettre de la drosère qu'une parcimonieuse pincée. Laisser reposer plusieurs semaines en flacon clos, puis filtrer jusqu'à parfaite limpidité.","d":"« Rossolis de rosée et d'épice, charme la table et l'esprit qu'il grise. »"},"rt-ratafia-de-semences-chaudes-ou-eau-des-sept-graines-1730":{"h":"L'Eau des Sept Graines appartient à la grande famille des liqueurs de « semences chaudes », ces eaux carminatives que les apothicaires composaient en assemblant les graines aromatiques réputées dissiper les vents. Anis, carvi, cumin, fenouil, ache et leurs pareilles formaient un quatuor savant transmis de recueil en recueil depuis le Moyen Âge. On la tenait pour une liqueur de santé autant que de plaisir, à prendre par petits verres après le repas.","p":"Toutes ces semences passaient pour carminatives et digestives au premier chef, propres à chasser les flatuosités et à soulager l'estomac chargé. L'ensemble était réputé stomachique et tonique, vertu cardinale de ces eaux d'office d'autrefois.","c":"Concasser légèrement les graines pour libérer leurs huiles avant de les noyer dans l'eau-de-vie. Une macération longue et un sucrage modéré laissent parler l'aromatique : filtrer fin, et servir en petite mesure au sortir de table.","d":"« Sept semences au même flacon, font à l'estomac sa raison. »"},"rt-ratafia-de-vanille":{"h":"La vanille, gousse d'une orchidée grimpante originaire du Mexique, fut rapportée en Europe par les conquérants espagnols qui la découvrirent chez les peuples mésoaméricains, lesquels en parfumaient déjà leur boisson de cacao. Longtemps rare et précieuse, elle ne fructifia hors de son berceau qu'une fois percé le secret de sa pollinisation. De cette gousse noire et parfumée, on tira un ratafia d'une suavité sans pareille, réservé aux liqueurs de luxe.","p":"La vanille était tenue pour cordiale et stomachique, propre à réconforter les esprits et à favoriser la digestion. On lui prêtait jadis une vertu réjouissante, voire échauffante, qui la rangeait parmi les aromates de bonne compagnie.","c":"Choisir des gousses grasses et souples, bien noires et luisantes, qu'on fendra dans la longueur pour livrer leurs grains. Une infusion patiente dans l'alcool sucré, à l'abri de la lumière, développe pleinement l'arôme sans amertume.","d":"« Gousse de vanille en l'eau-de-vie, embaume le verre et l'âme ravie. »"},"rt-ratafia-des-quatre-fruits-xviiie-siecle":{"h":"Le Ratafia des Quatre Fruits assemble cerises, groseilles, framboises et cassis selon une harmonie classique des recueils du XVIIIe siècle, où l'on dosait par livres ces baies des jardins. Chaque fruit y apportait sa note — la douceur de la cerise, l'acide de la groseille, le parfum de la framboise et la profondeur du cassis. Cette liqueur de ménage se préparait au plus fort de l'été, quand tous les fruits rouges abondaient ensemble.","p":"L'assemblage de ces baies était réputé rafraîchissant et cordial, ami du sang et propre à réjouir le cœur en fin de repas. On vantait surtout le cassis, tenu pour fortifiant et bienfaisant aux articulations dans la médecine des simples.","c":"Respecter la juste proportion des anciens, où la cerise domine et le cassis reste minoritaire pour ne pas étouffer les autres. Cueillir chaque fruit à parfaite maturité, le même jour si possible, et laisser la couleur s'unifier en bouteille avant de filtrer.","d":"« Quatre fruits en un seul flacon, gardent l'été sous le bouchon. »"},"rt-ratafia-d-illets-1":{"h":"L'œillet rouge, fleur que les Anciens nommaient girofle de jardin pour son parfum proche du clou de girofle, ornait jadis les bouquets de noces et les liqueurs de fleurs des dames de qualité. Son nom grec, dianthos, en faisait la « fleur des dieux », et l'on prisait ses pétales d'un rouge profond autant pour leur couleur que pour leur senteur épicée. De ces pétales frais, relevés d'un peu de cannelle et de coriandre, on tirait un ratafia d'une élégance toute florale.","p":"L'œillet était réputé cordial et réconfortant, propre à ranimer les esprits défaillants et à parfumer agréablement l'haleine. On lui prêtait une vertu tonique légère, à la mesure de son arôme chaud et poivré.","c":"N'employer que les pétales frais des œillets rouges les plus odorants, en retranchant le talon blanc de la base qui apporte de l'amertume. Macérer brièvement pour saisir le parfum, puis filtrer clair afin de garder la belle robe rosée.","d":"« Œillet vermeil dans l'eau-de-vie, donne au flacon couleur et vie. »"},"rt-ratafia-d-illets-2":{"h":"L'œillet, dont le nom grec 'dianthus' signifie 'fleur des dieux', parfumait jadis les jardins de curé et les ratafias de ménagère. Sa variété rouge sang, à l'odeur poivrée évoquant le clou de girofle, servait à colorer et à embaumer les vins de fête. Dans les campagnes, on cueillait ses pétales au matin, après la rosée, pour en tirer cette eau cordiale que l'on offrait aux visiteurs de marque.","p":"L'eau d'œillet passait pour réconforter le cœur défaillant et chasser les vapeurs de mélancolie ; on lui prêtait aussi la vertu de raffermir le ton de l'estomac.","c":"Ôter soigneusement l'onglet blanc à la base des pétales, qui apporte une amertume disgracieuse, et ne garder que la part colorée. Servir frais, en petit verre, après quelques semaines de repos en flacon bouché.","d":"« Pétale d'œillet au fond du verre, garde au logis le cœur prospère. »"},"rt-ratafia-d-oranges-du-portugal":{"h":"L'oranger doux fut longtemps nommé 'orange du Portugal', car ce sont les navigateurs lusitaniens qui répandirent en Europe les fruits sucrés rapportés d'Orient, supplantant la bigarade amère des Arabes. Tenu pour un luxe princier, l'oranger ornait les serres chaudes des grandes maisons, et son zeste parfumait ratafias et confitures de cour. On disait d'une table bien pourvue qu'elle sentait 'le Portugal'.","p":"Le zeste d'orange était réputé tonique et stomachique, ouvrant l'appétit et secondant les digestions difficiles ; son amertume légère passait pour réveiller les humeurs lentes.","c":"Choisir des fruits non traités et bien colorés, ne prélever que le zeste sans l'écorce blanche, source d'âcreté. Un long séjour de l'écorce dans l'eau-de-vie sucrée donne une liqueur d'ambre dorée à servir en fin de repas.","d":"« Qui d'orange emplit sa fiole, du long hiver chasse la mélancole. »"},"rt-hypocras-a-la-vanille":{"h":"La vanille, gousse d'une orchidée grimpante, fut rapportée du Mexique par les conquérants qui la goûtèrent dans le chocolat des souverains aztèques. Longtemps capricieuse hors de son sol natal, faute de l'insecte qui la fécondait, elle demeura denrée rare et coûteuse, réservée aux desserts et aux vins des riches tables. Ajoutée à un hypocras, elle adoucit le vin d'une rondeur veloutée et chaude.","p":"On tenait la vanille pour cordiale et réconfortante, propre à ranimer les esprits et à entretenir une douce chaleur ; elle était réputée aussi favoriser une digestion paisible.","c":"Fendre la gousse dans sa longueur et en gratter les graines pour libérer tout l'arôme dans le vin chaud. Un vin rouge rond et fruité l'accueille mieux qu'un cru trop charpenté ; laisser infuser à couvert pour retenir les parfums.","d":"« Vanille au vin, soir de velours, fait le dormeur heureux toujours. »"},"rt-hypocras-a-la-violette":{"h":"La violette, fleur de la modestie chez les poètes, donnait aussi cet 'iris de Florence' dont la racine séchée, sentant la violette mûre, parfumait linges et breuvages. Toscane et Vénétie en faisaient grand commerce, et l'on en poudrait les hypocras pour leur prêter une nuance florale et une teinte mauve délicate. La fleur confite garnissait les dragées des banquets et les boîtes à épices de chambre.","p":"La violette et l'iris étaient réputés adoucir la gorge et la poitrine, et calmer les humeurs échauffées ; on leur prêtait une vertu apaisante propre à concilier le sommeil.","c":"L'iris de Florence ne livre son parfum qu'après un long séchage : préférer une poudre déjà mûrie. Doser d'une main légère, car l'arôme de violette tourne vite au savon s'il domine ; servir frais pour en goûter la finesse.","d":"« Au vin de violette, point ne sois prodigue : peu suffit pour qu'il intrigue. »"},"hy-hypocras-a-l-angelique":{"h":"L'angélique, dite herbe des anges ou herbe du Saint-Esprit, doit son nom à la réputation céleste de ses vertus protectrices durant les temps de peste. Les religieux la cultivaient en grand, et la ville de Niort en fit longtemps sa spécialité, confisant ses tiges vertes en bâtonnets sucrés. Ses graines et ses racines aromatisaient liqueurs et hypocras d'une saveur musquée et chaude.","p":"L'angélique était réputée souverainement stomachique et carminative, dissipant les vents et fortifiant les estomacs froids ; on la disait tonique des convalescents et amie des digestions lentes.","c":"Employer de préférence la tige fraîche, plus parfumée, et compléter d'un peu de plante confite pour la rondeur sucrée. Laisser reposer le vin plusieurs semaines avant de filtrer finement, car l'angélique livre lentement ses arômes les plus profonds.","d":"« Tige d'ange dans le flacon, met l'estomac à la raison. »"},"hy-hypocras-a-l-orange":{"h":"Frotter un morceau de sucre sur l'écorce d'une orange est un geste ancien des offices, qui charge le sucre des huiles parfumées du zeste sans en prendre l'amertume. On nommait ce sucre parfumé un 'oléo-saccharum', secret des limonadiers et des maîtres d'hôtel pour relever vins et punchs. Cette manière donnait à l'hypocras une fraîcheur d'agrume qui tempérait la chaleur des épices.","p":"L'orange et son zeste passaient pour stomachiques et cordiaux, propres à réjouir le cœur et à seconder l'appétit ; leur parfum était tenu pour dissiper les langueurs.","c":"Frotter le sucre vivement sur une orange non traitée jusqu'à ce qu'il s'imprègne et jaunisse, puis le faire fondre dans le vin. Servir l'hypocras légèrement frais pour que l'agrume demeure vif et que les épices ne couvrent pas le fruit.","d":"« Sucre frotté d'orange amère, rend l'hypocras léger et clair. »"},"hy-hypocras-au-cedrat":{"h":"Le cédrat, plus ancien des agrumes connus d'Occident, fut chéri des anciens pour son écorce épaisse et odorante plus que pour sa pulpe avare. Les jardins de Corse et de la Riviera en perpétuèrent la culture, et l'on en confisait l'écorce en friandises de garde. Son zeste, frotté au sucre, prêtait à l'hypocras une note citronnée noble et persistante.","p":"Le cédrat était réputé cordial et propre à raffermir l'estomac, et l'on prêtait jadis à son écorce une vertu préservatrice contre les airs corrompus ; on s'en servait pour rafraîchir l'haleine.","c":"Ne prélever que la fine pellicule jaune du zeste, l'écorce blanche du cédrat étant épaisse et amère. Frotter le sucre sur l'écorce pour en capter l'essence, puis le dissoudre dans un vin blanc franc servi bien frais.","d":"« Cédrat au vin, parfum d'antan, garde l'haleine au goût plaisant. »"},"hy-hypocras-aux-cerises":{"h":"La cerise, fruit de courte saison, fut de tout temps célébrée comme l'annonce des beaux jours ; on en faisait ratafias, guignolets et vins de fête pour prolonger l'été dans la cave. Le cerisier doux, dit-on rapporté d'Orient par les voies de Rome, essaima dans tous les vergers d'Europe. Mariée au vin rouge et à l'eau-de-vie, la cerise donne un hypocras vermeil et gourmand.","p":"La cerise était réputée rafraîchissante et propre à délayer les humeurs épaisses ; on prêtait à ses queues une vertu diurétique fort estimée des anciens.","c":"Choisir des cerises bien mûres et charnues, et ne pas écraser tous les noyaux, dont l'amande, en excès, communique une amertume et n'est pas sans danger. Laisser macérer quinze jours puis filtrer ; le repos affine la robe et adoucit l'eau-de-vie.","d":"« Cerise au vin quand vient l'été, garde au flacon sa gaieté. »"},"hy-hypocras-au-genievre":{"h":"Le genévrier, arbuste des landes et des garrigues, livre ces baies bleu-noir qui parfument tant l'eau-de-vie du Nord que les marinades de gibier. On brûlait ses rameaux dans les chambres des malades pour assainir l'air, et ses baies concassées entraient dans bien des cordiaux d'hiver. Au vin sucré, le genièvre prête une amertume résineuse et balsamique.","p":"Le genièvre était tenu pour diurétique et stomachique, réchauffant les reins et secondant les digestions pesantes ; on s'en servait aussi pour fortifier contre les froidures.","c":"Concasser légèrement les baies pour libérer leur huile sans broyer les graines, qui apporteraient trop d'âpreté. Doser avec mesure, car le genièvre domine vite ; un court repos suffit, suivi d'une filtration soignée.","d":"« Baie de genièvre au vin d'hiver, réchauffe l'homme et l'air amer. »"},"hy-hypocras-au-vin-d-absinthe":{"h":"L'absinthe, dite herbe sainte ou armoise amère, comptait parmi les plus vieux remèdes amers de l'herboristerie ; son nom même évoque ce qui se boit difficilement, tant sa saveur est âpre. Vermouts et vins toniques lui doivent leur fond amer, et les anciens en faisaient des macérations vermifuges. Au vin blanc, jointe à l'anis, elle donne un hypocras vert et puissant.","p":"L'absinthe était réputée souveraine pour réveiller l'appétit, fortifier l'estomac et chasser les vers. Mais elle renferme de la thuyone, principe redoutable à dose : on n'en usera qu'avec parcimonie, en breuvage rare et fort dilué.","c":"N'employer qu'une faible quantité de plante et écourter la macération, car l'amertume monte vite et tourne à l'âcre. Sucrer généreusement pour équilibrer, filtrer avec soin et servir en très petit verre, jamais à pleine rasade.","d":"« De l'absinthe au vin, goutte choisie : trop en prendre est folie. »"},"hy-hypocras-aux-epices-1":{"h":"La cannelle de Chine, ou cannelle casse, est l'écorce d'un arbre cousin du vrai cannelier, plus rude et plus poivrée que sa parente de Ceylan. Moins coûteuse, elle fut longtemps celle des cuisines populaires et des vins épicés de marché. Jointe à la muscade, elle compose le fond chaud et corsé qui fait reconnaître entre tous l'hypocras des banquets.","p":"La cannelle était réputée échauffante et stomachique, propre à réveiller les estomacs froids et à fortifier le ton ; la muscade passait pour cordiale et réconfortante des esprits.","c":"La cannelle casse étant plus forte que celle de Ceylan, en réduire la part pour ne pas masquer le vin. Râper la muscade au dernier moment et n'en mettre qu'une pincée ; laisser infuser à froid pour préserver la finesse des arômes.","d":"« Cannelle et muscade au fond du pot, font le vin chaud sans le fourneau. »"},"hy-hypocras-aux-epices-2":{"h":"Le gingembre, rhizome venu d'Asie par les caravanes, fut l'une des épices reines des cuisines anciennes, prisé pour son feu vif et sa fraîcheur poivrée. Associé à la cannelle, à la cardamome et au girofle, il forme l'âme de l'hypocras médiéval, que parfumait souvent une touche d'eau de rose. On le râpait frais pour en tirer toute la vivacité.","p":"Le gingembre était réputé échauffant et stomachique au plus haut point, dissipant les vents, réveillant l'appétit et secondant les digestions languissantes ; on le tenait pour tonique des humeurs froides.","c":"Râper le gingembre frais plutôt que d'user de poudre, pour une saveur plus nette et vive. Choisir un vin rouge peu tannique, et préférer le miel au sucre pour une rondeur plus médiévale ; goûter en cours d'infusion, le gingembre montant rapidement.","d":"« Gingembre râpé, cannelle et rose, en l'hypocras toute chaleur repose. »"},"hy-hypocras-aux-epices-3":{"h":"Le macis, fine résille écarlate qui enveloppe la noix de muscade, partage l'arbre du muscadier des îles aux épices ; on le tenait pour plus délicat que la noix qu'il coiffe. Joint à l'amande amère et à la vanille, il compose un hypocras d'une rare richesse aromatique, digne des tables les plus soignées. Le vin de Chablis, sec et minéral, en porte les épices avec netteté.","p":"Le macis et la muscade étaient réputés cordiaux et stomachiques. Mais l'amande amère, comme les noyaux, recèle un principe qui dégage de l'acide cyanhydrique : on n'en mettra qu'une pincée, car à forte dose elle devient un poison véritable.","c":"Ne broyer qu'une très faible quantité d'amandes amères, juste pour la note de noyau, sans jamais forcer la dose. Filtrer plusieurs fois sur étamine ou papier pour clarifier le vin chargé de poudres, et laisser reposer afin que les épices se fondent.","d":"« Macis et noyau, main légère : trop d'amande est chose amère. »"},"hy-hypocras-au-miel":{"h":"Le miel, premier des sucrants avant que la canne ne règne, donnait à l'hypocras médiéval sa douceur ronde et sa profondeur ambrée. Joint au galanga, ce rhizome asiatique cousin du gingembre que les anciennes apothicaireries nommaient 'garingal', et au curcuma doré, il compose un breuvage de fête aux résonances orientales. C'était là le luxe sucré des banquets, bien avant les sucres raffinés.","p":"Le miel était tenu pour adoucissant, pectoral et fortifiant, et le galanga passait pour échauffant et stomachique à l'égal du gingembre ; le curcuma, lui, était réputé ami du foie et des digestions lentes.","c":"Choisir un miel de caractère, sans qu'il domine les épices, et le délayer dans un peu de vin tiède pour qu'il se fonde aisément. Râper galanga et gingembre frais, doser le curcuma avec retenue car il colore et amertume vite, puis laisser reposer avant de filtrer.","d":"« Miel et galanga au vin doré, font l'hypocras des soirs sacrés. »"},"hy-hypocras-aux-noyaux":{"h":"Parmi les hypocras de table, celui dit 'aux noyaux' empruntait son parfum d'amande aux amandons des fruits à noyau, ces semences cachées que les officines nommaient parfois 'amères'. Le procédé prolonge la tradition médiévale du vin épicé filtré à la chausse, en y mariant le goût de noyau cher aux ratafias d'autrefois.","p":"On prêtait au vin de noyaux une vertu cordiale et stomachique, propre à 'réjouir le cœur' après les repas. Mais l'amande amère et les noyaux pilés recèlent un principe libérant de l'acide cyanhydrique : n'en user qu'à dose mesurée et bien filtrée, car l'excès passe pour pernicieux.","c":"Concasser les noyaux sans en abuser, et goûter avant de servir : un soupçon suffit à parfumer tout le flacon. Servir frais, en très petits verres, après quelques jours de repos au cellier.","d":"« Du noyau prends la senteur, jamais sa pleine vigueur. »"},"hy-hypocras-de-la-marquise":{"h":"L'hypocras fut longtemps le vin des cours et des dames de qualité, et nombre de recettes portent un nom de noblesse pour en marquer la richesse. Celle de 'la Marquise' multiplie les épices royales — coriandre, poivre, muscade, girofle — sur un lit de vin rouge, d'agrumes et de fruits, à la manière des vins d'hôtel servis aux fins de banquet.","p":"Cet assemblage d'aromates était tenu pour échauffant et propice à la digestion des viandes lourdes ; le romarin y passait pour fortifier l'esprit. La muscade râpée en grande quantité demande la retenue, car on la disait capable de troubler la tête.","c":"Choisir un vin rouge rond, ni trop tannique ni trop fin, qui supporte la charge des épices. Laisser infuser quelques jours, filtrer à la chausse de toile, puis goûter avant d'ajuster le sucre.","d":"« Vin de marquise, mainte épice : courte gorgée, longue délice. »"},"hy-hypocras-framboise":{"h":"L'hypocras framboisé marie le vin épicé d'antan à la framboise, ce fruit des ronces que les jardins de monastère cultivaient déjà pour ses sirops et ses ratafias. La baie, autrefois nommée 'frambeise', donne au vin une robe vive et un parfum de sous-bois qui adoucit la rudesse des épices.","p":"La framboise passait pour rafraîchissante et propre à tempérer les ardeurs ; mêlée au vin épicé, elle en corrigeait la chaleur. On la disait amie de l'estomac et bienvenue dans les boissons d'apparat.","c":"Préférer des framboises bien mûres et parfumées, écrasées juste avant la macération pour livrer tout leur jus. Filtrer soigneusement les fins pépins, et servir frais en accompagnement d'un entremets.","d":"« Framboise au vin, baiser des ronces, qui pique encore quand on s'enfonce. »"},"hy-hypocras-rouge-ou-blanc":{"h":"L'hypocras se déclinait au gré du vin disponible, rouge pour la table opulente, blanc pour la table claire, la cannelle restant l'âme commune des deux. Cette écorce roulée, venue des comptoirs d'Orient par les routes des épices, valait jadis son pesant d'argent et signait les vins de fête.","p":"La cannelle était réputée échauffante, stomachique et cordiale, propre à réveiller l'appétit et à réconforter par temps froid. On la tenait aussi pour aromate de longue garde, capable de préserver le vin de l'aigreur.","c":"Râper la cannelle plutôt que de la laisser en bâton si l'on veut un parfum prompt, mais filtrer alors avec soin pour ôter la poudre. Au vin blanc préférer un cru sec et fruité, au rouge un vin souple.","d":"« Rouge ou blanc, qu'importe au flacon : la cannelle y fait la chanson. »"},"hy-vin-d-amour-en-cage":{"h":"L''amour en cage' désigne le physalis, dont la baie dorée se cache sous un calice de papier ajouré, semblable à une lanterne. Son nom poétique lui vient de cette enveloppe qui emprisonne le fruit comme un cœur en sa cage, et l'on en fit des confitures et des vins de dame avant qu'il ne devînt curiosité de table.","p":"La baie de physalis, une fois mûre, était tenue pour rafraîchissante et favorable aux voies de l'eau, à la manière des fruits acidulés. On veillait toutefois à ne cueillir que les fruits bien mûrs, la plante verte passant pour rude à l'estomac.","c":"Ne retenir que les baies dorées et parfumées, débarrassées de leur lampion sec. Marier au vin blanc et au miel, laisser reposer en lieu frais, puis filtrer avant de servir bien frais.","d":"« Sous sa cage d'or dort l'amour : qui l'en délivre en boit le jour. »"},"hy-vin-d-artichaut":{"h":"L'artichaut, chardon domestiqué par les jardiniers d'Italie puis de France, fut longtemps réputé légume des grandes tables. De ses feuilles amères on tira des vins et apéritifs toniques, dans la lignée des amers d'autrefois où l'on cherchait dans l'amertume une vertu plutôt qu'un défaut.","p":"La feuille d'artichaut était réputée amie du foie et de la bile, et l'on prêtait à ses sucs amers une action dépurative et apéritive. On la prenait volontiers avant le repas pour 'ouvrir l'estomac'.","c":"Employer de préférence les feuilles et les tiges, plus amères que le cœur, cueillies sur des artichauts non montés en fleur. Sucrer avec mesure pour ne pas masquer l'amertume, qui fait tout le caractère du vin.","d":"« L'amer du chardon, sage leçon : santé au fond, plaisir au front. »"},"vn-jus-d-andouille-blanc":{"h":"Sous ce nom cocasse de 'jus d'andouille' se cache un vin de ménage parfumé au curaçao, c'est-à-dire à l'écorce d'orange amère des îles. Ces extraits d'arôme, dont la maison Noirot fit commerce dès le XIXe siècle, permettaient aux familles d'imiter à peu de frais les liqueurs d'orange des grandes distilleries.","p":"L'écorce d'orange amère qui donne son ton au curaçao était réputée tonique et stomachique, propre à relever l'appétit. Mêlée au vin blanc et aux agrumes, elle passait pour une boisson de table aimable et digestive.","c":"Doser l'extrait avec prudence, quelques gouttes suffisant à parfumer le vin. Trancher finement oranges et citrons, laisser macérer puis filtrer ; servir frais à l'apéritif.","d":"« Nom de ribaud, goût de seigneur : au flacon ne te fie qu'au cœur. »"},"vn-vermouth-blanc-a-la-camomille":{"h":"Le vermouth tire son nom de l'armoise — Wermut en parler germanique — plante amère qui en fait l'ossature ; ici la camomille en prend le relais pour un amer plus doux et fleuri. Cette fleur d'or des champs, vieille compagne des herboristes, parfumait depuis longtemps les vins de dame et les tisanes du soir.","p":"La camomille était réputée calmante et amie de l'estomac, propre à dénouer les digestions difficiles et à favoriser le repos. L'orange amère qui l'accompagne y ajoutait sa vertu apéritive et tonique.","c":"User de fleurs de camomille bien sèches et odorantes, en infusion brève pour éviter l'amertume excessive. Laisser reposer le vermouth quelques jours, filtrer, et servir frais avec un zeste d'orange.","d":"« Fleur de camomille au vin clair, endort la peine et le grand air. »"},"vn-vin-chaud-aux-epices":{"h":"Le vin chaud épicé descend en droite ligne de l'hypocras médiéval, dont il garde la cannelle, le girofle et la muscade, mais qu'il sert fumant au lieu de filtré à froid. Boisson des veillées d'hiver et des marchés de décembre, il réunit autour de l'âtre les épices que les marchands rapportaient jadis d'Orient.","p":"Ce cortège d'aromates était tenu pour échauffant et réconfortant, propre à chasser le froid et à fortifier les voyageurs. La muscade et le poivre, donnés à forte main, demandent la mesure, l'excès de noix muscade passant pour étourdir.","c":"Chauffer le vin sans jamais le faire bouillir, sous peine d'en évaporer l'esprit et d'aigrir les épices. Infuser cannelle, girofle et badiane le temps d'un quart d'heure, sucrer en fin de course et servir brûlant.","d":"« Vin qui fume au cœur de l'hiver, vaut manteau doublé de vair. »"},"vn-vin-chaud-traditionnel":{"h":"Le vin chaud traditionnel, sobre en épices, se contente de cannelle, d'anis étoilé et d'agrumes pour réchauffer les soirées de gel. Boisson populaire des foires d'hiver, il perpétue l'usage ancien de bonifier un vin modeste par le feu, le sucre et le parfum des écorces.","p":"On lui prêtait la vertu de réchauffer le sang et de prévenir les refroidissements, d'où sa faveur aux veillées de décembre. L'orange et le citron y apportaient leur fraîcheur tonique, tempérant la chaleur du breuvage.","c":"Choisir un vin rouge honnête et fruité, qu'on chauffe doucement sans ébullition. Glisser un zeste plutôt que le fruit entier pour éviter l'amertume des écorces blanches, et servir sans attendre.","d":"« Au gel de décembre, point de remède : un verre fumant, et le froid cède. »"},"vn-vin-d-ecorce-de-bouleau":{"h":"Le bouleau, arbre des terres du Nord, fournissait jadis sa sève au printemps et son écorce argentée aux remèdes des bois. Les peuples forestiers en tiraient des boissons et des vins fortifiants, l'arbre passant pour celui des renouveaux tant sa sève montait dès la fin de l'hiver.","p":"L'écorce et la sève de bouleau étaient réputées dépuratives et amies des reins, propres à 'laver' l'humeur et à soulager les articulations. On en faisait des cures de printemps, dans l'esprit des vins de santé d'autrefois.","c":"Prélever l'écorce sur de jeunes rameaux, fine et claire, sans blesser l'arbre. La marier au vin rouge et au miel, laisser macérer plusieurs semaines au frais, puis filtrer avec soin.","d":"« Au bouleau d'avril prends ta part : santé qui monte avec la sève claire. »"},"vn-vin-a-la-reine-des-pres":{"h":"La reine des prés, ou filipendule, dresse ses plumets crème au bord des fossés humides et embaume l'amande et le miel. Les herboristes la nommaient 'spirée', et c'est de ce nom que la chimie tira plus tard le mot d'un célèbre remède, tant la plante recèle de ces principes calmant la douleur.","p":"On la tenait pour amie des fièvres et des douleurs, ainsi que pour favoriser les voies de l'eau, d'où sa réputation contre les rhumatismes. Riche en principes salicylés, elle était à déconseiller à qui supporte mal ces substances ; un usage modéré s'imposait.","c":"Cueillir les fleurs par temps sec, en plein épanouissement, et les employer fraîches ou bien séchées à l'ombre. Une infusion courte dans le vin blanc suffit, car une chaleur trop vive dissipe son parfum d'amande.","d":"« Reine des prés au pied mouillé, calme la fièvre du faucheur lassé. »"},"vn-vin-a-l-angelique":{"h":"L'angélique, haute ombellifère des jardins de monastère, fut surnommée 'herbe des anges' pour la réputation salutaire de sa racine. Cultivée de longue date dans les cloîtres, notamment en Poitou, elle parfumait confiseries, liqueurs et vins de santé de son arôme musqué et résineux.","p":"La racine et les feuilles d'angélique étaient réputées toniques, stomachiques et carminatives, propres à réconforter et à dissiper les vents. Sa sève contient toutefois des principes qui rendent la peau sensible au soleil : on évitait d'en abuser et de s'exposer après en avoir pris.","c":"Employer racines et feuilles bien parfumées, hachées menu pour livrer leur arôme au vin blanc. Laisser macérer plusieurs semaines, sucrer modérément et servir frais en digestif.","d":"« Herbe des anges au flacon close, garde le souffle et le repose. »"},"vn-vin-a-l-ananas":{"h":"L'ananas, fruit des terres chaudes du Nouveau Monde, fit longtemps figure de trésor exotique sur les tables d'Europe, où l'on bâtit des serres entières pour le faire mûrir. Sa chair dorée et sucrée passait pour un mets de prince, et l'on en parfumait volontiers vins et ratafias de fantaisie.","p":"On prêtait à l'ananas mûr une vertu rafraîchissante et propre à aider la digestion des repas lourds, sa chair renfermant un ferment qui 'attendrit' les viandes. On le tenait pour fruit aimable à l'estomac quand on le prenait bien mûr.","c":"Choisir un ananas parfumé, lourd et cédant sous le doigt, dont la chair embaume jusqu'au cœur. Le détailler en dés, marier au vin blanc et à l'eau-de-vie, laisser reposer puis filtrer et servir frais.","d":"« Pomme de pin des îles d'or, au vin clair donne son trésor. »"},"vn-vin-de-basilic":{"h":"Le basilic, dont le nom dérive du grec 'basilikon', l'herbe royale, fut longtemps tenu pour une plante de cour et de cérémonie, réservée aux préparations nobles. Venu de l'Inde par les routes du Levant, il prit place dans les jardins de cloître où l'on cultivait ce que l'on nommait alors les herbes odorantes. On lui prêtait de chasser la mélancolie et d'égayer l'esprit de qui le respirait.","p":"Ses feuilles parfumées étaient réputées soutenir l'estomac et dissiper les pesanteurs après les repas trop riches ; on en faisait volontiers un vin de table pour ouvrir l'appétit.","c":"Cueillir le basilic avant la floraison, par temps sec, et le froisser doucement plutôt que le hacher pour ne pas brunir l'infusion ; servir frais, mais non glacé, afin de garder le parfum vif.","d":"« Basilic au verre versé, soucis du jour ont trépassé. »"},"vn-vin-de-bleuet":{"h":"Le bleuet, ce 'casse-lunettes' des moissons, colorait jadis les champs de blé de sa teinte d'azur avant que l'on ne s'acharnât à l'en bannir. Son nom dit assez la couleur qui faisait sa renommée, recherchée des teinturiers comme des enlumineurs. Fleur des chemins et des bordures, il s'invitait aux bouquets champêtres autant qu'aux remèdes de bonne femme.","p":"L'eau distillée de ses fleurs était traditionnellement employée en lotion pour rafraîchir les yeux fatigués, d'où son surnom ; en vin, on le tenait pour une boisson légère et apaisante.","c":"Ne retenir que les pétales bien bleus, débarrassés du cœur vert qui amertumerait la macération ; filtrer avec soin sur une gaze fine pour obtenir une robe limpide.","d":"« Au bleuet des blés mûrs, l'œil se repose et le cœur s'épure. »"},"vn-vin-au-cresson":{"h":"Le cresson de fontaine, qui pousse au fil clair des sources et des ruisseaux, fut de tout temps une herbe de santé prisée des gens des campagnes. Les marins l'emportaient autrefois pour se prémunir des maux du long bord, et les herboristes le rangeaient parmi les plantes dépuratives du printemps. Sa saveur poivrée et fraîche en faisait une cure de saison autant qu'un agrément de table.","p":"On le disait dépuratif et fortifiant, propre à purifier le sang à la sortie de l'hiver et à redonner de la vigueur aux convalescents. On le cueillera toutefois en eau saine, car le cresson sauvage peut héberger les parasites des prés humides.","c":"Choisir un cresson d'eau courante et bien le rincer ; une macération courte suffit, car une infusion trop longue tourne à l'âcre et à l'herbacé.","d":"« Cresson de source au vin mêlé, rend au sang sa pureté. »"},"vn-vin-a-l-orange-amere":{"h":"L'orange amère, ou bigarade, fut la première des oranges à gagner l'Occident par les jardins maures d'Espagne et de Sicile, bien avant sa cousine douce. Son écorce parfumée et son amertume franche en firent l'âme des apéritifs et des liqueurs de ménage. On la suspendait piquée de girofle pour embaumer les armoires autant que pour parfumer le vin.","p":"L'amer de son zeste était réputé tonifier l'estomac et appeler l'appétit, vertu pour laquelle on en faisait un vin d'avant-repas fort estimé.","c":"Préférer des bigarades non traitées et ne prélever que le zeste, en laissant le ziste blanc qui apporterait une amertume rêche ; un repos de quelques semaines arrondit l'âpreté première.","d":"« L'amère bigarade en son rosé, met la faim sur le pavé. »"},"vn-vin-de-quinquina-blanc":{"h":"Le quinquina, écorce d'un arbre des Andes, parvint en Europe par les voies du Nouveau Monde et fit longtemps figure de remède souverain contre les fièvres. Son amertume profonde devint la signature des vins toniques et des apéritifs dits 'de quinquina', dont la mode gagna toutes les tables. On le mariait à l'orange amère et aux amandes pour en adoucir la rudesse.","p":"Son écorce était tenue pour fébrifuge et pour un puissant stimulant de l'appétit, d'où l'usage de ces vins avant le repas. Les amandes amères qui l'accompagnent recèlent un principe qui devient nocif à forte dose : on les emploiera avec mesure.","c":"Doser le quinquina d'une main légère, car son amer domine vite ; filtrer après macération et laisser reposer en bouteille pour que les arômes se fondent. Servir frais, en petite quantité.","d":"« Qui d'écorce andine sait user, voit l'appétit se réveiller. »"},"vn-vin-rose-au-quinquina":{"h":"Marié ici à la gentiane des montagnes, le quinquina compose l'un de ces vins amers que l'on tenait pour le meilleur des avant-repas. La gentiane jaune, dont on arrache la longue racine sur les pâturages d'altitude, partage avec l'écorce andine cette amertume noble qui ouvre l'estomac. L'alliance des deux amers fut chère aux distillateurs de jadis comme aux montagnards.","p":"Gentiane et quinquina passaient l'un et l'autre pour de remarquables apéritifs et toniques, propres à fortifier les digestions paresseuses. Leur amertume étant vive, on en usera par petits verres.","c":"Concasser la racine de gentiane plutôt que de la réduire en poudre, pour une extraction plus nette ; goûter en cours de macération afin d'arrêter l'amer au juste point. Une pointe de muscade lie agréablement le tout.","d":"« Gentiane et quinquina dans le rosé, font la table mieux apprêtée. »"},"vn-vin-blanc-de-fraises":{"h":"La fraise des jardins, longtemps cantonnée à la menue fraise des bois, ne prit son ampleur qu'avec les variétés rapportées des Amériques et croisées dans les potagers d'Europe. On la disait fruit de Vénus pour sa forme et son parfum, et les dames de cour en raffolaient au vin. Mariée au vin blanc, elle donnait une boisson de printemps légère et colorée.","p":"On prêtait à la fraise des vertus rafraîchissantes et propres à apaiser les ardeurs ; en vin léger, elle passait pour une douceur de saison plus agréable que médicinale.","c":"Choisir des fraises bien mûres et parfumées, équeutées au dernier moment ; macérer brièvement et filtrer sur gaze pour garder une robe claire. Boire jeune, car ce vin ne se garde guère.","d":"« Fraise au vin clair de la prime saison, dure le temps d'une chanson. »"},"vn-vin-aux-fraises-et-au-vin-rouge":{"h":"Marier la fraise au vin rouge est un usage ancien des vendanges, où l'on noyait les derniers fruits de l'été dans le moût nouveau. Le rouge profond exalte la fraise mieux que le blanc et lui prête une rondeur veloutée. Ces vins de fruits, faits au foyer, accompagnaient les veillées et les desserts champêtres.","p":"La fraise, fruit doux et juteux, était tenue pour rafraîchissante et de digestion aisée ; relevée de vanille, elle composait un vin de plaisir plus que de remède.","c":"Prendre un rouge souple et fruité, sans excès de tanin, qui n'écrase pas le fruit ; la vanille demande à infuser un peu plus longtemps que la fraise. Servir frais en fin de repas.","d":"« Fraise et vin rouge en bonne union, font le velours de la maison. »"},"vn-vin-de-menthe-fraiche":{"h":"La menthe, dont les anciens contaient qu'elle naquit d'une nymphe métamorphosée, parfume les jardins et les tables depuis la plus haute Antiquité. Son nom même chante la fraîcheur, et on la jetait jadis sur le sol des salles pour embaumer l'air des banquets. Herbe de tous les climats, elle se prête aux sirops comme aux vins d'été.","p":"La menthe était réputée faciliter la digestion et rafraîchir l'haleine ; en vin, on la buvait pour sa fraîcheur autant que pour ses vertus stomachiques.","c":"Cueillir la menthe juste avant la floraison, quand l'huile est la plus parfumée, et ne pas trop prolonger la macération qui virerait à l'amer ; servir bien frais, par temps de chaleur.","d":"« Menthe au verre par grande chaleur, est baume au gosier et au cœur. »"},"vn-vin-de-myrtille":{"h":"La myrtille, baie des landes et des sous-bois de montagne, fut longtemps cueillie au peigne de bois par les gens des hauteurs. Sa teinte profonde tachait les doigts et les langues, et l'on en tirait autrefois une couleur autant qu'un fruit. Les bergers en faisaient des conserves et des vins pour les longs hivers.","p":"On lui prêtait des vertus astringentes et fortifiantes, et la tradition la disait amie de la vue et du sang ; en vin, elle composait une boisson colorée et roborative.","c":"Choisir des myrtilles sauvages bien mûres, plus parfumées que les cultivées ; écraser légèrement les baies avant macération pour libérer le jus, puis filtrer avec soin. Un repos prolongé approfondit la couleur.","d":"« Myrtille des monts au vin coulée, teint le verre et l'année. »"},"vn-vin-aux-pruneaux":{"h":"Le pruneau, prune séchée au four ou au soleil, fut de longue date une provision d'hiver chère aux campagnes, et les pays d'Agen en firent une renommée. Sa chair confite et son parfum de fruit cuit en faisaient un trésor de garde-manger. Macéré dans le vin et l'eau-de-vie, il donnait un cordial épais et réconfortant pour la saison froide.","p":"Le pruneau passait pour adoucir et régulariser le ventre, vertu bien connue des aïeules ; relevé de vanille et d'armagnac, il composait un vin chaleureux que l'on buvait à la veillée.","c":"Garder les noyaux durant la macération pour un léger goût d'amande, sans en abuser ; choisir des pruneaux moelleux et un rouge corsé qui en soutienne la richesse. Servir à température de cave.","d":"« Pruneau au vin par la froidure, donne au corps bonne tournure. »"},"vn-vin-de-sauge":{"h":"La sauge, dont le nom latin évoque le salut et la guérison, fut l'herbe médicinale par excellence des jardins de monastère. Un vieil adage demandait pourquoi mourrait l'homme qui a de la sauge en son jardin, tant on la croyait souveraine. On en faisait des vins et des élixirs tenus pour préserver de bien des maux.","p":"La sauge était réputée tonique, digestive et propre à fortifier les nerfs et la mémoire ; on la buvait en vin pour se réchauffer et se raffermir. Très concentrée, elle ne convient pas aux femmes qui allaitent et veut être employée avec retenue.","c":"User des feuilles avec mesure, car la sauge domine vite et tourne au camphré ; une macération brève suffit à en tirer l'arôme. Servir frais, en petit verre d'avant-repas.","d":"« Sauge au jardin, sauge au flacon, gardent l'humeur et la raison. »"},"vn-vin-de-sureau":{"h":"Le sureau noir, arbre des haies et des bords de chemin, tient une grande place dans les croyances populaires, où on le disait protecteur du foyer. Ses ombelles de fleurs blanches puis ses grappes de baies noires servaient aux sirops, aux gelées et aux vins de ménage. On respectait l'arbre au point de le saluer avant d'y prélever ses fruits.","p":"Les baies mûres et cuites étaient tenues pour sudorifiques et propres à soutenir les refroidissements ; mais crues, elles échauffent le ventre et veulent toujours être employées bien mûres et chauffées, car elles sont autrement indigestes.","c":"Ne récolter que des baies parfaitement noires et mûres, jamais vertes ni rougeâtres, et les passer par la chaleur ; égrapper soigneusement, car les rafles donnent de l'amertume. Filtrer sur gaze.","d":"« Du sureau ne prends que le mûr, sinon le ventre en pâtit dur. »"},"vn-vin-blanc-aux-pamplemousses":{"h":"Le pamplemousse, dernier venu des grands agrumes, naquit aux Antilles du croisement fortuit d'arbres importés des tropiques de l'Ancien Monde. Son fruit généreux, amer et juteux à la fois, conquit les vergers chauds et les tables d'été. Plus moderne que ses cousins, il s'est taillé une place de choix dans les apéritifs frais et parfumés.","p":"Sa chair acidulée passait pour rafraîchissante et propre à réveiller l'appétit ; en vin léger, on le buvait surtout pour sa vivacité désaltérante.","c":"Choisir des pamplemousses bien mûrs et lourds, à la peau parfumée, et ne prélever du zeste que la partie colorée pour éviter l'amertume ; servir très frais, à l'heure de l'apéritif.","d":"« Pamplemousse au vin de l'été, désaltère qui a peiné. »"},"vn-vin-d-abricots":{"h":"L'abricotier, venu de Chine par la route de la soie puis acclimaté dans les vergers de Perse et d'Arménie, gagna le bassin méditerranéen où son fruit doré devint l'emblème des étés brefs. Son nom français descend, par l'arabe 'al-barqûq' et l'espagnol, du latin 'praecoquum', le « fruit précoce » qui mûrit avant les autres. On le mettait au vin pour prolonger en bouteille la douceur fugace de juillet.","p":"La chair de l'abricot était réputée nourrir et adoucir les humeurs, tandis que le vin macéré passait pour un cordial réconfortant les convalescents. On se gardait toutefois d'écraser les amandes de ses noyaux, tenues pour amères et dangereuses à dose.","c":"Choisir des abricots bien mûrs et parfumés, presque fondants, car un fruit acide donnera un vin maigre ; un bâton de cannelle suffit à relever sans masquer. Servir frais, après quelques semaines de repos en cave obscure.","d":"« Abricot cueilli à point, fait au vin le plus doux des liens. »"},"vn-vin-d-amande-amere":{"h":"L'amande amère, fruit d'une variété du même amandier que l'amande douce, fut de tout temps prisée des confiseurs et des parfumeurs pour son arôme puissant rappelant la cerise et le noyau. Les anciens en tiraient une essence dont une goutte suffisait à embaumer tout un flacon. Son parfum capiteux signait jadis les ratafias et les vins d'office des grandes maisons.","p":"On lui prêtait des vertus apéritives et le pouvoir d'éveiller l'appétit par son amertume franche. Mais l'amande amère et son huile essentielle renferment un principe qui se mue en acide cyanhydrique : on n'en use qu'à dose infime, quelques gouttes comptées, jamais davantage.","c":"Verser l'huile essentielle au compte-gouttes et goûter avec prudence, car l'arôme domine vite tout l'assemblage. Laisser reposer plusieurs semaines pour que la vanille arrondisse l'amertume, puis servir en tout petit verre.","d":"« De l'amande amère un soupçon ; qui force la dose en perd la raison. »"},"vn-vin-d-aneth":{"h":"L'aneth, ombellifère gracile des potagers d'autrefois, accompagne les hommes depuis les jardins de l'Égypte et de la Grèce, où l'on mâchait ses graines pour rafraîchir l'haleine. Son nom remonte au grec 'anethon', et les herboristes du Moyen Âge le confondaient volontiers avec le fenouil, son proche cousin. On en parfumait les vins de table pour aider à digérer les festins gras.","p":"Les graines d'aneth étaient réputées carminatives, apaisant les ballonnements et favorisant une digestion paisible après le repas. Mariées à l'anis étoilé, elles donnaient un vin que l'on tenait pour amical à l'estomac.","c":"Concasser légèrement les graines pour libérer leurs huiles avant de les jeter au vin, et n'en pas abuser sous peine d'amertume. Filtrer finement après macération, puis servir frais en fin de repas.","d":"« Graine d'aneth au fond du verre, allège la panse et désaltère. »"},"vn-vin-de-brugnons":{"h":"Le brugnon, cousin à peau lisse de la pêche, naît du même arbre capricieux que cultivaient déjà les vergers de Perse avant de gagner Rome. Glabre là où la pêche se couvre de duvet, il porte une chair ferme et sucrée que les anciens jugeaient plus noble en bouteille. Son nom vient de l'occitan 'brugnoun', petite prune, tant le fruit évoque par sa robe les drupes de verger.","p":"La chair du brugnon passait pour rafraîchissante et propre à tempérer les ardeurs de l'été. On évitait toutefois de mettre ses noyaux à macérer, leurs amandes recelant le même principe amer et redoutable que celles de l'abricot.","c":"Préférer des brugnons fermes mais parfumés, dénoyautés avec soin, pour un vin net et fruité. Une gousse de vanille suffit à enrober la chair ; laisser reposer trois à quatre semaines avant de servir bien frais.","d":"« Brugnon sans duvet, vin sans défaut, qui le boit l'été se porte au plus haut. »"},"vn-vin-de-bruyere":{"h":"La bruyère, humble arbrisseau des landes et des sous-bois acides, teinte de mauve les coteaux pauvres où peu d'autres plantes prospèrent. Les abeilles en tirent un miel sombre et corsé qui fit la réputation des terres de bruyère, et l'on coupait ses tiges pour en faire balais et litières. Ses fleurs séchées entraient dans les vins de campagne, mariées aux baies de la garrigue.","p":"On prêtait à la fleur de bruyère des vertus diurétiques et apaisantes pour les voies basses, et les baies de genièvre y ajoutaient leur réputation tonique et digestive. Le tout composait un vin que l'on disait ami des reins et de l'estomac.","c":"Récolter les fleurs en pleine floraison, bien ouvertes et sèches, et n'écraser que légèrement les baies de genièvre pour ne pas durcir le breuvage. Filtrer avec patience, car la fleur retient le trouble ; servir frais.","d":"« Fleur de lande au fond du tonneau, garde le sang clair et l'esprit haut. »"},"vn-vin-de-camomille-au-vin-blanc":{"h":"La camomille, petite marguerite odorante des chemins, doit son nom au grec 'khamaimêlon', la « pomme à terre », pour le parfum de pomme mûre que dégagent ses fleurs froissées. Les anciens herboristes la cueillaient avec révérence et la nommaient parfois plante des médecins, tant on la croyait capable de soigner ses voisines au jardin. Mariée à un vin blanc sec, elle donnait un breuvage clair et apaisant pour les fins de soirée.","p":"La camomille était réputée calmer les nerfs, adoucir les digestions difficiles et favoriser un sommeil tranquille. Le vin qui en recueillait l'arôme passait pour un doux réconfort du soir, sans rudesse.","c":"N'employer que les capitules secs et dorés, en quantité mesurée, car une infusion trop chargée vire à l'amertume. Une touche de rhum agricole soutient le bouquet ; servir bien frais, en petite quantité avant le coucher.","d":"« Camomille au vin blanc le soir, berce les songes sans le savoir. »"},"vn-vin-de-camomille-au-vin-rouge":{"h":"Si la camomille parfume volontiers les vins blancs, les vignerons de jadis l'unissaient aussi au vin rouge pour en tirer un cordial plus charpenté. Cette même fleur des champs, que l'on faisait sécher en bouquets suspendus aux poutres, traversait l'hiver dans les armoires des ménagères. Plongée dans un rouge léger, elle troquait sa délicatesse contre une rondeur plus rustique.","p":"On lui reconnaissait les mêmes vertus apaisantes et digestives qu'à son frère blanc, mais le vin rouge la rendait, disait-on, plus tonique et mieux faite pour réchauffer. C'était le remède du soir des veillées d'automne.","c":"Choisir un rouge souple et peu tannique, qui n'écrase pas la fleur, et doser la camomille avec retenue. Sucrer modérément, filtrer après quelques semaines, puis laisser le vin se faire encore en bouteille.","d":"« Camomille en robe vermeille, réchauffe le cœur et tient l'œil en éveil. »"},"vn-vin-de-camomille-au-vin-rouge-et-aux-epices":{"h":"Voici la camomille parée pour les grands soirs, mêlée à la cannelle, au macis et à l'orange amère comme dans les hypocras d'autrefois. Cette alliance de la fleur des prés et des épices de chambre rappelle les vins d'office que l'on servait après les banquets, à l'heure des confitures sèches. L'orange amère, ou bigarade, y apporte le mordant que recherchaient les palais médiévaux.","p":"Aux vertus calmantes et digestives de la camomille s'ajoutaient celles, réchauffantes et stomachiques, des épices royales ; le macis et l'orange amère étaient tenus pour réveiller l'appétit. On le buvait l'hiver, comme un baume contre les frimas.","c":"Ne mettre qu'un demi-bâton de cannelle et un peu de macis, afin que l'épice escorte la fleur sans la couvrir. Le zeste d'orange amère se prélève sans le blanc, amer à l'excès ; laisser reposer puis filtrer soigneusement.","d":"« Fleur et épice au même verre, font d'un hiver une douce affaire. »"},"vn-vin-de-cannelle":{"h":"La cannelle, écorce roulée d'un arbre de Ceylan, fut l'une des épices les plus convoitées du monde ancien, si précieuse qu'on l'offrait aux dieux et aux rois. Les marchands en taisaient l'origine pour en garder le monopole, l'entourant de récits fabuleux propres à faire grimper les prix. Unie au quinquina dans un vin doux, elle composait un apéritif de pharmacie autant que de plaisir.","p":"La cannelle était réputée cordiale, réchauffante et propice à la digestion, tandis que l'écorce de quinquina, fébrifuge célèbre, prêtait au vin son amertume tonique et apéritive. Ce mariage en faisait un vin de santé que l'on prenait à petites doses.","c":"Préférer une cannelle de Ceylan, fine et claire, à la casse plus rude, et ne laisser le quinquina infuser que le temps voulu, car son amertume gagne vite. Filtrer avec soin, puis servir frais comme apéritif.","d":"« Cannelle et quinquina au verre, ouvrent l'appétit, ferment l'hiver. »"},"vn-vin-de-cartagene":{"h":"La cartagène, mistelle née des coteaux du Languedoc, se fait en arrêtant le moût de raisin par l'alcool avant que le sucre ne fermente, selon une vieille tradition des vignerons du Midi. Chaque famille gardait jalousement sa proportion, transmise de père en fils, pour le vin que l'on offrait aux hôtes de marque. Son nom évoquerait la lointaine Carthagène, port d'où venaient jadis les vins doux.","p":"Liquoreuse et chaleureuse, la cartagène passait pour un cordial réconfortant, à prendre en digestif après les repas de fête. On la tenait pour amie des estomacs lourds, mais sa richesse en sucre et en alcool invitait à la modération.","c":"Choisir un moût de raisin bien mûr et sucré, et veiller à un mutage franc pour figer la douceur naturelle. Laisser vieillir longuement en bonbonne, à l'abri de la lumière, puis servir frais sur un dessert ou une pâtisserie.","d":"« Cartagène en fin de festin, fait du dîner un doux matin. »"},"vn-vin-de-cassis-1":{"h":"Le cassis, baie noire et musquée du groseillier des Vosges et de Bourgogne, fut longtemps cultivé pour ses feuilles autant que pour ses fruits, l'arbuste passant pour une véritable petite pharmacie de jardin. Un ancien traité vantait jadis ses vertus au point qu'on l'eût cru capable de guérir tous les maux. De cette réputation naquirent ratafias, crèmes et vins de cassis, gloire des celliers du centre de la France.","p":"La baie de cassis était réputée tonique et fortifiante, et l'on prêtait à ses feuilles des vertus contre les douleurs des articulations. Le vin qui en tirait la couleur sombre passait pour un reconstituant des plus agréables.","c":"Cueillir les grappes bien mûres et égrener avec soin, en gardant le poids des fruits en jus pour mesurer le sucre. Un vin rouge corsé soutient la baie ; laisser macérer longuement puis filtrer pour une robe profonde et nette.","d":"« Cassis dans le verre vermeil, donne au bras force et à l'œil son réveil. »"},"vn-vin-de-cassis-2":{"h":"Cette seconde manière de vin de cassis fait jouer le fruit avec un trait de cognac ou d'armagnac, ces eaux-de-vie nobles du Sud-Ouest qui prolongent la macération. Là où la première recette s'en tient à l'alcool blanc, celle-ci emprunte aux fines des chais leur rondeur boisée. C'est le vin de cassis des bonnes maisons, où l'on ne lésine pas sur la qualité de l'esprit-de-vin.","p":"Le cassis y conservait sa réputation de baie fortifiante et tonique, rehaussée par la chaleur réconfortante de l'eau-de-vie vieillie. On le réservait aux digestifs, à prendre en petite mesure pour clore un bon repas.","c":"Mesurer l'eau-de-vie par litre de jus pour garder l'équilibre, et choisir un cognac ou un armagnac assez souple pour ne pas masquer le fruit. Laisser reposer plusieurs mois afin que les saveurs se fondent avant de mettre en bouteille.","d":"« Cassis marié à la fine, fait un digestif qui domine. »"},"vn-vin-de-cerises-1":{"h":"Voici un vin de cerises pris à contre-saison, alors que les fruits sont encore verts et fermes, selon une coutume rustique qui tirait parti de la rigueur du fruit. Le cerisier, venu dit-on des rivages du Pont par les vergers de Rome, donna son nom à la ville de Cérasonte autant qu'au fruit. Relevé de kirsch, ce vin de cerises vertes gardait une fraîcheur acidulée que recherchaient les amateurs.","p":"La cerise était réputée rafraîchissante et bénéfique aux humeurs, et le kirsch ajoutait sa note de noyau qui passait pour stimuler la digestion. On tenait ce vin vert pour apéritif plutôt que pour douceur de fin de repas.","c":"Choisir des cerises bien vertes et fermes, qui tiennent à la macération sans se déliter, et sucrer avec mesure pour respecter l'acidité voulue. Le kirsch se verse en petite quantité ; filtrer net et servir frais.","d":"« Cerise verte au vin jetée, donne à la table sa gaieté. »"},"vn-vin-de-cerises-2":{"h":"Cette seconde façon préfère la cerise noire, mûre et charnue, à la verte de la recette précédente, pour un vin plus généreux et coloré. Les vins de cerises noires étaient la fierté des vergers d'Alsace et de Franche-Comté, où l'on faisait aussi le kirsch. On les laissait longtemps en bonbonne, jusqu'à ce que le fruit eût rendu toute sa robe sombre au vin.","p":"La cerise noire passait pour adoucir les humeurs et réjouir le cœur par sa douceur sucrée. On évitait néanmoins d'écraser les noyaux dans la masse, leurs amandes recelant ce principe amer qu'il ne faut goûter qu'avec retenue.","c":"Préférer des cerises noires bien mûres et juteuses, équeutées mais laissées entières, pour que le vin se charge lentement de couleur. Laisser reposer plusieurs mois à l'abri de la lumière, puis filtrer et servir frais sur un dessert.","d":"« Cerise noire en robe de nuit, fait le vin sombre et l'âme réjouie. »"},"vn-vin-de-feuilles-de-cerisier":{"h":"Le vin de feuilles de cerisier appartient à la longue tradition des vins de feuilles, où l'on faisait macérer le feuillage des arbres fruitiers plutôt que leur chair, plus précieuse. Les feuilles cueillies après la chute des fruits, lorsqu'elles rougissent, libèrent un parfum d'amande et de noyau dû aux mêmes composés qui embaument le kirsch. On en garnissait jadis les caves de campagne pour tirer parti d'un arbre déjà dépouillé de ses cerises.","p":"Les feuilles de cerisier passaient pour favoriser la digestion et apaiser les humeurs ; on les disait toniques et rafraîchissantes. On les choisira saines et non flétries, car le parfum d'amande qu'elles dégagent procède de composés à manier avec mesure.","c":"Récolter les feuilles bien colorées, à l'automne, après les premières fraîcheurs. Filtrer soigneusement après macération et servir frais, en apéritif, dans de petits verres.","d":"« Quand la feuille a rougi sur l'arbre dénudé, le cerisier encore au verre s'est donné. »"},"vn-vin-de-chicoree":{"h":"La chicorée, longtemps cultivée pour ses racines torréfiées en succédané du café, fut aussi prisée pour son amertume franche en apéritif. Son nom remonte au grec kikhorion, et les anciens herbiers la rangeaient parmi les plantes dites « amères » destinées à éveiller l'appétit. Le grain torréfié donne au vin une couleur sombre et une saveur de café boisé fort recherchée dans les campagnes du Nord.","p":"La chicorée était réputée stimuler l'appétit, soutenir le foie et faciliter la digestion par son amertume. On la tenait pour dépurative et rafraîchissante des entrailles.","c":"Doser le grain de chicorée avec prudence, car son amertume domine vite l'ensemble. Laisser reposer le vin quelques semaines en bouteille pour que l'âpreté s'arrondisse, puis servir frais.","d":"« À l'amer du grain torréfié, l'estomac paresseux est réveillé. »"},"vn-vin-de-coing":{"h":"Le coing, fruit de Cydonie dont les Anciens faisaient le « melimelon », était dédié aux noces et offert en gage de bonheur conjugal. Trop âpre pour être croqué cru, il révèle au contraire dans le vin et la liqueur un arôme floral et miellé d'une rare finesse. On le conservait dans les armoires à linge pour son parfum tenace, et dans les celliers pour ses préparations dorées.","p":"Le coing était réputé astringent et fortifiant de l'estomac ; on le tenait pour un remède des dévoiements et un cordial des convalescents. Sa pulpe cuite passait pour resserrer les tissus relâchés.","c":"Choisir des coings bien mûrs, jaunes et odorants, et les essuyer de leur duvet avant emploi. Filtrer avec patience, car la pulpe trouble longtemps le vin ; le repos en cave clarifie peu à peu la robe.","d":"« Coing au cellier, parfum d'antan ; au verre il se fait cordial galant. »"},"vn-vin-de-lectoure":{"h":"Le vin de Lectoure, du nom de la cité gasconne, marie l'orange à l'armagnac dans la manière des vins d'orange du Sud-Ouest, préparés à la fin de l'hiver lorsque les agrumes abondent. C'est une boisson de gardois et de gens du pays armagnacais, qui tiraient parti de leur fine eau-de-vie pour fixer le parfum des zestes. L'orange amère, surtout, y apporte une amertume noble héritée des recettes des cabinets d'apothicaires.","p":"Le zeste d'orange était réputé stomachique et cordial, propre à réchauffer et à ranimer l'appétit ; uni à l'armagnac, on le disait tonique et réconfortant des froidures.","c":"User d'oranges non traitées et n'employer que le zeste, en évitant le ziste blanc qui amène une amertume rêche. Laisser mûrir le vin plusieurs semaines, puis servir frais à l'apéritif.","d":"« D'orange et d'armagnac la noce gasconne, un soleil d'hiver au verre rayonne. »"},"vn-vin-d-epines":{"h":"Le vin d'épines, ou troussepinette dans bien des terroirs, se prépare à la fin du printemps avec les jeunes pousses tendres du prunellier, l'épine noire des haies. Cette coutume paysanne accompagnait jadis les travaux de mai, quand on cueillait les bourgeons avant qu'ils ne durcissent. Chaque campagne en gardait sa formule, jalousement transmise de génération en génération.","p":"Les pousses de prunellier étaient réputées astringentes et toniques, propres à resserrer et fortifier ; on prêtait au vin d'épines une vertu apéritive et un effet bienfaisant sur la digestion.","c":"Cueillir les pousses bien tendres, d'un vert clair, avant qu'elles ne se lignifient. Une macération mesurée suffit, car les pousses libèrent vite leur amertume ; servir frais après un repos prolongé.","d":"« Pousse de mai cueillie à la haie, au creux de l'hiver te désaltère. »"},"vn-vin-de-feuilles-de-cassis-au-vin-blanc":{"h":"La feuille de cassis, plus discrète que la baie, fut longtemps employée seule pour ses émanations résineuses et musquées qui rappellent le bourgeon. Les jardiniers la cueillaient au plein de la végétation, lorsque le feuillage embaume au moindre froissement. Mariée au vin blanc, elle donne une boisson verte et fraîche, prisée des amateurs de saveurs végétales.","p":"La feuille de cassis était réputée diurétique et apéritive, et l'on en prêtait l'usage contre les douleurs des articulations. On la tenait aussi pour un dépuratif léger, propre à la saison chaude.","c":"Récolter les feuilles jeunes et saines par temps sec, à l'écart des routes. Préférer un vin blanc nerveux et peu boisé qui laisse parler le parfum de la feuille ; servir bien frais.","d":"« Feuille froissée sous les doigts du jardinier, au blanc léger rend son parfum altier. »"},"vn-vin-de-feuilles-de-cassis-au-vin-rouge":{"h":"Cette variante au vin rouge épouse la même tradition des vins de feuilles de cassis, mais sur une base plus charpentée et colorée. Le cassis, dont le nom vient de l'ancien casse-noir des herbiers, est une plante des jardins du Nord et de l'Est où l'on tire parti de chaque partie de l'arbrisseau. Le rouge accentue les notes de fruit et habille la feuille d'une profondeur que le blanc n'offre point.","p":"Les feuilles de cassis passaient pour soulager les rhumatismes et soutenir les reins par leur action diurétique. On les tenait pour toniques et favorables à la circulation des humeurs.","c":"Choisir un vin rouge souple et fruité, sans tanins trop rudes qui masqueraient la feuille. Laisser macérer le temps qu'il faut, filtrer avec soin et servir frais, légèrement rafraîchi.","d":"« Au rouge profond la feuille se fond, plus d'un terroir y trouve son fond. »"},"vn-vin-de-feuilles-de-merisier":{"h":"Le merisier, ou cerisier sauvage des bois, donne des feuilles plus rustiques que celles du cerisier de verger, mais tout aussi parfumées d'amande. Les bûcherons et les gens de forêt en faisaient un vin de circonstance, tirant de l'arbre sa part de plaisir quand le bois servait surtout au menuisier. Le kirsch, distillé des merises elles-mêmes, vient ici renforcer le lien entre la feuille et le fruit dont elle procède.","p":"La feuille de merisier était réputée pour son parfum de noyau, qu'on disait stomachique et propre à réveiller l'appétit. Comme tout ce qui tient de l'amande amère, ce parfum se respecte et se dose, car il procède de composés à n'employer qu'avec modération.","c":"Cueillir les feuilles dans les sous-bois, loin des chemins poussiéreux, et les sécher un instant à l'ombre. Doser le kirsch d'une main légère, puis laisser reposer afin que l'amande s'arrondisse.","d":"« Du bois sauvage la feuille s'est donnée, parfum d'amande au verre est passé. »"},"vn-vin-de-figues-1":{"h":"La figue, fruit sacré des civilisations méditerranéennes, fut l'un des premiers à être séché pour passer l'hiver, gorgé de sucre et de soleil. Cette recette, conduite par la levure et les acides plutôt que par le vin, relève de l'art ancien de la fermentation domestique, où chaque ménage faisait son vin de fruits secs. La figue sèche, riche en sucres, fournit au ferment une matière généreuse propre à donner une boisson ambrée.","p":"La figue était réputée adoucissante, nourrissante et bienfaisante pour la poitrine ; on la tenait pour laxative douce et réconfortante des estomacs fatigués. On en faisait volontiers des pectoraux contre la toux.","c":"Choisir des figues sèches moelleuses et non traitées, et veiller à la propreté des récipients pour que la fermentation soit franche. Surveiller le travail du ferment, puis soutirer et laisser le vin se clarifier en lieu frais.","d":"« Figue de soleil au ferment confiée, en vin doré l'été s'est gardé. »"},"vn-vin-de-figues-2":{"h":"Cette seconde manière, plus simple, fait macérer la figue sèche dans le vin avec un bâton de cannelle, à la façon des vins de liqueur du pourtour méditerranéen. La cannelle, écorce venue des Indes par les routes des épices, accompagne depuis toujours les fruits sucrés des conserves et des vins de fête. L'union de la figue et de l'épice évoque les douceurs orientales des banquets d'autrefois.","p":"La figue passait pour pectorale et adoucissante, et la cannelle pour stomachique et réchauffante ; ensemble, on les tenait pour un cordial favorable à la digestion des repas copieux.","c":"Préférer des figues sèches non sulfitées et n'employer qu'un bâton de cannelle pour ne pas couvrir le fruit. Sucrer selon le goût, à la fin, et servir le vin frais après un repos d'au moins quelques semaines.","d":"« Figue et cannelle au flacon mariées, parfum d'Orient au soir versé. »"},"vn-vin-de-fleurs-d-acacia-robinier":{"h":"Les grappes blanches et odorantes du robinier, que l'usage nomme à tort acacia, fleurissent au mois de mai et embaument les abords des villages. Introduit d'Amérique par le jardinier Jean Robin, dont l'arbre garde le nom savant, le robinier offre des fleurs que l'on frit en beignets ou que l'on fait macérer en vins doux. Leur parfum suave, proche du miel et de la fleur d'oranger, ne dure qu'une saison brève qu'il faut saisir au vol.","p":"La fleur de robinier était réputée adoucissante et légèrement calmante ; on la tenait pour favorable à l'estomac. On n'emploiera que les fleurs, car l'écorce, les feuilles et les gousses de cet arbre sont tenues pour toxiques et ne doivent jamais entrer dans la préparation.","c":"Cueillir les grappes fraîchement écloses, par temps sec, et n'utiliser que les fleurs détachées de la rafle. La macération sera courte pour garder l'arôme floral ; servir le vin bien frais, relevé de son trait de miel d'acacia.","d":"« Grappe de mai au parfum éphémère, qui sait la cueillir en garde l'hiver. »"},"vn-vin-rouge-de-framboises":{"h":"La framboise, ronce des montagnes que les Anciens appelaient le « fruit de l'Ida », fut longtemps cueillie sauvage avant d'entrer dans les jardins. Son parfum fragile s'accommode mal de la conservation, aussi les ménagères en faisaient-elles vins et ratafias pour en prolonger la saison. Sur un vin rouge de Bordeaux, elle compose une boisson profonde et vineuse, riche en couleur et en arôme.","p":"La framboise était réputée rafraîchissante et propre à apaiser la soif des fébricitants ; on lui prêtait des vertus toniques et un effet bienfaisant sur l'estomac. On la tenait aussi pour favorable au cœur, d'où son rang de cordial.","c":"Choisir des framboises bien mûres et parfumées, triées de tout fruit gâté qui aigrirait l'ensemble. Un vin rouge fruité et souple convient mieux qu'un cru trop tannique ; filtrer avec douceur pour ne pas troubler la robe.","d":"« Framboise des ronces au Bordeaux unie, d'un rouge profond le verre est empli. »"},"vn-vin-blanc-de-framboises":{"h":"Sur un vin blanc, la framboise révèle une tout autre figure : claire, rosée et délicate, comme un soupçon d'été en bouteille. Cette préparation appartient aux ratafias clairs que l'on offrait aux dames et aux visiteurs de marque, par leur teinte avenante et leur parfum suave. Le blanc, peu coloré, laisse pleinement s'exprimer la fraîcheur du fruit.","p":"La framboise passait pour rafraîchissante et apéritive, et l'on en faisait volontiers un sirop contre l'ardeur des fièvres. Unie au blanc, on la tenait pour un agréable tonique des temps chauds.","c":"N'employer que des framboises bien mûres pour obtenir une belle couleur rosée sans recourir à l'artifice. Préférer un vin blanc sec et fruité, et conserver le vin au frais et à l'abri de la lumière, qui ternit sa teinte.","d":"« Au blanc la framboise prête sa rougeur, soupçon d'été versé pour le buveur. »"},"vn-vin-de-framboises-a-l-ancienne":{"h":"Cette recette à l'ancienne perpétue la manière des vieux celliers, où l'on faisait macérer un grand bol de framboises dans le bon vin rouge de la maison. C'est le vin des dimanches et des veillées, transmis sans mesures précises, à l'œil et au goût, comme savaient le faire les aïeules. Il témoigne d'un temps où le ratafia de fruits tenait lieu de douceur dans les foyers modestes.","p":"La framboise était tenue pour cordiale et réconfortante, propre à réjouir le cœur et à soutenir les forces. Le vin ainsi parfumé passait pour un fortifiant doux, qu'on offrait aux visiteurs et aux convalescents.","c":"Employer des framboises gorgées de soleil et un vin rouge franc, sans excès de bois. Laisser macérer longuement, à la manière d'antan, puis filtrer sur une étamine et servir frais, en compagnie.","d":"« À l'ancienne au cellier patiente, le vin de framboise se bonifie et tente. »"},"vn-vin-de-feuilles-de-framboisier":{"h":"La feuille de framboisier, longtemps moins prisée que son fruit, tenait pourtant une place de choix dans les armoires des matrones et des herbières de campagne. On la cueillait au printemps, avant la montée en fruit, pour la faire sécher au grenier et la garder à portée de main toute l'année. Sa saveur, légèrement astringente et verte, rappelle le thé et trahit sa parenté avec la ronce des bois.","p":"L'infusion de feuilles de framboisier était traditionnellement réputée tonique et resserrante, recommandée aux femmes pour adoucir les maux propres à leur état. On lui prêtait aussi des vertus rafraîchissantes et fortifiantes pour les convalescents.","c":"Cueillir les feuilles jeunes et saines, à l'écart des chemins poussiéreux, et les laisser flétrir un jour avant la mise en macération pour atténuer l'amertume. Servir frais, après plusieurs semaines de repos et une filtration soignée sur étamine.","d":"« Feuille de mai vaut mieux que fruit d'été, qui la garde n'est jamais démuni. »"},"vn-vin-rouge-de-genievre":{"h":"Le genièvre, baie bleu-noir du genévrier, parfume les celliers d'Europe depuis l'Antiquité, où l'on brûlait ses rameaux pour assainir l'air des demeures. Son nom a donné celui du gin et du genièvre flamand, mais bien avant ces eaux-de-vie, on glissait ses baies dans le vin pour le relever d'un parfum résineux et poivré. Les bergers en mâchaient pour se réchauffer la bouche par temps de froidure.","p":"La baie de genévrier était tenue pour souverainement diurétique et stomachique, propre à réveiller l'appétit et à dégager les humeurs lourdes. On la disait amie de l'estomac fatigué par les chairs grasses.","c":"N'employer que les baies bien mûres, d'un noir profond, en écrasant légèrement chacune pour libérer l'arôme sans amertume excessive. Un repos prolongé arrondit la note résineuse, parfois mordante les premiers jours.","d":"« Qui mâche genièvre au matin, garde l'estomac alerte et le pas certain. »"},"vn-vin-blanc-de-genievre":{"h":"Marié au vin blanc plutôt qu'au rouge, le genièvre révèle une facette plus claire et plus florale, où la résine se fait dentelle. Dans les pays du Nord, on tenait le genévrier pour un arbuste protecteur, planté au seuil des maisons pour écarter les maléfices et les fièvres. Sa baie, longue à mûrir sur deux ou trois saisons, passait pour concentrer la patience de l'arbre.","p":"On prêtait à cette baie des vertus apéritives et carminatives, capables de réchauffer les entrailles froides et de chasser les flatulences. Elle était volontiers conseillée aux estomacs paresseux, en petite quantité seulement.","c":"Choisir un vin blanc sec et nerveux, qui soutiendra la fraîcheur des baies sans s'effacer. Filtrer avec patience, car le genièvre laisse un dépôt fin qu'il faut savoir abandonner au fond du flacon.","d":"« Genièvre en vin clair, fièvre prend le large et froidure se perd. »"},"vn-vin-blanc-de-gentiane":{"h":"La grande gentiane jaune des montagnes, dont on arrache la longue racine à la force du bras, donne l'amertume la plus noble des liqueurs d'altitude. Son nom évoquerait un ancien roi d'Illyrie qui aurait, dit-on, vanté ses mérites, mais les arracheurs de gentiane des hauts pâturages n'en avaient cure : ils savaient seulement qu'une bonne racine se paie de sueur. On la confond parfois, à ses dépens, avec le vénéneux vératre, et la prudence du cueilleur s'imposait toujours.","p":"La racine de gentiane était réputée le plus puissant des amers toniques, ouvrant l'appétit et fortifiant les estomacs débiles. On la recommandait aux las et aux pâles, en doses mesurées, car son amertume est sans pareille.","c":"Ne mettre qu'un fragment de racine, tant son amertume domine : trop de gentiane rend le breuvage imbuvable. Laisser reposer longtemps et goûter souvent, pour retirer la racine dès que l'amer est franc et plaisant.","d":"« Racine amère au mois d'août, redonne faim et chasse le dégoût. »"},"vn-vin-rouge-de-gentiane":{"h":"Au vin rouge, la gentiane prend une robe plus sombre et une amertume charpentée, à la manière des amers que l'on sirote au comptoir des bourgs montagnards. La racine, qui peut s'enfoncer profond dans la terre maigre des alpages, met de longues années à grossir avant qu'on l'arrache. Les anciens la séchaient en rondelles enfilées comme des chapelets, pour la garder d'une saison à l'autre.","p":"On tenait ce breuvage pour un fébrifuge et un fortifiant des grandes lassitudes, capable de relever les forces après les fièvres. Son amertume était dite stimulante pour la rate et le foie engourdis.","c":"Préférer une racine bien sèche et parfumée, et la doser avec retenue dans un vin rouge déjà corsé. Servir à température de cave, en très petit verre, comme un amer de fin de repas.","d":"« Gentiane en rouge au soir versée, ranime le sang et la veillée. »"},"vn-vin-de-gingembre":{"h":"Le gingembre, rhizome venu d'Orient par les routes des épices, enflamma l'imagination des marchands médiévaux qui le payaient au poids de l'argent. On l'employait aussi bien en cuisine qu'en médecine, et il entrait dans nombre de vins épicés destinés à réchauffer les corps. Sa chair piquante et parfumée passait pour porter en elle la chaleur des contrées lointaines d'où il venait.","p":"Le gingembre était réputé échauffant et stomachique, propre à raviver la digestion engourdie et à réveiller les ardeurs assoupies. On le disait souverain contre les froids de l'estomac et les nausées des voyageurs.","c":"Râper ou émincer finement le rhizome frais et bien ferme, en dosant selon le mordant souhaité. Un séjour de quelques semaines suffit à diffuser son feu ; au-delà, le piquant peut prendre le dessus sur le fruit.","d":"« Gingembre au vin, chaleur soudaine, réchauffe le ventre et la semaine. »"},"vn-vin-de-guignolet":{"h":"Le guignolet doit son nom à la guigne, petite cerise douce à longue queue que l'on cueillait dès les premières chaleurs de l'été. En Anjou comme ailleurs, on en tirait des vins et des ratafias prisés des fins becs, où la cerise se mêlait volontiers à une pointe de noyau. Sa chair fondante et sucrée en fait l'une des cerises les plus aimables pour la macération.","p":"La guigne était tenue pour rafraîchissante et légèrement laxative, amie des sangs échauffés par la saison chaude. On la croyait propre à adoucir l'humeur et à réjouir le cœur des mélancoliques.","c":"Choisir des guignes bien mûres et charnues, dénoyautées avec soin si l'on craint l'amertume du noyau. Quelques noyaux concassés ajoutés à la macération relèvent toutefois le parfum d'une note d'amande, à n'en mettre qu'une poignée.","d":"« Guigne d'été dans le verre tombée, change la peine en gaieté. »"},"vn-vin-de-kiwis":{"h":"Le kiwi, longtemps appelé groseille de Chine avant de prendre le nom de l'oiseau des antipodes, ne gagna nos vergers que tardivement, mais sa chair verte et acidulée séduisit vite les amateurs de nouveautés. Originaire des vallées chinoises, il fut acclimaté loin de chez lui, où on le para d'un nom plus exotique encore. Sa saveur fraîche, mi-fruit mi-agrume, en fait un hôte vif et désaltérant des vins de fruits.","p":"On vante volontiers ce fruit pour sa fraîcheur et sa pulpe gorgée de suc, jadis appréciée pour soutenir les convalescents et entretenir la vigueur. Sa note acidulée était jugée propre à rafraîchir les bouches lasses.","c":"Préférer des kiwis mûrs mais encore fermes, pelés et tranchés, en relevant l'ensemble d'un zeste d'orange pour appuyer le parfum. Filtrer avec soin, car la chair tendre rend un jus trouble qu'il faut clarifier patiemment.","d":"« Fruit d'outre-mer en vin baigné, donne au palais un air d'été. »"},"vn-vin-de-litchis":{"h":"Le litchi, fruit à l'écorce rugueuse et rose qui cache une chair nacrée et parfumée, fut chéri des cours impériales d'Orient bien avant d'atteindre nos tables. On raconte que des coureurs s'épuisaient à le porter frais jusqu'au palais, tant son parfum se fanait vite après la cueillette. Sa douceur florale, presque rosée, en fait un fruit de fête et de mets précieux.","p":"Le litchi passait pour un fruit doux et réconfortant, propre à réjouir les sens et à apaiser les chaleurs intérieures. On le tenait pour nourrissant et aimable aux estomacs délicats, sans excès.","c":"Choisir des litchis bien parfumés à l'écorce intacte, pelés et dénoyautés juste avant la macération pour préserver l'arôme fugace. Une gousse de vanille et un trait de rhum ambré soutiennent sa note florale sans l'écraser.","d":"« Litchi cueilli, parfum pressé, qui tarde trop l'a vu passer. »"},"vn-vin-de-mai":{"h":"Le vin de mai, ou maitrank des pays rhénans, doit tout à l'aspérule odorante, cette modeste herbe des sous-bois que l'on cueille au moment où elle fleurit, au cœur du printemps. Une fois flétrie, elle exhale un parfum de foin coupé et de vanille qui embaume le vin de toute sa fraîcheur. On en faisait la boisson des premières belles soirées, quand la forêt reverdit.","p":"L'aspérule était réputée cordiale et apaisante, amie du sommeil et des cœurs agités. On la maniait toutefois avec mesure, car son parfum vient de la coumarine, substance qui, à forte dose, devient nuisible : la sagesse voulait qu'on n'en abusât point.","c":"Cueillir l'aspérule juste avant ou au début de la floraison, et la laisser légèrement flétrir un jour pour libérer son arôme. Ne pas prolonger la macération au-delà de quelques heures à un ou deux jours, sous peine d'un goût trop herbacé et d'un excès de coumarine.","d":"« Herbe de mai brièvement trempée, parfume le verre sans le charger. »"},"vn-vin-blanc-de-mirabelle":{"h":"La mirabelle, petite prune dorée des vergers lorrains, mûrit dans la chaleur d'août en se couvrant de taches de rousseur. On la mangeait à pleine main au pied de l'arbre, on en faisait des tartes, des confitures et des eaux-de-vie réputées. Sa douceur mielleuse et son parfum caractéristique en font l'une des prunes les plus recherchées pour les liqueurs.","p":"La mirabelle bien mûre était tenue pour douce et légèrement laxative, rafraîchissante pour les sangs échauffés de la canicule. On la jugeait nourrissante et bienfaisante aux humeurs paresseuses.","c":"Ne retenir que des mirabelles parfaitement mûres et parfumées, fendues et dénoyautées pour libérer leur suc. Un vin blanc sec contrebalance heureusement leur sucre ; laisser reposer assez longtemps pour que le parfum se fonde.","d":"« Prune dorée d'août recueillie, vaut au verre tout son soleil. »"},"vn-vin-de-noyer":{"h":"La feuille de noyer, à l'odeur puissante et balsamique quand on la froisse, servait jadis à parfumer les vins toniques de fin d'été. On la cueillait par les chaudes journées, à l'heure où l'arbre exhale le plus fort, et l'on disait qu'il ne faisait pas bon s'endormir sous son ombrage trop lourd. Ses feuilles tachent les doigts d'un brun tenace, signe de la sève active qu'elles renferment.","p":"La feuille de noyer était réputée dépurative et fortifiante, employée en vins amers pour relever le ton des estomacs et purifier les humeurs. On lui prêtait aussi des vertus contre les fatigues languissantes, en usage modéré.","c":"Cueillir les feuilles jeunes et saines au plein de l'été, et n'en mettre qu'une mesure raisonnable, car leur arôme est envahissant. Une macération brève suffit à colorer et parfumer le vin sans le rendre trop âpre.","d":"« Feuille de noyer en plein midi, donne au vin sa force et son défi. »"},"vn-vin-de-noix-aux-epices":{"h":"La noix verte, cueillie avant la Saint-Jean alors que sa coque est encore tendre au couteau, est la matière reine des vins de noix de nos campagnes. On la ramassait au cœur de l'été, à l'époque où le brou tache les mains d'un noir indélébile, et chaque maison gardait jalousement sa recette. Son amertume verte et résineuse, peu à peu domptée par le sucre et le temps, donne un vin sombre et profond.","p":"Le brou de noix vert était traditionnellement tenu pour tonique, stomachique et dépuratif, propre à fortifier les convalescents et à relever l'appétit. On le maniait avec mesure, car son astringence est rude au palais des délicats.","c":"Cueillir les noix bien vertes vers la fin juin, quand l'aiguille les traverse encore aisément, et les couper en quartiers en se protégeant les mains. Le breuvage demande de longs mois de repos pour que l'âpreté du brou se mue en velours.","d":"« Noix verte à la Saint-Jean fendue, fait le vin noir et la santé venue. »"},"vn-vin-de-noix-aux-clous-de-girofle":{"h":"Mariée au clou de girofle, la noix verte gagne une chaleur épicée qui rappelle les vins de garde des veillées d'automne. Le girofle, bouton séché d'un arbre des îles lointaines, valait jadis une petite fortune et signait les tables opulentes. Ensemble, le brou âpre et l'épice ardente composent un vin corsé que l'on tirait pour les grandes occasions.","p":"Le brou de noix était réputé fortifiant et apéritif, et le girofle passait pour échauffant et antiseptique, propre à assainir la bouche et à réveiller la digestion. On tenait l'alliance des deux pour réconfortante en saison froide, à petites doses.","c":"Choisir des noix bien vertes et tendres, et n'ajouter que quelques clous de girofle, dont le parfum domine vite l'ensemble. Filtrer après une longue macération, puis laisser vieillir encore en flacon pour assouplir l'âpreté du brou.","d":"« Noix et girofle au flacon mariés, font le vin grave et l'hiver allégé. »"},"vn-vin-de-peches":{"h":"Le vin de feuilles de pêcher, que l'on nomme parfois 'vin de brou de pêche', appartient à ces apéritifs paysans nés dans les vergers du Sud-Ouest et du Centre, où l'on ne laissait rien perdre de l'arbre. Ce sont les feuilles, et non le fruit, qui parfument la liqueur : froissées, elles dégagent un arôme d'amande qui rappelle la parenté botanique du pêcher avec l'amandier. On les cueillait à l'automne, à la chute, quand la sève s'était retirée dans le bois.","p":"Les feuilles de pêcher étaient autrefois réputées vermifuges et apaisantes, et l'on en tirait des tisanes pour calmer la toux. On se gardera toutefois de doses immodérées : la feuille renferme des composés cyanogènes parents de ceux de l'amande amère, et le breuvage demande d'être goûté avec mesure.","c":"Choisir des feuilles saines, d'un pêcher non traité, et les laisser infuser le temps voulu sans excès afin que l'amertume ne domine pas. Servir frais, en apéritif, après un repos d'au moins une lune pour que le parfum d'amande s'arrondisse.","d":"« Feuille de pêcher en automne tombée, en flacon ressuscite l'été. »"},"vn-vin-de-pissenlits":{"h":"Le pissenlit, dont le nom cru trahit la vieille renommée diurétique de la plante, fleurit la première les prairies d'avril ; en plusieurs provinces on l'appelle 'dent-de-lion' pour ses feuilles dentelées. Sa fleur d'or servait depuis longtemps à parfumer vins et confitures, et l'on guettait sa cueillette comme une fête du printemps. Les abeilles s'en repaissent dès les premiers beaux jours, ce qui valut à la plante son surnom de premier miel des prés.","p":"On prêtait au pissenlit des vertus dépuratives et 'pour ouvrir le foie', et la racine torréfiée passait pour un tonique de saison. La fleur même est sans danger, mais il convient d'écarter avec soin tout pédoncule vert, dont le latex amer gâterait le breuvage.","c":"Cueillir les fleurs par temps sec et bien ouvertes, vers midi, et ne retenir que les pétales d'or en chassant le vert. Filtrer avec patience avant la mise en flacon ; le repos de quelques mois adoucit la verdeur première.","d":"« Fleur de pissenlit cueillie au matin clair, vaut bouteille d'or pour qui sait la faire. »"},"vn-vin-de-pousses-d-epine":{"h":"Le vin de pousses d'épine, ou 'épine noire', se prépare des jeunes rejets du prunellier que l'on cueille au mois de mai, quand ils sont encore tendres et rougeoyants. C'est une tradition vivace de l'Ouest et du Poitou, où chaque maison gardait sa proportion d'épines comme un secret. Le prunellier, buisson des haies épineuses, donnait jadis le bois des fléaux et des cannes, et ses pousses la couleur grenat de cet apéritif.","p":"Les pousses d'épine noire passaient pour astringentes et toniques, et l'on en faisait des décoctions 'pour resserrer les humeurs'. On les emploie cependant en raison gardée : comme tout ce qui touche au prunellier, elles renferment des principes cyanogènes, et le vin se boit en petit verre d'apéritif, non au gobelet.","c":"Cueillir les jeunes pousses au printemps, avant le durcissement, et les laisser macérer le temps prescrit pour que la couleur prenne sans excès d'amertume. Filtrer soigneusement et laisser vieillir : ce vin gagne à patienter une année entière.","d":"« Qui en mai l'épine sait cueillir, à la Toussaint la verra mûrir. »"},"vn-vin-de-prunelles":{"h":"La prunelle est le fruit bleu-noir du prunellier, petit et âpre, que les gelées d'automne attendrissent et adoucissent. On la ramassait après les premières blanches, car le froid brisait son astringence rude ; faute de gelée, les anciens passaient les fruits au gel artificiel du cellier. Ancêtre sauvage de nos prunes cultivées, elle a parfumé liqueurs et vins des campagnes bien avant que la quetsche ne règne sur les vergers.","p":"La prunelle était tenue pour astringente et rafraîchissante, bonne 'pour le ventre dévoyé', et sa pulpe entrait dans les remèdes domestiques. On évitera toutefois de broyer les noyaux dans la préparation, car leur amande amère recèle un principe cyanhydrique dont il faut se défier.","c":"Attendre que les prunelles aient connu le gel pour qu'elles cèdent leur sucre, et préférer les fruits bien mûrs et souples. Ne pas écraser les noyaux ; servir frais après un repos prolongé qui arrondit la dureté du fruit.","d":"« Prunelle d'avant gelée n'est que pierre, prunelle d'après est confiture en verre. »"},"vn-vin-de-prele":{"h":"La prêle, que l'on nommait 'queue-de-cheval' ou 'asperge des sables', est une plante très ancienne, descendante des grandes forêts primitives, dont la tige cannelée crisse sous la dent par sa silice. Les artisans s'en servaient pour polir l'étain et le bois, d'où son autre nom d'herbe à récurer. Au jardin des simples, elle figurait parmi les plantes des terrains humides que l'on récoltait au plein de l'été.","p":"La prêle était réputée reminéralisante et 'bonne pour les os', et on lui prêtait des vertus pour resserrer les saignements. On la manie cependant avec prudence : la plante contient une substance qui détruit la thiamine, et seule la prêle des champs, soigneusement reconnue, doit être employée, jamais sa cousine des marais.","c":"N'employer que la prêle des champs bien identifiée, cueillie jeune en début d'été, fraîche ou correctement séchée. Le miel corrige la verdeur minérale du breuvage ; servir en petite mesure, à titre de tonique.","d":"« Prêle des champs au flacon mise, donne à l'os la pierre assise. »"},"vn-vin-de-roses":{"h":"Le vin de roses puise dans une tradition très ancienne, des roseraies de Perse aux jardins monastiques d'Occident, où la rose passait pour la reine des fleurs. Les pétales de roses rouges, les plus parfumés, donnaient au vin une couleur de rubis pâle et un nez délicat. On distillait jadis l'eau de rose pour la table et la toilette, et le vin en était la version conviviale, servie aux noces et aux fêtes de mai.","p":"La rose était tenue pour cordiale et astringente, propre à 'réjouir le cœur' et à raffermir les gencives ; on en faisait des conserves et des miels rosats. La fleur est franche et sans péril, pourvu qu'elle vienne d'un rosier non traité, à l'écart des routes poudreuses.","c":"Cueillir les pétales le matin, à pleine ouverture, et n'ôter que le talon blanc à la base, plus amer. Une pointe de jus de citron ravive la couleur ; servir bien frais, en apéritif léger.","d":"« Rose au matin cueillie en son éclat, met dans le verre un parfum qui ne ment pas. »"},"vn-vin-de-trouspinette":{"h":"La trouspinette, ou 'troussepinette', est l'apéritif emblématique de la Vendée et du Bas-Poitou, dont chaque famille revendique la recette véritable. Son nom rustique évoquerait les épines que l'on troussait dans les haies au temps de la cueillette. Ici, ce sont les feuilles de pêcher qui font l'âme du breuvage, mariées au vin rouge et à l'eau-de-vie selon un usage transmis de génération en génération.","p":"On disait la trouspinette apéritive et stomachique, bonne 'pour ouvrir l'appétit' avant le repas dominical. Comme la feuille de pêcher s'apparente à l'amande amère par ses composés cyanogènes, on la consomme en petit verre, à la mesure d'un apéritif et non d'un vin de table.","c":"Choisir des feuilles d'un pêcher sain, cueillies hors saison de traitement, et respecter la durée de macération sans la prolonger outre mesure. Mettre en bouteille après filtration et laisser mûrir quelques mois ; servir frais.","d":"« À la trouspinette de l'aïeule, chaque maison se croit la seule. »"},"vn-vin-d-eucalyptus":{"h":"L'eucalyptus, géant venu des terres australes, ne gagna les jardins du Midi méditerranéen qu'à une époque assez récente, où on le planta volontiers pour assainir les marais. Sa feuille coriace, d'un vert glauque, exhale un parfum balsamique et camphré reconnaissable entre tous. On en parfumait sirops et boissons d'hiver pour leur fraîcheur mentholée et pénétrante.","p":"La feuille d'eucalyptus était réputée 'pour la poitrine' et les voies du souffle, et on l'inhalait volontiers contre les rhumes. Son huile essentielle est toutefois puissante et peut se révéler toxique à forte dose : on n'en met qu'une mesure modeste, et le vin se déguste en petit verre.","c":"Employer des feuilles bien sèches et aromatiques, broyées juste avant la macération pour libérer leur baume. Doser la feuille avec retenue, car son parfum domine vite ; servir frais après un repos qui en assouplit la vigueur.","d":"« Feuille d'eucalyptus au flacon dormante, à l'hiver venu rend l'haleine plus franche. »"},"vn-vin-d-hysope":{"h":"L'hysope, dont le nom remonte aux langues anciennes de la Méditerranée, est une plante des jardins de simples citée de longue date pour ses fleurs bleues et son parfum amer et résineux. On la trouvait au verger des cloîtres, où les moines la cultivaient parmi les aromatiques sacrées. Sa réputation traversa les siècles comme herbe de purification autant que de cuisine.","p":"L'hysope passait pour pectorale et stomachique, bonne 'pour dégager la poitrine' et faciliter la digestion des mets gras. Mais son huile renferme une substance, la pinocamphone, qui à forte dose peut provoquer des accidents nerveux : on n'en emploie qu'une faible mesure, et la prudence commande d'en réduire la part, comme le veut d'ailleurs la recette.","c":"Cueillir l'hysope en fleur, par temps sec, et n'en mettre qu'une petite quantité parmi les autres plantes pour qu'elle ne domine ni n'alourdisse. Servir en très petite mesure, à titre de digestif, après une longue macération.","d":"« L'hysope à pleine main est poison sournois, à la pointe des doigts elle réjouit le foie. »"},"vn-vin-rouge-d-orange":{"h":"Le vin d'orange, fierté des cuisines de Provence et du Languedoc, naît de l'écorce d'oranges parfumées que l'on fait macérer dans le vin avec l'eau-de-vie et le sucre. C'est un apéritif de fin d'hiver, préparé quand les agrumes abondent et que l'orange amère, dite bigarade, donne le meilleur de son zeste. La pratique de parfumer le vin par les écorces d'agrumes remonte aux tables épicées du Moyen Âge.","p":"Le zeste d'orange était réputé tonique et stomachique, propre à 'réchauffer l'estomac' et à relever les esprits avant le repas. Le fruit est sans péril, mais on choisira des oranges non traitées, car c'est l'écorce et son huile parfumée qui font tout le breuvage.","c":"Préférer des oranges non traitées, voire amères, et ne prélever que le zeste coloré en évitant la peau blanche, amère sans finesse. Un bâton de cannelle apporte la rondeur médiévale ; servir frais après plusieurs semaines de repos.","d":"« Écorce d'orange au vin rouge mariée, fait d'un soir d'hiver une soirée dorée. »"},"vn-vin-blanc-d-orange":{"h":"Ce vin d'orange à robe claire se construit sur un blanc liquoreux et les zestes d'oranges parfumées, rehaussés d'une eau-de-vie noble venue de Gascogne ou de Charente. Il appartient à la même famille provençale que son cousin rouge, mais joue la douceur et la lumière. Les armagnacs et cognacs y apportent une signature de terroir, et l'on aimait les marier aux agrumes dans les apéritifs de maison.","p":"L'écorce d'orange douce passait pour cordiale et digestive, et l'on prêtait à son parfum la vertu de 'remonter les esprits abattus'. Sans danger, le zeste demande seulement de provenir d'un fruit non traité pour livrer pleinement son huile odorante.","c":"Ne lever que les zestes de deux oranges bien mûres et non traitées, sans le blanc amer, et accorder la macération d'une cannelle discrète. Servir frais, presque glacé, à l'apéritif ou sur un dessert aux agrumes.","d":"« Vin blanc d'orange en flacon serré, garde le soleil pour les jours voilés. »"},"vn-vin-rouge-epice-chaud-glogi-finlande":{"h":"Le glögi est le vin chaud épicé des pays nordiques, cousin finlandais du glühwein et du glögg suédois, que l'on sert fumant aux longues nuits de l'avent. On y plonge amandes pelées et raisins secs, qui gonflent dans la coupe et se mangent à la cuillère une fois le vin bu. Girofle et cannelle, épices précieuses jadis venues de loin, en font le cœur parfumé et la chaleur réconfortante.","p":"Les épices royales du glögi, girofle et cannelle, étaient réputées réchauffer le corps et fortifier l'estomac contre les froids rigoureux. Le breuvage est cordial par tradition, et la vodka qui le renforce invite à le servir en mesure raisonnable, par les soirs d'hiver.","c":"Chauffer le vin avec les épices sans jamais le porter à ébullition, pour ne pas chasser l'arôme ni l'alcool. Déposer amandes et raisins au fond des coupes avant de verser ; servir brûlant, dans des verres épais qui tiennent la chaleur.","d":"« Quand dehors la neige fait son nid, dedans fume le bon glögi. »"},"vn-vin-fortifiant-au-persil":{"h":"Le persil, herbe potagère des plus anciennes, ornait déjà les tables de l'Antiquité méditerranéenne où on le tressait en couronnes autant qu'on le mettait au pot. Ce vin fortifiant relève d'une longue tradition domestique de toniques de printemps, où l'on faisait macérer le persil frais dans le vin avec miel et vinaigre. C'était le remède de bonne femme par excellence, transmis comme un trésor de cuisine.","p":"Le persil était tenu pour diurétique et reminéralisant, 'bon pour le sang' et pour soutenir les convalescents affaiblis. L'herbe est familière et bénigne en cuisine ; on l'emploie ici en brins mesurés, tiges et feuilles, pour un vin pris à titre de fortifiant et non de boisson de table.","c":"Choisir un persil bien vert et frais, une vingtaine de brins avec leurs tiges, et le hacher grossièrement avant macération. Le miel d'acacia et le trait de balsamique en équilibrent l'âpreté ; servir en petit verre, frais.","d":"« Brin de persil au vin laissé reposer, rend force à qui sait l'apprécier. »"},"vn-vin-tonique-du-pape":{"h":"Le 'vin du pape' désigne ces vins toniques richement épicés que les apothicaires et les maisons monastiques composaient pour relever les forces, à la manière des hypocras de jadis. Girofle, cannelle, macis, cardamome et gingembre y dessinent un bouquet d'épices de chambre dignes des banquets médiévaux. Les baies de genièvre et le miel d'acacia y ajoutent la note de garrigue et la douceur du rucher.","p":"Ce mélange d'épices nobles était réputé tonique et cordial, propre à 'réchauffer les sangs' et à soutenir les estomacs paresseux. On y use du genièvre avec retenue, car en forte dose il est âpre aux reins ; le vin se boit en petit verre, comme un cordial de fête.","c":"Concasser légèrement les épices et le genièvre pour libérer leurs huiles, et râper le gingembre frais juste avant la macération. Le miel d'acacia, plus fin que le sucre, en arrondit le feu ; servir frais ou à peine chambré, en digestif.","d":"« Aux épices du pape, point de tristesse qui tienne, un dé suffit, la liesse vient. »"}};

NOTES_SITE['lq-alkermes'] = {
  p: "L'alkermes passait pour un cordial souverain, réconfortant le cœur et relevant les esprits abattus ; les Médicis en firent une de leurs « liqueurs de longue vie ». La cochenille qui la teignait d'écarlate n'y apporte que la couleur, non la vertu.",
  c: "Exposer le bocal au plein soleil active l'extraction des épices ; la cochenille, facultative, se dose avec parcimonie pour un rouge profond sans amertume. Se sert glacé, en très petits verres.",
  d: "« Rouge des Médicis, longue vie au logis. »"
};
